fn validate_root_metadata_gate_options(
    require_complete_root_metadata: bool,
    extract_metadata_xml: bool,
    selected_file_names: &BTreeSet<String>,
) -> Result<()> {
    if !require_complete_root_metadata {
        return Ok(());
    }
    if !extract_metadata_xml {
        bail!("--require-complete-root-metadata requires --extract-metadata-xml");
    }
    if !selected_file_names.is_empty() {
        bail!(
            "--require-complete-root-metadata requires a full Config export without --file-name or --file-name-list"
        );
    }
    Ok(())
}

const fn root_metadata_inventory_scope(
    plan: MssqlExportInventoryPlan,
) -> RootMetadataInventoryScope {
    match plan.root_metadata_scope() {
        MssqlExportInventoryScope::Full => RootMetadataInventoryScope::Full,
        MssqlExportInventoryScope::Scoped => RootMetadataInventoryScope::Scoped,
    }
}

const fn source_asset_inventory_scope(
    plan: MssqlExportInventoryPlan,
) -> SourceAssetCompletenessScope {
    match plan.source_asset_scope() {
        MssqlExportInventoryScope::Full => SourceAssetCompletenessScope::Full,
        MssqlExportInventoryScope::Scoped => SourceAssetCompletenessScope::Scoped,
    }
}

/// Projects an adapter-owned plan once for either row-processing boundary.
/// Eager and streamed paths must not independently recreate this decision.
const fn inventory_scopes(
    plan: MssqlExportInventoryPlan,
) -> (RootMetadataInventoryScope, SourceAssetCompletenessScope) {
    (
        root_metadata_inventory_scope(plan),
        source_asset_inventory_scope(plan),
    )
}

/// Exports a provider-neutral storage image through the same family decoders
/// used by the direct MSSQL path. The input contains no SQL connection or
/// process assumptions; callers may obtain it from CF or another adapter.
pub fn export_storage_image_to_source(
    image: &StorageImage,
    output_dir: &Path,
    overwrite: bool,
    source_version: InfobaseConfigSourceVersion,
) -> Result<StorageImageSourceExportReport> {
    let plan = StorageExportPlan::from_image(image);
    let mut rows = Vec::with_capacity(plan.records().len());
    let mut decoder_names = BTreeSet::new();
    for record in plan.records() {
        if !decoder_names.insert(record.logical_name()) {
            bail!(
                "storage records with distinct keys reuse decoder name `{}`",
                record.logical_name()
            );
        }
        let payload = record.packed_payload().with_context(|| {
            format!(
                "failed to materialize storage record `{}`",
                record.logical_key()
            )
        })?;
        let data_size = i64::try_from(payload.len()).with_context(|| {
            format!(
                "storage record `{}` is too large for the legacy row boundary",
                record.logical_key()
            )
        })?;
        rows.push(ConfigRow {
            file_name: record.logical_name().to_owned(),
            part_no: 0,
            data_size,
            binary_hex: encode_hex_lower(payload.as_ref()),
        });
    }

    prepare_output_dir(output_dir, overwrite)?;
    // Reuses the same eligibility rule the streamed MSSQL pipeline uses
    // (`MssqlExportInventoryPlan::config_dump_info_eligible`,
    // `src/adapters/mssql_legacy.rs`) instead of re-deriving the
    // write_binary_rows/extract_module_text/extract_metadata_xml AND-chain
    // by hand: a `cf export` always processes the full, unfiltered storage
    // image as the current configuration (no row selection, metadata XML
    // and module text both extracted, no raw binary rows written), so it is
    // eligible for ConfigDumpInfo.xml exactly when the streamed path would
    // also consider it eligible.
    let config_dump_info_plan = MssqlExportInventoryPlan::new(
        MssqlConfigurationTableRole::Current,
        false,
        true,
        true,
        false,
        true,
    );
    let dumped = dump_table_rows_with_options_mode(
        output_dir,
        MssqlConfigurationTableRole::Current.sql_name(),
        rows,
        false,
        false,
        true,
        true,
        source_version,
        RootMetadataInventoryScope::Scoped,
        SourceAssetCompletenessScope::Scoped,
        true,
        false,
        config_dump_info_plan.config_dump_info_eligible(),
    )?;
    let successful = dumped
        .rows
        .into_iter()
        .map(|manifest| (manifest.file_name.clone(), manifest))
        .collect::<BTreeMap<_, _>>();
    let failed = dumped
        .failed_rows
        .into_iter()
        .map(|failure| (failure.file_name, failure.message))
        .collect::<BTreeMap<_, _>>();

    let mut entries = Vec::with_capacity(plan.records().len());
    for record in plan.records() {
        let packed_bytes = record.packed_bytes().with_context(|| {
            format!(
                "failed to measure storage record `{}`",
                record.logical_key()
            )
        })?;
        if let Some(message) = failed.get(record.logical_name()) {
            entries.push(StorageExportEntryReport::failed(
                record,
                packed_bytes,
                message.clone(),
            ));
            continue;
        }

        let outputs = successful
            .get(record.logical_name())
            .into_iter()
            .flat_map(|manifest| {
                [
                    manifest.metadata_xml_path.as_ref(),
                    manifest.module_text_path.as_ref(),
                    manifest.source_asset_path.as_ref(),
                ]
            })
            .flatten()
            .cloned()
            .collect::<Vec<_>>();
        if outputs.is_empty() {
            entries.push(StorageExportEntryReport::opaque(
                record,
                packed_bytes,
                "no legacy family decoder recognized this storage entry",
            ));
        } else {
            entries.push(StorageExportEntryReport::supported(
                record,
                packed_bytes,
                outputs,
            ));
        }
    }

    let files_written = count_output_files(output_dir)?;

    Ok(StorageImageSourceExportReport {
        output_dir: output_dir.to_path_buf(),
        source_version: source_version.as_str().to_owned(),
        files_written,
        storage: StorageExportReport::new(image, &plan, entries),
    })
}

#[allow(dead_code)]
fn dump_table_rows_eager(
    sqlcmd: &Path,
    server: &str,
    user: Option<&str>,
    password: Option<&str>,
    database: &str,
    inventory_plan: MssqlExportInventoryPlan,
    selected_file_names: &BTreeSet<String>,
    output_dir: &Path,
    write_binary_rows: bool,
    inflate: bool,
    extract_module_text: bool,
    extract_metadata_xml: bool,
) -> Result<DumpedTable> {
    let table = inventory_plan.role().sql_name();
    let (inventory_scope, source_asset_scope) = inventory_scopes(inventory_plan);
    let rows = fetch_rows(
        sqlcmd,
        server,
        user,
        password,
        database,
        table,
        selected_file_names,
    )?;
    dump_table_rows_with_options_mode(
        output_dir,
        table,
        rows,
        write_binary_rows,
        inflate,
        extract_module_text,
        extract_metadata_xml,
        InfobaseConfigSourceVersion::V2_20,
        inventory_scope,
        source_asset_scope,
        false,
        false,
        inventory_plan.config_dump_info_eligible(),
    )
}

struct DumpedTable {
    rows: Vec<MssqlDumpRowManifest>,
    failed_rows: Vec<FailedDumpRow>,
    binary_bytes: usize,
    inflated_rows: usize,
    module_text_rows: usize,
    metadata_xml_rows: usize,
    source_asset_rows: usize,
    source_assets: SourceAssetCompletenessReport,
    metadata_root_inventory: RootMetadataInventoryReport,
    timings: MssqlDumpTimingReport,
}

struct FailedDumpRow {
    file_name: String,
    message: String,
}

struct DumpedRow {
    manifest: MssqlDumpRowManifest,
    binary_bytes: usize,
    inflated_rows: usize,
    module_text_rows: usize,
    metadata_xml_rows: usize,
    source_asset_rows: usize,
    source_assets: SourceAssetCompletenessReport,
    metadata_xml_diagnostic: Option<MetadataSourceExtractionDiagnostic>,
    timings: MssqlDumpTimingReport,
}

struct DumpRowContext<'a> {
    output_dir: &'a Path,
    table: &'a str,
    source_version: InfobaseConfigSourceVersion,
    write_binary_rows: bool,
    inflate: bool,
    extract_module_text: bool,
    extract_metadata_xml: bool,
    collect_all_source_asset_diagnostics: bool,
    refused_output_paths: &'a ReferenceOutputCollisions,
    module_text_paths: &'a BTreeMap<String, PathBuf>,
    source_assets: &'a BTreeMap<String, SourceAsset>,
    metadata_texts_by_file_name: &'a BTreeMap<&'a str, &'a MetadataTextRow>,
    command_refs: &'a BTreeMap<String, String>,
    metadata_refs: &'a BTreeMap<String, MetadataCommandReference>,
    type_index: &'a BTreeMap<String, String>,
    type_index_collisions: &'a BTreeSet<String>,
    moxel_generated_types: &'a BTreeMap<String, String>,
    dcs_type_index: &'a DcsTypeIndex,
    object_refs: &'a BTreeMap<String, String>,
    object_ref_resolutions: &'a BTreeMap<String, MetadataObjectReferenceResolution>,
    metadata_object_refs: &'a BTreeMap<String, String>,
    configuration_root_object_refs: &'a BTreeMap<String, String>,
    recalculation_refs: &'a BTreeMap<String, CalculationRecalculationReference>,
    root_recalculation_refs: &'a CalculationRootRecalculationReferences,
    predefined_item_refs: &'a BTreeMap<String, String>,
    /// The object reference index a form is parsed against: the plain one with
    /// the owner-qualified predefined-item names laid over it.  A design-time
    /// reference in a form names a predefined item of an arbitrary object, and
    /// a predefined item is not a metadata object, so the plain index cannot
    /// name it.  The two key spaces are disjoint -- a predefined-item key is
    /// `owner-value:<owner>:<uuid>`, never a bare identifier -- so every
    /// existing lookup through this index answers exactly as before.
    form_object_refs: &'a BTreeMap<String, String>,
    role_rights_object_refs: &'a BTreeMap<String, String>,
    metadata_order: &'a BTreeMap<String, usize>,
    field_refs: &'a BTreeMap<String, String>,
    field_type_refs: &'a Arc<BTreeMap<String, String>>,
    information_register_field_refs: &'a InformationRegisterFieldReferenceIndex,
    information_register_master_dimensions: &'a Arc<InformationRegisterMasterDimensionIndex>,
    functional_option_refs: &'a BTreeMap<String, String>,
    help_refs: &'a BTreeMap<String, String>,
    standalone_refs: &'a StandaloneContentReferences,
    form_refs: &'a BTreeMap<String, FormSourceReference>,
    template_refs: &'a BTreeMap<String, TemplateSourceReference>,
    subsystem_refs: &'a BTreeMap<String, SubsystemSourceReference>,
    file_names: &'a BTreeSet<String>,
    body_owners: &'a BTreeMap<String, BodyOwnerSourceReference>,
    configuration_module_groups: &'a BTreeSet<String>,
}

