#[allow(clippy::too_many_arguments)]
fn dump_table_rows_with_options_mode(
    output_dir: &Path,
    table: &str,
    rows: Vec<ConfigRow>,
    write_binary_rows: bool,
    inflate: bool,
    extract_module_text: bool,
    extract_metadata_xml: bool,
    source_version: InfobaseConfigSourceVersion,
    inventory_scope: RootMetadataInventoryScope,
    source_asset_scope: SourceAssetCompletenessScope,
    continue_on_row_error: bool,
    collect_all_source_asset_diagnostics: bool,
    generate_config_dump_info: bool,
) -> Result<DumpedTable> {
    let table_dir = output_dir.join(table);
    if write_binary_rows {
        fs::create_dir_all(&table_dir)
            .with_context(|| format!("failed to create {}", table_dir.display()))?;
    }
    let inflated_dir = output_dir.join(format!("{table}_inflated"));
    if inflate {
        fs::create_dir_all(&inflated_dir)
            .with_context(|| format!("failed to create {}", inflated_dir.display()))?;
    }
    let module_text_dir = output_dir.join(format!("{table}_module_text"));
    // Only the legacy raw/debug fallback (see `dump_table_row_bytes`) ever
    // writes directly under this root; every canonical module path creates
    // its own parent directory lazily right before its own `fs::write`. A
    // strict source export (`write_binary_rows == false`) never takes that
    // fallback, so pre-creating an empty `{table}_module_text` directory
    // here would be a stray artifact with no platform counterpart.
    if extract_module_text && write_binary_rows {
        fs::create_dir_all(&module_text_dir)
            .with_context(|| format!("failed to create {}", module_text_dir.display()))?;
    }
    let file_names_owned = rows
        .iter()
        .map(|row| row.file_name.clone())
        .collect::<BTreeSet<_>>();
    let needs_standalone_refs =
        file_names_have_standalone_content_asset(file_names_owned.iter().map(String::as_str));
    let needs_source_layout_refs = !write_binary_rows;
    let standalone_required_refs = if needs_standalone_refs && !extract_metadata_xml {
        standalone_content_reference_uuids_from_config_rows(&rows)
    } else {
        BTreeSet::new()
    };
    let metadata_audit = if extract_metadata_xml
        || extract_module_text
        || needs_standalone_refs
        || needs_source_layout_refs
    {
        build_metadata_text_rows_audited(&rows)
    } else {
        MetadataTextRowsAudit::default()
    };
    let metadata_texts = &metadata_audit.rows;
    let metadata_texts_by_file_name = metadata_texts
        .iter()
        .map(|row| (row.file_name.as_str(), row))
        .collect::<BTreeMap<_, _>>();
    let recalculation_refs = if extract_metadata_xml {
        build_calculation_recalculation_reference_index(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let root_recalculation_refs = if extract_metadata_xml {
        build_calculation_root_recalculation_reference_index(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let module_text_paths = if extract_module_text {
        module_body_paths_from_texts(&rows, &metadata_texts)
    } else {
        BTreeMap::new()
    };
    let command_refs = if extract_metadata_xml {
        build_command_interface_reference_index_from_texts(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let metadata_refs = if extract_metadata_xml {
        build_metadata_command_reference_index_from_texts(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let MetadataTypeIndexes {
        references: type_index,
        reference_collisions: type_index_collisions,
        dcs: dcs_type_index,
    } = if extract_metadata_xml || needs_source_layout_refs {
        build_metadata_type_indexes_from_texts(&metadata_texts)
    } else {
        MetadataTypeIndexes::default()
    };
    let moxel_generated_types =
        build_moxel_generated_type_index(&type_index, &type_index_collisions);
    let refs_for_standalone =
        extract_metadata_xml || needs_standalone_refs || needs_source_layout_refs;
    let form_refs = if refs_for_standalone {
        build_complete_form_source_reference_index(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let template_refs = if refs_for_standalone {
        build_template_source_reference_index_from_texts(&rows, &metadata_texts)
    } else {
        BTreeMap::new()
    };
    let subsystem_refs = if refs_for_standalone {
        build_subsystem_source_reference_index_from_texts(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let MetadataObjectReferenceIndexes {
        references: object_refs,
        resolutions: object_ref_resolutions,
    } = if extract_metadata_xml || needs_source_layout_refs {
        build_metadata_object_reference_indexes_from_texts(&metadata_texts)
    } else if needs_standalone_refs {
        MetadataObjectReferenceIndexes::from_legacy(
            &build_standalone_object_reference_index_from_texts(
                &metadata_texts,
                &standalone_required_refs,
                &form_refs,
                &template_refs,
                &subsystem_refs,
            ),
        )
    } else {
        MetadataObjectReferenceIndexes::default()
    };
    let configuration_root_object_refs = if extract_metadata_xml {
        build_configuration_root_object_reference_index_from_texts(&metadata_texts, &object_refs)
    } else {
        BTreeMap::new()
    };
    let role_rights_object_refs =
        build_role_rights_object_reference_index(&object_refs, &form_refs);
    let metadata_order = if extract_metadata_xml || needs_source_layout_refs {
        build_metadata_order_index_from_texts(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let field_refs = if extract_metadata_xml {
        build_metadata_field_reference_index_from_texts(&metadata_texts)
    } else {
        BTreeMap::new()
    };
    let field_type_refs = Arc::new(if extract_metadata_xml {
        build_metadata_field_type_reference_index_from_texts(metadata_texts, &type_index)
    } else {
        BTreeMap::new()
    });
    let information_register_field_refs = if extract_metadata_xml {
        let defined_type_value_owner_refs =
            build_defined_type_value_owner_reference_index_from_texts(&metadata_texts, &type_index);
        build_information_register_field_reference_index_from_texts(
            &metadata_texts,
            &type_index,
            &defined_type_value_owner_refs,
        )
    } else {
        BTreeMap::new()
    };
    let information_register_master_dimensions = Arc::new(if extract_metadata_xml {
        build_information_register_master_dimension_index_from_texts(
            metadata_texts,
            &type_index,
            &object_refs,
            &form_refs,
            source_version == InfobaseConfigSourceVersion::V2_21,
        )
    } else {
        InformationRegisterMasterDimensionIndex::new()
    });
    let functional_option_refs = if extract_metadata_xml {
        build_functional_option_reference_index_from_texts(
            &metadata_texts,
            &object_refs,
            &form_refs,
            &template_refs,
            &subsystem_refs,
        )
    } else {
        BTreeMap::new()
    };
    let source_assets = source_asset_paths_with_indexes(
        &rows,
        &metadata_texts,
        &command_refs,
        &metadata_refs,
        &object_refs,
        &field_refs,
        &type_index,
        &form_refs,
        &template_refs,
        &subsystem_refs,
    );
    let source_asset_diagnostics =
        build_form_owner_resolution_diagnostics_from_texts(&metadata_texts);
    let rows_by_file_name = rows
        .iter()
        .map(|row| (row.file_name.as_str(), row))
        .collect::<BTreeMap<_, _>>();
    let source_asset_discovery_misses = source_asset_discovery_misses(
        &metadata_texts,
        &file_names_owned.iter().map(String::as_str).collect(),
        &rows_by_file_name,
        &command_refs,
        &metadata_refs,
        &object_refs,
        &field_refs,
        &type_index,
        &subsystem_refs,
        &form_refs,
        &template_refs,
    );
    let help_refs = if extract_metadata_xml {
        build_help_reference_index(&object_refs, &form_refs, &template_refs, &subsystem_refs)
    } else {
        BTreeMap::new()
    };
    let standalone_refs = if needs_standalone_refs
        && source_assets
            .values()
            .any(|asset| matches!(asset.kind, SourceAssetKind::StandaloneContent))
    {
        if extract_metadata_xml {
            build_standalone_content_references(
                &metadata_texts,
                &configuration_root_object_refs,
                &form_refs,
                &template_refs,
                &subsystem_refs,
            )
        } else {
            build_standalone_content_references_for_uuids(
                &metadata_texts,
                &standalone_required_refs,
                &build_configuration_root_object_reference_index_from_texts(
                    &metadata_texts,
                    &object_refs,
                ),
                &form_refs,
                &template_refs,
                &subsystem_refs,
            )
        }
    } else {
        StandaloneContentReferences::default()
    };
    let body_owners = if extract_metadata_xml || needs_source_layout_refs {
        build_body_owner_source_index_from_texts(&metadata_texts, &subsystem_refs)
    } else {
        BTreeMap::new()
    };
    let needs_predefined_item_refs =
        predefined_data_needs_item_references(&file_names_owned, &body_owners);
    let predefined_item_refs = if needs_predefined_item_refs {
        build_predefined_item_reference_index(&rows, &body_owners, &type_index, &object_refs)?
    } else {
        BTreeMap::new()
    };
    let metadata_value_owner_file_names = eager_metadata_value_owner_file_names(&metadata_texts);
    let mut metadata_value_owner_ids = selected_metadata_predefined_owner_ids(
        &metadata_texts,
        &metadata_value_owner_file_names,
        &type_index,
        &object_refs,
        &body_owners,
    );
    metadata_value_owner_ids.extend(business_process_flowchart_predefined_owner_ids(
        &rows,
        &business_process_flowchart_file_names(&metadata_texts),
        &type_index,
        &object_refs,
        &body_owners,
    ));
    let metadata_value_body_owners = body_owners
        .iter()
        .filter(|(uuid, _)| metadata_value_owner_ids.contains(*uuid))
        .map(|(uuid, owner)| (uuid.clone(), owner.clone()))
        .collect::<BTreeMap<_, _>>();
    let metadata_value_predefined_item_refs = build_predefined_item_reference_index(
        &rows,
        &metadata_value_body_owners,
        &type_index,
        &object_refs,
    )?;
    let mut form_object_refs = object_refs.clone();
    form_object_refs.extend(build_form_predefined_item_reference_index(
        &rows,
        &body_owners,
        &type_index,
        &object_refs,
    ));
    let mut metadata_object_refs = object_refs.clone();
    extend_metadata_owner_value_references(&mut metadata_object_refs, &predefined_item_refs)?;
    extend_metadata_owner_value_references(
        &mut metadata_object_refs,
        &metadata_value_predefined_item_refs,
    )?;
    let configuration_module_groups = configuration_module_groups(&file_names_owned);
    // A path claimed by two storage entries is a refusal about those entries,
    // not about the export: both are withheld and named, and everything that
    // claims its path alone is still produced.
    let mut source_assets = source_assets;
    let mut source_asset_diagnostics = source_asset_diagnostics;
    for (file_name, message) in
        colliding_source_asset_paths(&source_assets, &source_asset_diagnostics)
    {
        source_assets.remove(&file_name);
        source_asset_diagnostics.insert(file_name, message);
    }
    // Forms, templates, subsystems, and canonical module bodies each resolve
    // their own output path through their own reference index, never through
    // `source_assets`, so two rows that resolve to the identical path there
    // are invisible to the check above and would otherwise race a writer. The
    // same row uuid can be a claimant on more than one route at once (a
    // form's body is both a source asset and a module-text owner, each with
    // its own target path), so refusal is tracked per route rather than by a
    // single flat file-name key: refusing a colliding module path must not
    // also withhold that row's unrelated, non-colliding source asset.
    let mut reference_collisions = colliding_reference_output_paths(
        &source_assets,
        &form_refs,
        &template_refs,
        &subsystem_refs,
        &module_text_paths,
    );
    for (file_name, message) in std::mem::take(&mut reference_collisions.source_assets) {
        if source_assets.remove(&file_name).is_some() {
            source_asset_diagnostics.insert(file_name, message);
        }
    }

    let context = DumpRowContext {
        output_dir,
        table,
        source_version,
        write_binary_rows,
        inflate,
        extract_module_text,
        extract_metadata_xml,
        collect_all_source_asset_diagnostics,
        refused_output_paths: &reference_collisions,
        module_text_paths: &module_text_paths,
        source_assets: &source_assets,
        metadata_texts_by_file_name: &metadata_texts_by_file_name,
        command_refs: &command_refs,
        metadata_refs: &metadata_refs,
        type_index: &type_index,
        type_index_collisions: &type_index_collisions,
        moxel_generated_types: &moxel_generated_types,
        dcs_type_index: &dcs_type_index,
        object_refs: &object_refs,
        object_ref_resolutions: &object_ref_resolutions,
        metadata_object_refs: &metadata_object_refs,
        configuration_root_object_refs: &configuration_root_object_refs,
        recalculation_refs: &recalculation_refs,
        root_recalculation_refs: &root_recalculation_refs,
        predefined_item_refs: &predefined_item_refs,
        form_object_refs: &form_object_refs,
        role_rights_object_refs: &role_rights_object_refs,
        metadata_order: &metadata_order,
        field_refs: &field_refs,
        field_type_refs: &field_type_refs,
        information_register_field_refs: &information_register_field_refs,
        information_register_master_dimensions: &information_register_master_dimensions,
        functional_option_refs: &functional_option_refs,
        help_refs: &help_refs,
        standalone_refs: &standalone_refs,
        form_refs: &form_refs,
        template_refs: &template_refs,
        subsystem_refs: &subsystem_refs,
        file_names: &file_names_owned,
        body_owners: &body_owners,
        configuration_module_groups: &configuration_module_groups,
    };
    let dumped_rows = parallel::install(|| {
        rows.par_iter()
            .map(|row| dump_table_row(&context, row))
            .collect::<Vec<_>>()
    })?;

    let mut manifests = Vec::with_capacity(dumped_rows.len());
    let mut binary_bytes = 0;
    let mut inflated_rows = 0;
    let mut module_text_rows = 0;
    let mut metadata_xml_rows = 0;
    let mut source_asset_rows = 0;
    let mut source_asset_completeness = SourceAssetCompletenessReport::default();
    let mut metadata_extraction_diagnostics = BTreeMap::new();
    let mut failed_rows = Vec::new();
    for (row, dumped) in rows.iter().zip(dumped_rows) {
        let dumped = match dumped {
            Ok(dumped) => dumped,
            Err(error) if continue_on_row_error => {
                failed_rows.push(FailedDumpRow {
                    file_name: row.file_name.clone(),
                    message: format!("{error:#}"),
                });
                continue;
            }
            Err(error) => return Err(error),
        };
        binary_bytes += dumped.binary_bytes;
        inflated_rows += dumped.inflated_rows;
        module_text_rows += dumped.module_text_rows;
        metadata_xml_rows += dumped.metadata_xml_rows;
        source_asset_rows += dumped.source_asset_rows;
        source_asset_completeness.merge(&dumped.source_assets);
        if let Some(diagnostic) = dumped.metadata_xml_diagnostic {
            metadata_extraction_diagnostics.insert(row.file_name.clone(), diagnostic);
        }
        manifests.push(dumped.manifest);
    }
    for (source_row_id, reason) in &source_asset_discovery_misses {
        source_asset_completeness.record_affected_reason(source_asset_audit_entry(
            table,
            source_row_id,
            source_assets.get(source_row_id),
            format!("source_asset.discovery.{reason}"),
            "source_asset_candidate_missing",
        ));
    }
    for (source_row_id, reason) in &metadata_audit.misses {
        source_asset_completeness.record_affected_reason(source_asset_audit_entry(
            table,
            source_row_id,
            source_assets.get(source_row_id),
            format!(
                "source_asset.discovery.metadata_decode_miss.{}",
                reason.as_str()
            ),
            "source_asset_candidate_missing",
        ));
    }
    for source_row_id in source_asset_diagnostics.keys() {
        source_asset_completeness.record_affected_reason(source_asset_audit_entry(
            table,
            source_row_id,
            source_assets.get(source_row_id),
            "source_asset.form_owner_resolution.uncertain".to_string(),
            "source_asset_identity_uncertain",
        ));
    }
    source_asset_completeness.finish_inventory(
        source_asset_scope,
        source_asset_discovery_misses.is_empty()
            && metadata_audit.misses.is_empty()
            && source_asset_diagnostics.is_empty(),
        source_assets.len() + source_asset_discovery_misses.len() + metadata_audit.misses.len(),
    );

    if generate_config_dump_info {
        // Every real compiler-produced full-snapshot CF carries a `versions`
        // service record (confirmed across the T1/T2/T3 native-evidence
        // corpora); a storage image without one is not presenting a
        // versioned snapshot inventory at all, so ConfigDumpInfo.xml is
        // simply not applicable rather than an error -- clean-room and
        // partial images are first-class inputs for this offline exporter.
        // A `versions` record that IS present but structurally corrupt
        // (multipart, duplicated, undecodable) still fails the export:
        // fail-closed applies to content we claim to decode.
        let mut versions_blob: Option<Vec<u8>> = None;
        for row in &rows {
            if row.file_name != "versions" {
                continue;
            }
            if row.part_no != 0 {
                bail!("Config versions row has unsupported PartNo {}", row.part_no);
            }
            if versions_blob.is_some() {
                bail!("Config versions row was fetched more than once");
            }
            versions_blob = Some(
                decode_hex(&row.binary_hex)
                    .with_context(|| "Config versions row is not valid hex".to_string())?,
            );
        }

        let mut emitted_source_asset_paths = BTreeMap::<String, PathBuf>::new();
        for manifest in &manifests {
            let Some(path) = manifest.source_asset_path.as_ref().map(PathBuf::from) else {
                continue;
            };
            if let Some(previous) =
                emitted_source_asset_paths.insert(manifest.file_name.clone(), path.clone())
                && previous != path
            {
                bail!(
                    "Config source asset {} was emitted to both {} and {}",
                    manifest.file_name,
                    previous.display(),
                    path.display()
                );
            }
        }
        // `dump_table_rows_with_options_mode`'s in-memory `Vec<ConfigRow>`
        // callers are the CF export path (`export_storage_image_to_source`)
        // and test helpers built the same way — never the streamed MSSQL SQL
        // path (that one calls `write_config_dump_info` directly from
        // `dump_table_rows_streamed` with `VersionsBlobOrigin::MssqlConfigTable`
        // and the `Fail` partial-inventory policy).
        if let Some(versions_blob) = versions_blob {
            write_config_dump_info(
                output_dir,
                source_version,
                &versions_blob,
                VersionsBlobOrigin::CfStorageImage,
                ConfigDumpInfoPartialInventoryPolicy::Skip,
                ConfigDumpInfoInventory {
                    file_names: &file_names_owned,
                    metadata_texts: &metadata_audit.rows,
                    object_refs: &object_refs,
                    form_refs: &form_refs,
                    template_refs: &template_refs,
                    subsystem_refs: &subsystem_refs,
                    module_text_paths: &module_text_paths,
                    source_assets: &source_assets,
                    emitted_source_asset_paths: &emitted_source_asset_paths,
                    configuration_module_groups: &configuration_module_groups,
                },
            )?;
        }
    }

    let metadata_root_inventory = if extract_metadata_xml {
        let indexed_roots = configuration_root_metadata_file_names_from_texts(&metadata_audit.rows);
        let (candidates, candidate_set_complete) = selected_root_metadata_candidates(
            &metadata_audit,
            &file_names_owned,
            inventory_scope,
            indexed_roots.as_ref(),
        );
        audit_root_metadata_inventory(
            &candidates,
            &metadata_audit,
            &manifests,
            &metadata_extraction_diagnostics,
            inventory_scope,
            candidate_set_complete,
        )
    } else {
        RootMetadataInventoryReport::default()
    };
    Ok(DumpedTable {
        rows: manifests,
        failed_rows,
        binary_bytes,
        inflated_rows,
        module_text_rows,
        metadata_xml_rows,
        source_asset_rows,
        source_assets: source_asset_completeness,
        metadata_root_inventory,
        timings: MssqlDumpTimingReport::default(),
    })
}

fn dump_table_rows_streamed(
    sqlcmd: &Path,
    bcp: &Path,
    server: &str,
    user: Option<&str>,
    password: Option<&str>,
    database: &str,
    selected_file_names: &BTreeSet<String>,
    inventory_plan: MssqlExportInventoryPlan,
    output_dir: &Path,
    write_binary_rows: bool,
    inflate: bool,
    extract_module_text: bool,
    extract_metadata_xml: bool,
    source_version: InfobaseConfigSourceVersion,
    collect_all_source_asset_diagnostics: bool,
) -> Result<DumpedTable> {
    let table = inventory_plan.role().sql_name();
    let generate_config_dump_info = inventory_plan.config_dump_info_eligible();
    let (inventory_scope, source_asset_scope) = inventory_scopes(inventory_plan);
    let table_dir = output_dir.join(table);
    if write_binary_rows {
        fs::create_dir_all(&table_dir)
            .with_context(|| format!("failed to create {}", table_dir.display()))?;
    }
    let inflated_dir = output_dir.join(format!("{table}_inflated"));
    if inflate {
        fs::create_dir_all(&inflated_dir)
            .with_context(|| format!("failed to create {}", inflated_dir.display()))?;
    }
    let module_text_dir = output_dir.join(format!("{table}_module_text"));
    // See the identical comment in `dump_table_rows_with_options_mode`: only
    // the legacy raw/debug fallback ever writes here, and strict source
    // exports never take it.
    if extract_module_text && write_binary_rows {
        fs::create_dir_all(&module_text_dir)
            .with_context(|| format!("failed to create {}", module_text_dir.display()))?;
    }

    let headers_started = Instant::now();
    let headers = fetch_row_headers(
        sqlcmd,
        server,
        user,
        password,
        database,
        table,
        selected_file_names,
    )?;
    let fetch_headers_ms = elapsed_ms(headers_started);
    let mut timings = MssqlDumpTimingReport {
        fetch_headers_ms,
        fetch_headers_sqlcmd_ms: fetch_headers_ms,
        ..MssqlDumpTimingReport::default()
    };
    let prepare_started = Instant::now();
    let mut file_names = headers
        .iter()
        .map(|row| row.file_name.clone())
        .collect::<BTreeSet<_>>();
    let needs_standalone_refs =
        file_names_have_standalone_content_asset(file_names.iter().map(String::as_str));
    let standalone_body_file_names = if needs_standalone_refs && !extract_metadata_xml {
        standalone_content_asset_file_names(file_names.iter().map(String::as_str))
    } else {
        BTreeSet::new()
    };
    let metadata_file_names = file_names
        .iter()
        .filter(|file_name| !file_name.contains('.'))
        .cloned()
        .collect::<BTreeSet<_>>();
    let metadata_fetch_started = Instant::now();
    let mut metadata_fetch_used_bcp = false;
    let needs_source_layout_refs = !write_binary_rows;
    let mut metadata_rows = if extract_metadata_xml
        || extract_module_text
        || needs_standalone_refs
        || needs_source_layout_refs
    {
        if selected_file_names.is_empty() {
            metadata_fetch_used_bcp = true;
            fetch_metadata_rows_bcp(sqlcmd, bcp, server, user, password, database, table)?
        } else if metadata_file_names.is_empty() {
            Vec::new()
        } else {
            metadata_fetch_used_bcp = true;
            fetch_config_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &metadata_file_names,
            )?
        }
    } else {
        Vec::new()
    };
    let elapsed = elapsed_ms(metadata_fetch_started);
    timings.prepare_metadata_fetch_ms += elapsed;
    if metadata_fetch_used_bcp {
        timings.prepare_metadata_fetch_bcp_ms += elapsed;
    }
    let standalone_body_rows = if !standalone_body_file_names.is_empty() {
        let metadata_fetch_started = Instant::now();
        let rows = fetch_config_rows_bcp(
            sqlcmd,
            bcp,
            server,
            user,
            password,
            database,
            table,
            &standalone_body_file_names,
        )?;
        let elapsed = elapsed_ms(metadata_fetch_started);
        timings.prepare_metadata_fetch_ms += elapsed;
        timings.prepare_metadata_fetch_bcp_ms += elapsed;
        rows
    } else {
        Vec::new()
    };
    let standalone_required_refs = if needs_standalone_refs && !extract_metadata_xml {
        standalone_content_reference_uuids_from_config_rows(&standalone_body_rows)
    } else {
        BTreeSet::new()
    };
    let selected_metadata_rows = if extract_metadata_xml
        || extract_module_text
        || needs_standalone_refs
        || needs_source_layout_refs
    {
        metadata_rows
            .iter()
            .filter(|row| metadata_file_names.contains(&row.file_name))
            .cloned()
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let metadata_texts_started = Instant::now();
    let selected_metadata_audit = if extract_metadata_xml
        || extract_module_text
        || needs_standalone_refs
        || needs_source_layout_refs
    {
        build_metadata_text_rows_audited(&selected_metadata_rows)
    } else {
        MetadataTextRowsAudit::default()
    };
    let selected_metadata_texts = &selected_metadata_audit.rows;
    timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
    let selected_configuration_index_needs =
        selected_configuration_source_asset_index_needs_with_metadata(
            &file_names,
            &selected_metadata_texts,
        );
    let selected_metadata_index_needs = if selected_configuration_index_needs.is_none() {
        selected_metadata_source_reference_index_needs(&selected_metadata_texts)
    } else {
        None
    };
    let broad_metadata_indexes_without_command_refs = selected_file_names.is_empty()
        || selected_configuration_index_needs
            .is_some_and(SourceReferenceIndexNeeds::needs_broad_metadata_without_command_refs)
        || selected_metadata_index_needs
            .is_some_and(SourceReferenceIndexNeeds::needs_broad_metadata)
        || needs_standalone_refs
        || (selected_configuration_index_needs.is_none()
            && selected_metadata_index_needs.is_none()
            && selected_export_needs_broad_metadata_indexes(
                extract_module_text,
                &file_names,
                &selected_metadata_texts,
            ));
    let mut selected_configuration_body_rows = Vec::new();
    if !broad_metadata_indexes_without_command_refs
        && extract_metadata_xml
        && selected_configuration_index_needs
            .is_some_and(|needs| needs.command_refs || needs.metadata_refs)
    {
        let metadata_fetch_started = Instant::now();
        selected_configuration_body_rows = fetch_config_rows_bcp(
            sqlcmd,
            bcp,
            server,
            user,
            password,
            database,
            table,
            &file_names,
        )?;
        let elapsed = elapsed_ms(metadata_fetch_started);
        timings.prepare_metadata_fetch_ms += elapsed;
        timings.prepare_metadata_fetch_bcp_ms += elapsed;
    }
    let selected_command_interface_refs =
        if selected_configuration_index_needs.is_some_and(|needs| needs.command_refs) {
            selected_configuration_command_interface_command_refs(&selected_configuration_body_rows)
        } else {
            Some(BTreeSet::new())
        };
    let mut broad_metadata_indexes = broad_metadata_indexes_without_command_refs;
    if selected_command_interface_refs.is_none() {
        broad_metadata_indexes = true;
    }
    if broad_metadata_indexes && !selected_file_names.is_empty() {
        let metadata_fetch_started = Instant::now();
        metadata_rows =
            fetch_metadata_rows_bcp(sqlcmd, bcp, server, user, password, database, table)?;
        let elapsed = elapsed_ms(metadata_fetch_started);
        timings.prepare_metadata_fetch_ms += elapsed;
        timings.prepare_metadata_fetch_bcp_ms += elapsed;
    } else if extract_metadata_xml
        && selected_configuration_index_needs
            .is_some_and(|needs| needs.command_refs || needs.metadata_refs)
    {
        let metadata_fetch_started = Instant::now();
        let targeted_metadata_file_names =
            selected_configuration_direct_metadata_reference_file_names(
                &selected_configuration_body_rows,
            );
        let mut metadata_fetch_used_bcp = false;
        if !targeted_metadata_file_names.is_empty() {
            metadata_fetch_used_bcp = true;
            metadata_rows = fetch_config_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &targeted_metadata_file_names,
            )?;
        }
        let elapsed = elapsed_ms(metadata_fetch_started);
        timings.prepare_metadata_fetch_ms += elapsed;
        if metadata_fetch_used_bcp {
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
        }
        if selected_configuration_index_needs.is_some_and(|needs| needs.command_refs) {
            let metadata_texts_started = Instant::now();
            let direct_metadata_texts = build_metadata_text_rows(&metadata_rows);
            let direct_command_refs =
                build_command_interface_reference_index_from_texts(&direct_metadata_texts);
            let direct_metadata_refs =
                build_metadata_command_reference_index_from_texts(&direct_metadata_texts);
            let unresolved_command_refs = unresolved_command_interface_reference_uuids(
                selected_command_interface_refs
                    .as_ref()
                    .expect("checked selected command interface refs"),
                &direct_command_refs,
                &direct_metadata_refs,
            );
            timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
            if !unresolved_command_refs.is_empty() {
                let metadata_fetch_started = Instant::now();
                let broad_metadata_rows =
                    fetch_metadata_rows_bcp(sqlcmd, bcp, server, user, password, database, table)?;
                let elapsed = elapsed_ms(metadata_fetch_started);
                timings.prepare_metadata_fetch_ms += elapsed;
                timings.prepare_metadata_fetch_bcp_ms += elapsed;
                let metadata_texts_started = Instant::now();
                let (owner_rows, resolved_uuids) = selected_owner_metadata_rows_for_uuids(
                    &broad_metadata_rows,
                    &unresolved_command_refs,
                );
                if !owner_rows.is_empty() {
                    metadata_rows = merge_config_rows_by_file_name(metadata_rows, owner_rows);
                }
                if !unresolved_command_refs.is_subset(&resolved_uuids) {
                    metadata_rows = broad_metadata_rows;
                    broad_metadata_indexes = true;
                }
                timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
            }
        }
    }
    if !selected_file_names.is_empty()
        && !broad_metadata_indexes
        && !selected_metadata_rows.is_empty()
    {
        let metadata_texts_started = Instant::now();
        let selected_form_file_names = form_metadata_file_names(&selected_metadata_rows);
        let direct_metadata_file_names = selected_metadata_direct_reference_file_names(
            &build_metadata_text_rows(&selected_metadata_rows),
        );
        timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
        if !direct_metadata_file_names.is_empty() {
            let metadata_fetch_started = Instant::now();
            let direct_metadata_rows = fetch_config_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &direct_metadata_file_names,
            )?;
            let mut direct_form_file_names = form_metadata_file_names(&direct_metadata_rows);
            direct_form_file_names.extend(selected_form_file_names.iter().cloned());
            let elapsed = elapsed_ms(metadata_fetch_started);
            timings.prepare_metadata_fetch_ms += elapsed;
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
            let resolved = direct_metadata_rows
                .iter()
                .map(|row| row.file_name.clone())
                .collect::<BTreeSet<_>>();
            let unresolved = direct_metadata_file_names
                .into_iter()
                .filter(|file_name| !resolved.contains(file_name))
                .collect::<BTreeSet<_>>();
            metadata_rows = merge_config_rows_by_file_name(metadata_rows, direct_metadata_rows);
            if !unresolved.is_empty() || !direct_form_file_names.is_empty() {
                let metadata_fetch_started = Instant::now();
                let broad_metadata_rows =
                    fetch_metadata_rows_bcp(sqlcmd, bcp, server, user, password, database, table)?;
                let elapsed = elapsed_ms(metadata_fetch_started);
                timings.prepare_metadata_fetch_ms += elapsed;
                timings.prepare_metadata_fetch_bcp_ms += elapsed;
                let metadata_texts_started = Instant::now();
                let (owner_rows, _) =
                    selected_owner_metadata_rows_for_uuids(&broad_metadata_rows, &unresolved);
                if !owner_rows.is_empty() {
                    metadata_rows = merge_config_rows_by_file_name(metadata_rows, owner_rows);
                }
                let form_owner_rows = selected_form_owner_metadata_rows(
                    &broad_metadata_rows,
                    &direct_form_file_names,
                );
                if !form_owner_rows.is_empty() {
                    metadata_rows = merge_config_rows_by_file_name(metadata_rows, form_owner_rows);
                }
                timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
            }
        } else if !selected_form_file_names.is_empty() {
            let metadata_fetch_started = Instant::now();
            let broad_metadata_rows =
                fetch_metadata_rows_bcp(sqlcmd, bcp, server, user, password, database, table)?;
            let elapsed = elapsed_ms(metadata_fetch_started);
            timings.prepare_metadata_fetch_ms += elapsed;
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
            let metadata_texts_started = Instant::now();
            let form_owner_rows =
                selected_form_owner_metadata_rows(&broad_metadata_rows, &selected_form_file_names);
            if !form_owner_rows.is_empty() {
                metadata_rows = merge_config_rows_by_file_name(metadata_rows, form_owner_rows);
            }
            timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
        }
    }
    if !selected_file_names.is_empty() && !broad_metadata_indexes {
        let fetch_selected_rows_started = Instant::now();
        let selected_body_rows = fetch_config_rows_bcp(
            sqlcmd,
            bcp,
            server,
            user,
            password,
            database,
            table,
            &file_names,
        )?;
        let elapsed = elapsed_ms(fetch_selected_rows_started);
        timings.prepare_metadata_fetch_ms += elapsed;
        timings.prepare_metadata_fetch_bcp_ms += elapsed;

        let metadata_texts_started = Instant::now();
        let direct_body_metadata_file_names =
            selected_body_direct_reference_file_names(&selected_body_rows);
        timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
        if !direct_body_metadata_file_names.is_empty() {
            let metadata_fetch_started = Instant::now();
            let direct_metadata_rows = fetch_config_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &direct_body_metadata_file_names,
            )?;
            let elapsed = elapsed_ms(metadata_fetch_started);
            timings.prepare_metadata_fetch_ms += elapsed;
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
            let resolved = direct_metadata_rows
                .iter()
                .map(|row| row.file_name.clone())
                .collect::<BTreeSet<_>>();
            let unresolved = direct_body_metadata_file_names
                .into_iter()
                .filter(|file_name| !resolved.contains(file_name))
                .collect::<BTreeSet<_>>();
            metadata_rows = merge_config_rows_by_file_name(metadata_rows, direct_metadata_rows);
            if !unresolved.is_empty() {
                let metadata_fetch_started = Instant::now();
                let broad_metadata_rows =
                    fetch_metadata_rows_bcp(sqlcmd, bcp, server, user, password, database, table)?;
                let elapsed = elapsed_ms(metadata_fetch_started);
                timings.prepare_metadata_fetch_ms += elapsed;
                timings.prepare_metadata_fetch_bcp_ms += elapsed;
                let metadata_texts_started = Instant::now();
                let (owner_rows, _) =
                    selected_owner_metadata_rows_for_uuids(&broad_metadata_rows, &unresolved);
                if !owner_rows.is_empty() {
                    metadata_rows = merge_config_rows_by_file_name(metadata_rows, owner_rows);
                }
                timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
            }
        }
    }
    let mut supplemental_owner_rows = Vec::new();
    if !selected_file_names.is_empty() && !broad_metadata_indexes && !metadata_rows.is_empty() {
        let mut known_metadata_file_names = metadata_rows
            .iter()
            .map(|row| row.file_name.clone())
            .collect::<BTreeSet<_>>();
        let mut frontier_rows = metadata_rows.clone();
        loop {
            let metadata_texts_started = Instant::now();
            let frontier_texts = build_metadata_text_rows(&frontier_rows);
            timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
            let next_metadata_file_names =
                selected_metadata_direct_reference_file_names(&frontier_texts)
                    .into_iter()
                    .filter(|file_name| !known_metadata_file_names.contains(file_name))
                    .collect::<BTreeSet<_>>();
            if next_metadata_file_names.is_empty() {
                break;
            }

            let metadata_fetch_started = Instant::now();
            let fetched_rows = fetch_config_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &next_metadata_file_names,
            )?;
            let elapsed = elapsed_ms(metadata_fetch_started);
            timings.prepare_metadata_fetch_ms += elapsed;
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
            if fetched_rows.is_empty() {
                break;
            }

            frontier_rows = fetched_rows
                .iter()
                .filter(|row| known_metadata_file_names.insert(row.file_name.clone()))
                .cloned()
                .collect::<Vec<_>>();
            if frontier_rows.is_empty() {
                break;
            }
            metadata_rows = merge_config_rows_by_file_name(metadata_rows, fetched_rows);
        }

        let metadata_texts_started = Instant::now();
        let supplemental_metadata_file_names = build_metadata_text_rows(&metadata_rows)
            .into_iter()
            .filter(|row| row.kind.as_deref() == Some("Subsystem"))
            .map(|row| row.file_name)
            .filter(|file_name| !metadata_file_names.contains(file_name))
            .collect::<BTreeSet<_>>();
        timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
        if !supplemental_metadata_file_names.is_empty() {
            let metadata_fetch_started = Instant::now();
            supplemental_owner_rows = fetch_metadata_owner_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &supplemental_metadata_file_names,
            )?;
            let elapsed = elapsed_ms(metadata_fetch_started);
            timings.prepare_metadata_fetch_ms += elapsed;
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
            file_names.extend(supplemental_metadata_file_names);
            file_names.extend(
                supplemental_owner_rows
                    .iter()
                    .map(|row| row.file_name.clone()),
            );
        }
    }

    let mut write_index_rows = rows_for_source_indexes(&headers, &selected_metadata_rows);
    if !metadata_rows.is_empty() {
        write_index_rows = merge_config_rows_by_file_name(write_index_rows, metadata_rows.clone());
    }
    if !supplemental_owner_rows.is_empty() {
        write_index_rows =
            merge_config_rows_by_file_name(write_index_rows, supplemental_owner_rows.clone());
    }
    let metadata_texts_started = Instant::now();
    let index_metadata_texts = if extract_metadata_xml
        || extract_module_text
        || needs_standalone_refs
        || needs_source_layout_refs
    {
        if broad_metadata_indexes {
            build_metadata_text_rows(&metadata_rows)
        } else if selected_configuration_index_needs.is_some() && !metadata_rows.is_empty() {
            build_metadata_text_rows(&metadata_rows)
        } else {
            build_metadata_text_rows(&selected_metadata_rows)
        }
    } else {
        Vec::new()
    };
    timings.prepare_metadata_texts_ms += elapsed_ms(metadata_texts_started);
    let reference_indexes_started = Instant::now();
    let metadata_texts_by_file_name = index_metadata_texts
        .iter()
        .map(|row| (row.file_name.as_str(), row))
        .collect::<BTreeMap<_, _>>();
    let recalculation_refs = if extract_metadata_xml {
        build_calculation_recalculation_reference_index(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    let root_recalculation_refs = if extract_metadata_xml {
        build_calculation_root_recalculation_reference_index(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };

    let module_text_paths = if extract_module_text {
        module_body_paths_from_texts(&write_index_rows, &index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    let index_part_started = Instant::now();
    let source_reference_needs = selected_configuration_index_needs
        .or(selected_metadata_index_needs)
        .unwrap_or_else(SourceReferenceIndexNeeds::full);
    let build_selected_local_refs = extract_metadata_xml && !selected_file_names.is_empty();
    let command_refs = if extract_metadata_xml
        && (source_reference_needs.command_refs || build_selected_local_refs)
    {
        build_command_interface_reference_index_from_texts(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    timings.prepare_command_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let metadata_refs = if extract_metadata_xml
        && (source_reference_needs.metadata_refs || build_selected_local_refs)
    {
        build_metadata_command_reference_index_from_texts(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    timings.prepare_metadata_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let MetadataTypeIndexes {
        references: type_index,
        reference_collisions: type_index_collisions,
        dcs: dcs_type_index,
    } = if (extract_metadata_xml || needs_source_layout_refs)
        && (source_reference_needs.type_index || build_selected_local_refs)
    {
        build_metadata_type_indexes_from_texts(&index_metadata_texts)
    } else {
        MetadataTypeIndexes::default()
    };
    let moxel_generated_types =
        build_moxel_generated_type_index(&type_index, &type_index_collisions);
    timings.prepare_type_index_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let form_refs = if (extract_metadata_xml
        && (source_reference_needs.form_refs
            || source_reference_needs.object_refs
            || build_selected_local_refs))
        || needs_standalone_refs
    {
        build_complete_form_source_reference_index(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    timings.prepare_form_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let template_refs = if (extract_metadata_xml
        && (source_reference_needs.template_refs || build_selected_local_refs))
        || needs_standalone_refs
    {
        build_template_source_reference_index_from_texts(&metadata_rows, &index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    timings.prepare_template_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let subsystem_refs = if (extract_metadata_xml
        && (source_reference_needs.subsystem_refs || build_selected_local_refs))
        || needs_standalone_refs
    {
        build_subsystem_source_reference_index_from_texts(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    timings.prepare_subsystem_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let MetadataObjectReferenceIndexes {
        references: object_refs,
        resolutions: object_ref_resolutions,
    } = if (extract_metadata_xml || needs_source_layout_refs)
        && (source_reference_needs.object_refs || build_selected_local_refs)
    {
        build_metadata_object_reference_indexes_from_texts(&index_metadata_texts)
    } else if needs_standalone_refs {
        MetadataObjectReferenceIndexes::from_legacy(
            &build_standalone_object_reference_index_from_texts(
                &index_metadata_texts,
                &standalone_required_refs,
                &form_refs,
                &template_refs,
                &subsystem_refs,
            ),
        )
    } else {
        MetadataObjectReferenceIndexes::default()
    };
    let configuration_root_object_refs = if extract_metadata_xml {
        build_configuration_root_object_reference_index_from_texts(
            &index_metadata_texts,
            &object_refs,
        )
    } else {
        BTreeMap::new()
    };
    let role_rights_object_refs =
        build_role_rights_object_reference_index(&object_refs, &form_refs);
    timings.prepare_object_refs_ms += elapsed_ms(index_part_started);
    let metadata_order = if (extract_metadata_xml || needs_source_layout_refs)
        && source_reference_needs.metadata_order
    {
        build_metadata_order_index_from_texts(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    let index_part_started = Instant::now();
    let field_refs = if extract_metadata_xml && source_reference_needs.field_refs {
        build_metadata_field_reference_index_from_texts(&index_metadata_texts)
    } else {
        BTreeMap::new()
    };
    let field_type_refs = Arc::new(
        if extract_metadata_xml && source_reference_needs.field_refs {
            build_metadata_field_type_reference_index_from_texts(&index_metadata_texts, &type_index)
        } else {
            BTreeMap::new()
        },
    );
    let information_register_field_refs =
        if extract_metadata_xml && source_reference_needs.field_refs {
            let defined_type_value_owner_refs =
                build_defined_type_value_owner_reference_index_from_texts(
                    &index_metadata_texts,
                    &type_index,
                );
            build_information_register_field_reference_index_from_texts(
                &index_metadata_texts,
                &type_index,
                &defined_type_value_owner_refs,
            )
        } else {
            BTreeMap::new()
        };
    let information_register_master_dimensions = Arc::new(
        if extract_metadata_xml && source_reference_needs.field_refs {
            build_information_register_master_dimension_index_from_texts(
                &index_metadata_texts,
                &type_index,
                &object_refs,
                &form_refs,
                source_version == InfobaseConfigSourceVersion::V2_21,
            )
        } else {
            InformationRegisterMasterDimensionIndex::new()
        },
    );
    timings.prepare_field_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let functional_option_refs =
        if extract_metadata_xml && source_reference_needs.functional_option_refs {
            build_functional_option_reference_index_from_texts(
                &index_metadata_texts,
                &object_refs,
                &form_refs,
                &template_refs,
                &subsystem_refs,
            )
        } else {
            BTreeMap::new()
        };
    timings.prepare_functional_option_refs_ms += elapsed_ms(index_part_started);
    let source_asset_metadata_texts = &index_metadata_texts;
    let index_part_started = Instant::now();
    let source_assets = source_asset_paths_with_indexes(
        &write_index_rows,
        source_asset_metadata_texts,
        &command_refs,
        &metadata_refs,
        &object_refs,
        &field_refs,
        &type_index,
        &form_refs,
        &template_refs,
        &subsystem_refs,
    );
    let source_asset_diagnostics =
        build_form_owner_resolution_diagnostics_from_texts(source_asset_metadata_texts);
    let write_rows_by_file_name = write_index_rows
        .iter()
        .map(|row| (row.file_name.as_str(), row))
        .collect::<BTreeMap<_, _>>();
    let source_asset_discovery_misses = source_asset_discovery_misses(
        source_asset_metadata_texts,
        &file_names.iter().map(String::as_str).collect(),
        &write_rows_by_file_name,
        &command_refs,
        &metadata_refs,
        &object_refs,
        &field_refs,
        &type_index,
        &subsystem_refs,
        &form_refs,
        &template_refs,
    );
    timings.prepare_source_assets_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let help_refs = if extract_metadata_xml
        && (source_reference_needs.help_refs || build_selected_local_refs)
    {
        build_help_reference_index(&object_refs, &form_refs, &template_refs, &subsystem_refs)
    } else {
        BTreeMap::new()
    };
    timings.prepare_help_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let standalone_refs = if (needs_standalone_refs
        || (extract_metadata_xml && source_reference_needs.standalone_refs))
        && source_assets
            .values()
            .any(|asset| matches!(asset.kind, SourceAssetKind::StandaloneContent))
    {
        if extract_metadata_xml {
            build_standalone_content_references(
                &index_metadata_texts,
                &configuration_root_object_refs,
                &form_refs,
                &template_refs,
                &subsystem_refs,
            )
        } else {
            build_standalone_content_references_for_uuids(
                &index_metadata_texts,
                &standalone_required_refs,
                &build_configuration_root_object_reference_index_from_texts(
                    &index_metadata_texts,
                    &object_refs,
                ),
                &form_refs,
                &template_refs,
                &subsystem_refs,
            )
        }
    } else {
        StandaloneContentReferences::default()
    };
    timings.prepare_standalone_refs_ms += elapsed_ms(index_part_started);
    let index_part_started = Instant::now();
    let body_owners = if (extract_metadata_xml
        && (source_reference_needs.body_owners || build_selected_local_refs))
        || needs_source_layout_refs
    {
        build_body_owner_source_index_from_texts(&index_metadata_texts, &subsystem_refs)
    } else {
        BTreeMap::new()
    };
    timings.prepare_body_owners_ms += elapsed_ms(index_part_started);
    let needs_predefined_item_refs =
        predefined_data_needs_item_references(&file_names, &body_owners);
    let predefined_item_refs = if needs_predefined_item_refs {
        let predefined_body_file_names = predefined_data_body_file_names(&body_owners);
        let metadata_fetch_started = Instant::now();
        let rows = if predefined_body_file_names.is_empty() {
            Vec::new()
        } else {
            fetch_config_rows_bcp(
                sqlcmd,
                bcp,
                server,
                user,
                password,
                database,
                table,
                &predefined_body_file_names,
            )?
        };
        let elapsed = elapsed_ms(metadata_fetch_started);
        timings.prepare_metadata_fetch_ms += elapsed;
        if !predefined_body_file_names.is_empty() {
            timings.prepare_metadata_fetch_bcp_ms += elapsed;
        }
        build_predefined_item_reference_index(&rows, &body_owners, &type_index, &object_refs)?
    } else {
        BTreeMap::new()
    };
    let metadata_value_owner_file_names =
        streamed_metadata_value_owner_file_names(&index_metadata_texts, &selected_file_names);
    let mut owner_ids = selected_metadata_predefined_owner_ids(
        &index_metadata_texts,
        &metadata_value_owner_file_names,
        &type_index,
        &object_refs,
        &body_owners,
    );
    let flowchart_file_names = business_process_flowchart_file_names(&index_metadata_texts);
    if !flowchart_file_names.is_empty() {
        let flowchart_fetch_started = Instant::now();
        let flowchart_rows = fetch_config_rows_bcp(
            sqlcmd,
            bcp,
            server,
            user,
            password,
            database,
            table,
            &flowchart_file_names,
        )?;
        timings.prepare_metadata_fetch_ms += elapsed_ms(flowchart_fetch_started);
        timings.prepare_metadata_fetch_bcp_ms += elapsed_ms(flowchart_fetch_started);
        owner_ids.extend(business_process_flowchart_predefined_owner_ids(
            &flowchart_rows,
            &flowchart_file_names,
            &type_index,
            &object_refs,
            &body_owners,
        ));
    }
    let required_body_owners = body_owners
        .iter()
        .filter(|(uuid, _)| owner_ids.contains(*uuid))
        .map(|(uuid, owner)| (uuid.clone(), owner.clone()))
        .collect::<BTreeMap<_, _>>();
    let body_file_names = predefined_data_body_file_names(&required_body_owners);
    let metadata_fetch_started = Instant::now();
    let rows = if body_file_names.is_empty() {
        Vec::new()
    } else {
        fetch_config_rows_bcp(
            sqlcmd,
            bcp,
            server,
            user,
            password,
            database,
            table,
            &body_file_names,
        )?
    };
    let elapsed = elapsed_ms(metadata_fetch_started);
    timings.prepare_metadata_fetch_ms += elapsed;
    if !body_file_names.is_empty() {
        timings.prepare_metadata_fetch_bcp_ms += elapsed;
    }
    let metadata_value_predefined_item_refs = build_predefined_item_reference_index(
        &rows,
        &required_body_owners,
        &type_index,
        &object_refs,
    )?;
    let mut form_object_refs = object_refs.clone();
    form_object_refs.extend(build_form_predefined_item_reference_index(
        &rows,
        &required_body_owners,
        &type_index,
        &object_refs,
    ));
    let mut metadata_object_refs = object_refs.clone();
    extend_metadata_owner_value_references(&mut metadata_object_refs, &predefined_item_refs)?;
    extend_metadata_owner_value_references(
        &mut metadata_object_refs,
        &metadata_value_predefined_item_refs,
    )?;
    let configuration_module_groups = configuration_module_groups(&file_names);
    // A path claimed by two storage entries is a refusal about those entries,
    // not about the export: both are withheld and named, and everything that
    // claims its path alone is still produced.
    let mut source_assets = source_assets;
    let mut source_asset_diagnostics = source_asset_diagnostics;
    for (file_name, message) in
        colliding_source_asset_paths(&source_assets, &source_asset_diagnostics)
    {
        source_assets.remove(&file_name);
        source_asset_diagnostics.insert(file_name, message);
    }
    // See the identical comment in `dump_table_rows_with_options_mode`: forms,
    // templates, subsystems, and canonical module bodies resolve their output
    // path outside `source_assets`, so extend the same refusal to those
    // routes here too.
    let mut reference_collisions = colliding_reference_output_paths(
        &source_assets,
        &form_refs,
        &template_refs,
        &subsystem_refs,
        &module_text_paths,
    );
    for (file_name, message) in std::mem::take(&mut reference_collisions.source_assets) {
        if source_assets.remove(&file_name).is_some() {
            source_asset_diagnostics.insert(file_name, message);
        }
    }
    timings.prepare_reference_indexes_ms += elapsed_ms(reference_indexes_started);
    timings.prepare_indexes_ms = elapsed_ms(prepare_started);

    let context = DumpRowContext {
        output_dir,
        table,
        source_version,
        write_binary_rows,
        inflate,
        extract_module_text,
        extract_metadata_xml,
        collect_all_source_asset_diagnostics,
        refused_output_paths: &reference_collisions,
        module_text_paths: &module_text_paths,
        source_assets: &source_assets,
        metadata_texts_by_file_name: &metadata_texts_by_file_name,
        command_refs: &command_refs,
        metadata_refs: &metadata_refs,
        type_index: &type_index,
        type_index_collisions: &type_index_collisions,
        moxel_generated_types: &moxel_generated_types,
        dcs_type_index: &dcs_type_index,
        object_refs: &object_refs,
        object_ref_resolutions: &object_ref_resolutions,
        metadata_object_refs: &metadata_object_refs,
        configuration_root_object_refs: &configuration_root_object_refs,
        recalculation_refs: &recalculation_refs,
        root_recalculation_refs: &root_recalculation_refs,
        predefined_item_refs: &predefined_item_refs,
        form_object_refs: &form_object_refs,
        role_rights_object_refs: &role_rights_object_refs,
        metadata_order: &metadata_order,
        field_refs: &field_refs,
        field_type_refs: &field_type_refs,
        information_register_field_refs: &information_register_field_refs,
        information_register_master_dimensions: &information_register_master_dimensions,
        functional_option_refs: &functional_option_refs,
        help_refs: &help_refs,
        standalone_refs: &standalone_refs,
        form_refs: &form_refs,
        template_refs: &template_refs,
        subsystem_refs: &subsystem_refs,
        file_names: &file_names,
        body_owners: &body_owners,
        configuration_module_groups: &configuration_module_groups,
    };

    let mut manifests = Vec::with_capacity(file_names.len());
    let mut binary_bytes = 0;
    let mut inflated_rows = 0;
    let mut module_text_rows = 0;
    let mut metadata_xml_rows = 0;
    let mut source_asset_rows = 0;
    let mut source_asset_completeness = SourceAssetCompletenessReport::default();
    let mut metadata_extraction_diagnostics = BTreeMap::new();
    let mut versions_blob = None;
    let file_name_batches = build_dump_file_name_batches(&headers, &file_names);
    for chunk in file_name_batches {
        let selected = chunk.iter().cloned().collect::<BTreeSet<_>>();
        let fetch_started = Instant::now();
        let rows = fetch_binary_rows_bcp(
            sqlcmd,
            bcp,
            server,
            user,
            password,
            database,
            table,
            &selected,
            selected_file_names.is_empty(),
        )
        .with_context(|| {
            let first = chunk.first().map(String::as_str).unwrap_or("<empty>");
            let last = chunk.last().map(String::as_str).unwrap_or("<empty>");
            format!("failed to fetch {table} rows batch {first}..{last}")
        })?;
        let elapsed = elapsed_ms(fetch_started);
        timings.fetch_rows_ms += elapsed;
        timings.fetch_rows_bcp_ms += elapsed;
        timings.fetch_row_batches += 1;
        timings.fetch_row_batch_max_rows = timings.fetch_row_batch_max_rows.max(rows.len() as u64);
        let batch_binary_bytes = rows.iter().map(|row| row.binary.len() as u64).sum::<u64>();
        timings.fetch_row_batch_max_binary_bytes = timings
            .fetch_row_batch_max_binary_bytes
            .max(batch_binary_bytes);
        if generate_config_dump_info {
            for row in rows.iter().filter(|row| row.file_name == "versions") {
                if row.part_no != 0 {
                    bail!("Config versions row has unsupported PartNo {}", row.part_no);
                }
                if versions_blob.replace(row.binary.clone()).is_some() {
                    bail!("Config versions row was fetched more than once");
                }
            }
        }
        let process_started = Instant::now();
        let dumped_rows = parallel::install(|| {
            rows.par_iter()
                .map(|row| dump_table_binary_row(&context, row))
                .collect::<Vec<_>>()
        })?;
        timings.process_rows_wall_ms += elapsed_ms(process_started);
        for dumped in dumped_rows {
            let dumped = dumped?;
            binary_bytes += dumped.binary_bytes;
            inflated_rows += dumped.inflated_rows;
            module_text_rows += dumped.module_text_rows;
            metadata_xml_rows += dumped.metadata_xml_rows;
            source_asset_rows += dumped.source_asset_rows;
            source_asset_completeness.merge(&dumped.source_assets);
            if let Some(diagnostic) = dumped.metadata_xml_diagnostic {
                metadata_extraction_diagnostics
                    .insert(dumped.manifest.file_name.clone(), diagnostic);
            }
            timings.add_assign(&dumped.timings);
            manifests.push(dumped.manifest);
        }
    }
    for (source_row_id, reason) in &source_asset_discovery_misses {
        source_asset_completeness.record_affected_reason(source_asset_audit_entry(
            table,
            source_row_id,
            source_assets.get(source_row_id),
            format!("source_asset.discovery.{reason}"),
            "source_asset_candidate_missing",
        ));
    }
    for (source_row_id, reason) in &selected_metadata_audit.misses {
        source_asset_completeness.record_affected_reason(source_asset_audit_entry(
            table,
            source_row_id,
            source_assets.get(source_row_id),
            format!(
                "source_asset.discovery.metadata_decode_miss.{}",
                reason.as_str()
            ),
            "source_asset_candidate_missing",
        ));
    }
    for source_row_id in source_asset_diagnostics.keys() {
        source_asset_completeness.record_affected_reason(source_asset_audit_entry(
            table,
            source_row_id,
            source_assets.get(source_row_id),
            "source_asset.form_owner_resolution.uncertain".to_string(),
            "source_asset_identity_uncertain",
        ));
    }
    source_asset_completeness.finish_inventory(
        source_asset_scope,
        source_asset_discovery_misses.is_empty()
            && selected_metadata_audit.misses.is_empty()
            && source_asset_diagnostics.is_empty(),
        source_assets.len()
            + source_asset_discovery_misses.len()
            + selected_metadata_audit.misses.len(),
    );

    if generate_config_dump_info {
        let started = Instant::now();
        let mut emitted_source_asset_paths = BTreeMap::<String, PathBuf>::new();
        for manifest in &manifests {
            let Some(path) = manifest.source_asset_path.as_ref().map(PathBuf::from) else {
                continue;
            };
            if let Some(previous) =
                emitted_source_asset_paths.insert(manifest.file_name.clone(), path.clone())
                && previous != path
            {
                bail!(
                    "Config source asset {} was emitted to both {} and {}",
                    manifest.file_name,
                    previous.display(),
                    path.display()
                );
            }
        }
        write_config_dump_info(
            output_dir,
            source_version,
            versions_blob
                .as_deref()
                .ok_or_else(|| anyhow!("full Config export has no versions row"))?,
            VersionsBlobOrigin::MssqlConfigTable,
            ConfigDumpInfoPartialInventoryPolicy::Fail,
            ConfigDumpInfoInventory {
                file_names: &file_names,
                metadata_texts: &index_metadata_texts,
                object_refs: &object_refs,
                form_refs: &form_refs,
                template_refs: &template_refs,
                subsystem_refs: &subsystem_refs,
                module_text_paths: &module_text_paths,
                source_assets: &source_assets,
                emitted_source_asset_paths: &emitted_source_asset_paths,
                configuration_module_groups: &configuration_module_groups,
            },
        )?;
        timings.source_asset_config_dump_info_cpu_ms += elapsed_ms(started);
    }

    let metadata_root_inventory = if extract_metadata_xml {
        let indexed_roots =
            configuration_root_metadata_file_names_from_texts(&index_metadata_texts);
        let (candidates, candidate_set_complete) = selected_root_metadata_candidates(
            &selected_metadata_audit,
            &metadata_file_names,
            inventory_scope,
            indexed_roots.as_ref(),
        );
        audit_root_metadata_inventory(
            &candidates,
            &selected_metadata_audit,
            &manifests,
            &metadata_extraction_diagnostics,
            inventory_scope,
            candidate_set_complete,
        )
    } else {
        RootMetadataInventoryReport::default()
    };
    Ok(DumpedTable {
        rows: manifests,
        failed_rows: Vec::new(),
        binary_bytes,
        inflated_rows,
        module_text_rows,
        metadata_xml_rows,
        source_asset_rows,
        source_assets: source_asset_completeness,
        metadata_root_inventory,
        timings,
    })
}

fn elapsed_ms(started: Instant) -> u64 {
    started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64
}

fn build_dump_file_name_batches(
    headers: &[ConfigRowHeader],
    file_names: &BTreeSet<String>,
) -> Vec<Vec<String>> {
    let mut file_sizes = BTreeMap::<&str, u64>::new();
    for header in headers {
        file_sizes
            .entry(header.file_name.as_str())
            .and_modify(|size| *size = (*size).max(header.data_size.max(0) as u64))
            .or_insert(header.data_size.max(0) as u64);
    }

    let mut batches = Vec::new();
    let mut current = Vec::new();
    let mut current_bytes = 0u64;
    for file_name in file_names {
        let file_bytes = file_sizes
            .get(file_name.as_str())
            .copied()
            .unwrap_or_default();
        let would_exceed_bytes = current_bytes > 0
            && current_bytes.saturating_add(file_bytes) > SQLCMD_DUMP_BATCH_MAX_DATA_BYTES;
        let would_exceed_count = current.len() >= SQLCMD_DUMP_FILE_BATCH_SIZE;
        if !current.is_empty() && (would_exceed_bytes || would_exceed_count) {
            batches.push(std::mem::take(&mut current));
            current_bytes = 0;
        }
        current.push(file_name.clone());
        current_bytes = current_bytes.saturating_add(file_bytes);
    }
    if !current.is_empty() {
        batches.push(current);
    }
    batches
}

fn rows_for_source_indexes(
    headers: &[ConfigRowHeader],
    metadata_rows: &[ConfigRow],
) -> Vec<ConfigRow> {
    let metadata_file_names = metadata_rows
        .iter()
        .map(|row| row.file_name.as_str())
        .collect::<BTreeSet<_>>();
    let mut rows = metadata_rows.to_vec();
    let mut seen = BTreeSet::<&str>::new();
    for header in headers {
        if metadata_file_names.contains(header.file_name.as_str())
            || !seen.insert(header.file_name.as_str())
        {
            continue;
        }
        rows.push(ConfigRow {
            file_name: header.file_name.clone(),
            part_no: header.part_no,
            data_size: header.data_size,
            binary_hex: String::new(),
        });
    }
    rows
}

#[derive(Default)]
struct MetadataTextRowsAudit {
    rows: Vec<MetadataTextRow>,
    misses: BTreeMap<String, MetadataExtractionMissReason>,
}

fn build_metadata_text_rows_audited(rows: &[ConfigRow]) -> MetadataTextRowsAudit {
    let mut audit = MetadataTextRowsAudit::default();
    for row in rows.iter().filter(|row| !row.file_name.contains('.')) {
        let row_audit = match decode_hex(&row.binary_hex) {
            Ok(bytes) => metadata_text_row_audit_from_blob(&row.file_name, &bytes),
            Err(_) => MetadataTextRowAudit::Miss(MetadataExtractionMiss {
                file_name: row.file_name.clone(),
                reason: MetadataExtractionMissReason::Inflate,
            }),
        };
        match row_audit {
            MetadataTextRowAudit::Extracted(mut metadata) => {
                normalize_direct_form_metadata(&mut metadata);
                audit.rows.push(metadata);
            }
            MetadataTextRowAudit::ExtractedWithWarning(mut metadata, miss) => {
                let recognized_configuration = is_configuration_metadata_row(&metadata);
                let recognized_direct_form = normalize_direct_form_metadata(&mut metadata);
                if !recognized_configuration
                    && !(recognized_direct_form
                        && miss.reason == MetadataExtractionMissReason::Family)
                {
                    audit.misses.entry(miss.file_name).or_insert(miss.reason);
                }
                audit.rows.push(metadata);
            }
            MetadataTextRowAudit::Miss(miss) => {
                audit.misses.entry(miss.file_name).or_insert(miss.reason);
            }
        }
    }
    audit
}

fn normalize_direct_form_metadata(metadata: &mut MetadataTextRow) -> bool {
    if !is_direct_code14_form_metadata_text(&metadata.text, &metadata.file_name) {
        return false;
    }
    metadata.kind = Some("Form".to_string());
    metadata.folder = None;
    true
}

fn is_configuration_metadata_row(metadata: &MetadataTextRow) -> bool {
    parse_configuration_reference_text_for_row(&metadata.text, &metadata.file_name).is_some()
}

fn build_metadata_text_rows(rows: &[ConfigRow]) -> Vec<MetadataTextRow> {
    build_metadata_text_rows_audited(rows).rows
}

fn selected_root_metadata_candidates(
    metadata: &MetadataTextRowsAudit,
    selected_file_names: &BTreeSet<String>,
    scope: RootMetadataInventoryScope,
    indexed_root_file_names: Option<&BTreeSet<String>>,
) -> (BTreeSet<String>, bool) {
    let decoded_roots = metadata
        .rows
        .iter()
        .filter(|row| row.folder.is_some() || is_configuration_metadata_row(row))
        .map(|row| row.file_name.clone())
        .collect::<BTreeSet<_>>();
    if scope == RootMetadataInventoryScope::Full {
        return indexed_root_file_names
            .cloned()
            .map(|candidates| (candidates, true))
            .unwrap_or((decoded_roots, false));
    }

    if let Some(indexed) = indexed_root_file_names {
        let candidates = selected_file_names
            .intersection(indexed)
            .filter(|file_name| is_uuid_text(file_name))
            .cloned()
            .collect::<BTreeSet<_>>();
        return (candidates, true);
    }

    let candidates = decoded_roots
        .into_iter()
        .filter(|file_name| selected_file_names.contains(file_name))
        .collect::<BTreeSet<_>>();
    let has_ambiguous_miss = metadata.misses.keys().any(|file_name| {
        selected_file_names.contains(file_name)
            && is_uuid_text(file_name)
            && !candidates.contains(file_name)
    });
    (candidates, !has_ambiguous_miss)
}

fn form_metadata_file_names(rows: &[ConfigRow]) -> BTreeSet<String> {
    build_metadata_text_rows(rows)
        .into_iter()
        .filter(|row| {
            is_form_metadata_text(&row.text, &row.file_name)
                || is_direct_code14_form_metadata_text(&row.text, &row.file_name)
        })
        .map(|row| row.file_name)
        .collect()
}

fn is_direct_code14_form_metadata_text(text: &str, uuid: &str) -> bool {
    if parse_metadata_object_code(text) != Some(14) {
        return false;
    }
    let Some(fields) = metadata_object_fields(text) else {
        return false;
    };
    fields.len() == 6
        && fields.first().map(|field| field.trim()) == Some("14")
        && metadata_header_field_index(&fields, uuid) == Some(1)
        && information_register_bool(fields[2]).is_some()
        && information_register_bool(fields[3]).is_some()
        && direct_form_application_purposes_are_valid(fields[4])
        && information_register_bool(fields[5]).is_some()
}

fn direct_form_application_purposes_are_valid(value: &str) -> bool {
    let Some(fields) = split_1c_braced_fields(value, 0) else {
        return false;
    };
    let Some(count) = fields
        .first()
        .and_then(|field| field.trim().parse::<usize>().ok())
    else {
        return false;
    };
    if count.checked_add(1) != Some(fields.len()) {
        return false;
    }
    fields.iter().skip(1).all(|field| {
        let Some(item) = split_1c_braced_fields(field, 0) else {
            return false;
        };
        item.len() == 3
            && item.first().map(|field| field.trim()) == Some(r##""#""##)
            && item
                .get(1)
                .and_then(|field| parse_uuid_field(field.trim()))
                .as_deref()
                == Some(FORM_APPLICATION_USE_PURPOSE_TYPE_UUID)
            && matches!(item.get(2).map(|field| field.trim()), Some("1" | "2"))
    })
}

fn build_direct_code14_form_source_reference_index(
    rows: &[MetadataTextRow],
) -> BTreeMap<String, FormSourceReference> {
    let forms = rows
        .iter()
        .filter(|row| is_direct_code14_form_metadata_text(&row.text, &row.file_name))
        .filter_map(|row| row.header.clone())
        .collect::<Vec<_>>();
    let form_uuids = forms
        .iter()
        .map(|form| form.uuid.clone())
        .collect::<BTreeSet<_>>();
    if form_uuids.is_empty() {
        return BTreeMap::new();
    }

    let mut owner_paths_by_ref = BTreeMap::<String, BTreeSet<PathBuf>>::new();
    for row in rows {
        if is_form_metadata_text(&row.text, &row.file_name)
            || is_direct_code14_form_metadata_text(&row.text, &row.file_name)
        {
            continue;
        }
        let (Some(kind), Some(folder), Some(header)) =
            (row.kind.as_deref(), row.folder, row.header.as_ref())
        else {
            continue;
        };
        if !metadata_kind_can_own_forms(kind) {
            continue;
        }
        let Some(references) = owned_form_uuid_values_matching(&row.text, &form_uuids) else {
            continue;
        };
        let owner_path = PathBuf::from(folder).join(sanitize_source_path_segment(&header.name));
        for reference in references {
            owner_paths_by_ref
                .entry(reference)
                .or_default()
                .insert(owner_path.clone());
        }
    }

    forms
        .into_iter()
        .filter_map(|form| {
            let owner_paths = owner_paths_by_ref.get(&form.uuid)?;
            let mut owners = owner_paths.iter();
            let owner = owners.next()?;
            if owners.next().is_some() {
                return None;
            }
            Some((
                form.uuid,
                FormSourceReference {
                    relative_path: owner
                        .join("Forms")
                        .join(sanitize_source_path_segment(&form.name))
                        .with_extension("xml"),
                    kind: "Form",
                },
            ))
        })
        .collect()
}

fn build_complete_form_source_reference_index(
    rows: &[MetadataTextRow],
) -> BTreeMap<String, FormSourceReference> {
    let mut refs = build_form_source_reference_index_from_texts(rows);
    refs.extend(build_direct_code14_form_source_reference_index(rows));
    refs
}

fn selected_form_owner_metadata_rows(
    rows: &[ConfigRow],
    form_file_names: &BTreeSet<String>,
) -> Vec<ConfigRow> {
    if form_file_names.is_empty() {
        return Vec::new();
    }
    let owner_file_names = build_metadata_text_rows(rows)
        .into_iter()
        .filter(|row| {
            row.kind.as_deref().is_some_and(metadata_kind_can_own_forms)
                && owned_form_uuid_values_matching(&row.text, form_file_names)
                    .is_some_and(|references| !references.is_empty())
        })
        .map(|row| row.file_name)
        .collect::<BTreeSet<_>>();
    rows.iter()
        .filter(|row| owner_file_names.contains(&row.file_name))
        .cloned()
        .collect()
}

fn selected_metadata_predefined_owner_ids(
    rows: &[MetadataTextRow],
    selected_file_names: &BTreeSet<String>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    body_owners: &BTreeMap<String, BodyOwnerSourceReference>,
) -> BTreeSet<String> {
    let mut owners = BTreeSet::new();
    for row in rows {
        if !matches!(
            row.kind.as_deref(),
            Some("InformationRegister" | "Catalog" | "Document")
        ) || !selected_file_names.contains(&row.file_name)
        {
            continue;
        }
        collect_predefined_owner_ids_in_value(
            &row.text,
            type_index,
            object_refs,
            body_owners,
            &mut owners,
        );
    }
    owners
}

fn collect_predefined_owner_ids_in_value(
    text: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    body_owners: &BTreeMap<String, BodyOwnerSourceReference>,
    owners: &mut BTreeSet<String>,
) {
    let mut pending = vec![text];
    while let Some(value) = pending.pop() {
        if let Some((owner_uuid, value_uuid)) =
            parse_information_register_design_time_ref_ids(value)
            && !information_register_uuid_is_zero(&owner_uuid)
            && !information_register_uuid_is_zero(&value_uuid)
            && let Some(owner_reference) = information_register_design_time_owner_reference(
                &owner_uuid,
                type_index,
                object_refs,
            )
            && !object_refs.get(&value_uuid).is_some_and(|reference| {
                information_register_reference_belongs_to_owner(&owner_reference, reference)
            })
        {
            let mut matches = body_owners
                .keys()
                .filter(|candidate| object_refs.get(*candidate) == Some(&owner_reference));
            if let (Some(owner_metadata_uuid), None) = (matches.next().cloned(), matches.next()) {
                owners.insert(owner_metadata_uuid);
            }
        }
        let Some(fields) = split_1c_braced_fields(value, 0) else {
            continue;
        };
        pending.extend(
            fields
                .into_iter()
                .filter(|field| field.trim_start().starts_with('{')),
        );
    }
}

/// Business-process flowcharts are the one source asset carrying design-time
/// references to predefined items (addressing-attribute values); their owners
/// must join the predefined-item reference index the same way metadata-text
/// owners do.
fn business_process_flowchart_file_names(metadata_texts: &[MetadataTextRow]) -> BTreeSet<String> {
    metadata_texts
        .iter()
        .filter(|row| row.kind.as_deref() == Some("BusinessProcess"))
        .map(|row| format!("{}.7", row.file_name))
        .collect()
}

fn business_process_flowchart_predefined_owner_ids(
    flowchart_rows: &[ConfigRow],
    flowchart_file_names: &BTreeSet<String>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    body_owners: &BTreeMap<String, BodyOwnerSourceReference>,
) -> BTreeSet<String> {
    let mut owners = BTreeSet::new();
    for row in flowchart_rows {
        if !flowchart_file_names.contains(&row.file_name) {
            continue;
        }
        let Ok(bytes) = decode_hex(&row.binary_hex) else {
            continue;
        };
        let Ok(inflated) = inflate_raw_deflate(&bytes) else {
            continue;
        };
        let Ok(text) = String::from_utf8(inflated) else {
            continue;
        };
        collect_predefined_owner_ids_in_value(
            text.trim_start_matches('\u{feff}'),
            type_index,
            object_refs,
            body_owners,
            &mut owners,
        );
    }
    owners
}

fn metadata_value_owner_file_names(rows: &[MetadataTextRow]) -> BTreeSet<String> {
    rows.iter()
        .filter(|row| {
            matches!(
                row.kind.as_deref(),
                Some("InformationRegister" | "Catalog" | "Document")
            )
        })
        .map(|row| row.file_name.clone())
        .collect()
}

fn eager_metadata_value_owner_file_names(rows: &[MetadataTextRow]) -> BTreeSet<String> {
    metadata_value_owner_file_names(rows)
}

fn streamed_metadata_value_owner_file_names(
    rows: &[MetadataTextRow],
    selected_file_names: &BTreeSet<String>,
) -> BTreeSet<String> {
    if selected_file_names.is_empty() {
        metadata_value_owner_file_names(rows)
    } else {
        selected_file_names.clone()
    }
}

fn merge_config_rows_by_file_name(
    mut left: Vec<ConfigRow>,
    right: Vec<ConfigRow>,
) -> Vec<ConfigRow> {
    let mut rows = BTreeMap::<String, ConfigRow>::new();
    for row in left.drain(..).chain(right) {
        rows.insert(row.file_name.clone(), row);
    }
    rows.into_values().collect()
}

fn dump_table_row(context: &DumpRowContext<'_>, row: &ConfigRow) -> Result<DumpedRow> {
    let bytes = decode_hex(&row.binary_hex)
        .with_context(|| format!("failed to decode {} row {}", context.table, row.file_name))?;
    dump_table_row_bytes(context, &row.file_name, row.part_no, row.data_size, &bytes)
}

fn dump_table_binary_row(context: &DumpRowContext<'_>, row: &BinaryConfigRow) -> Result<DumpedRow> {
    dump_table_row_bytes(
        context,
        &row.file_name,
        row.part_no,
        row.data_size,
        &row.binary,
    )
}

fn dump_table_row_bytes(
    context: &DumpRowContext<'_>,
    file_name: &str,
    part_no: i32,
    data_size: i64,
    bytes: &[u8],
) -> Result<DumpedRow> {
    let mut timings = MssqlDumpTimingReport::default();
    if bytes.len() != data_size as usize {
        bail!(
            "{} row {} DataSize {} does not match BinaryData length {}",
            context.table,
            file_name,
            data_size,
            bytes.len()
        );
    }

    let safe_name = safe_storage_file_name(file_name, part_no);
    let binary_relative = if context.write_binary_rows {
        Some(PathBuf::from(context.table).join(format!("{safe_name}.bin")))
    } else {
        None
    };
    if context.write_binary_rows {
        let started = Instant::now();
        let binary_path = context
            .output_dir
            .join(binary_relative.as_ref().expect("binary path is present"));
        fs::write(&binary_path, &bytes)
            .with_context(|| format!("failed to write {}", binary_path.display()))?;
        timings.binary_write_cpu_ms += elapsed_ms(started);
    }

    let mut inflated_rows = 0;
    let inflated_relative = if context.inflate {
        let started = Instant::now();
        match inflate_raw_deflate(&bytes) {
            Ok(inflated) => {
                let relative = PathBuf::from(format!("{}_inflated", context.table))
                    .join(format!("{safe_name}.txt"));
                let path = context.output_dir.join(&relative);
                fs::write(&path, inflated)
                    .with_context(|| format!("failed to write {}", path.display()))?;
                inflated_rows = 1;
                timings.inflate_cpu_ms += elapsed_ms(started);
                Some(relative.to_string_lossy().replace('\\', "/"))
            }
            Err(_) => {
                timings.inflate_cpu_ms += elapsed_ms(started);
                None
            }
        }
    } else {
        None
    };

    let static_source_asset = context.source_assets.get(file_name);
    let parsed_form_body = if matches!(
        static_source_asset.map(|asset| &asset.kind),
        Some(SourceAssetKind::Form { .. })
    ) {
        let started = Instant::now();
        let parsed = parse_form_body_blob(bytes).ok();
        timings.form_body_parse_cpu_ms += elapsed_ms(started);
        parsed
    } else {
        None
    };

    let mut module_text_rows = 0;
    let module_text_relative = if context.extract_module_text {
        let started = Instant::now();
        let module_text = match unpack_module_blob_text(&bytes) {
            Ok(text) => Some(text),
            Err(_) if let Some(body) = parsed_form_body.as_ref() => {
                form_body_module_text_bytes(body)
            }
            Err(_) if context.module_text_paths.contains_key(file_name) => {
                unpack_form_body_module_text(&bytes)
                    .or_else(|| unpack_plain_text_module_body(&bytes))
            }
            Err(_) => None,
        };
        match module_text {
            Some(_)
                if context
                    .refused_output_paths
                    .module_text
                    .contains_key(file_name) =>
            {
                // Two rows resolved to the identical canonical module path
                // (`colliding_reference_output_paths`); the platform writes
                // neither, and picking a winner would be nondeterministic
                // between runs of this same binary. Disclosed as an opaque
                // entry in the top-level export report, not a written file.
                timings.module_text_cpu_ms += elapsed_ms(started);
                None
            }
            Some(text) => {
                let relative = match context.module_text_paths.get(file_name).cloned() {
                    Some(relative) => Some(relative),
                    // No canonical owner path. `write_binary_rows` is this
                    // pipeline's existing signal for "raw/debug MSSQL storage
                    // dump" (see `needs_source_layout_refs` above): that mode
                    // keeps the historical `{table}_module_text/*.bsl`
                    // fallback for forensic inspection. A strict source
                    // export (`write_binary_rows == false`, i.e. `cf export`
                    // and `infobase config export`) never takes it: the
                    // platform does not have this path at all -- confirmed by
                    // its absence from every native reference tree -- so
                    // writing it here was always a debug-tool convenience
                    // leaking into the parity-graded output, not a real
                    // export path. Fail closed instead and disclose through
                    // the opaque entry, matching the "not emitted" reasoning
                    // recorded for the owning object's own metadata XML.
                    None if context.write_binary_rows => Some(
                        PathBuf::from(format!("{}_module_text", context.table))
                            .join(format!("{safe_name}.bsl")),
                    ),
                    None => None,
                };
                match relative {
                    Some(relative) => {
                        let path = context.output_dir.join(&relative);
                        if let Some(parent) = path.parent() {
                            fs::create_dir_all(parent).with_context(|| {
                                format!("failed to create {}", parent.display())
                            })?;
                        }
                        fs::write(&path, text)
                            .with_context(|| format!("failed to write {}", path.display()))?;
                        module_text_rows = 1;
                        timings.module_text_cpu_ms += elapsed_ms(started);
                        Some(relative.to_string_lossy().replace('\\', "/"))
                    }
                    None => {
                        timings.module_text_cpu_ms += elapsed_ms(started);
                        None
                    }
                }
            }
            None => {
                timings.module_text_cpu_ms += elapsed_ms(started);
                None
            }
        }
    } else {
        None
    };

    let mut metadata_xml_rows = 0;
    let mut metadata_xml_diagnostic = None;
    let metadata_xml_relative = if context.extract_metadata_xml {
        let started = Instant::now();
        let extracted = if context
            .refused_output_paths
            .metadata_xml
            .contains_key(file_name)
        {
            // Two rows resolved to the identical canonical descriptor path
            // (`colliding_reference_output_paths` -- a form, template, or
            // subsystem whose own XML lands on a path another row also
            // claims). The platform writes neither, so this exporter must
            // not pick a nondeterministic winner between runs either: fail
            // closed instead of computing and writing either row's XML.
            Err(MetadataSourceExtractionDiagnostic::legacy_option_none(
                MetadataSourceFailureClass::Unsupported,
                "unknown",
                "output_path_collision",
            ))
        } else if let Some(row) = context.metadata_texts_by_file_name.get(file_name) {
            extract_metadata_source_xml_from_text_row_audited_with_object_ref_resolutions(
                row,
                context.type_index,
                context.type_index_collisions,
                context.object_refs,
                context.object_ref_resolutions,
                context.metadata_object_refs,
                context.configuration_root_object_refs,
                context.recalculation_refs,
                context.root_recalculation_refs,
                context.functional_option_refs,
                context.form_refs,
                context.template_refs,
                context.subsystem_refs,
                context.source_version,
            )
        } else {
            extract_metadata_source_xml_with_recalculation_refs_with_object_ref_resolutions(
                &bytes,
                file_name,
                context.type_index,
                context.type_index_collisions,
                context.object_refs,
                context.object_ref_resolutions,
                context.metadata_object_refs,
                context.configuration_root_object_refs,
                context.recalculation_refs,
                context.root_recalculation_refs,
                context.functional_option_refs,
                context.form_refs,
                context.template_refs,
                context.subsystem_refs,
                context.source_version,
            )
            .ok_or_else(|| {
                MetadataSourceExtractionDiagnostic::legacy_option_none(
                    MetadataSourceFailureClass::Unknown,
                    "unknown",
                    "metadata_row_unavailable",
                )
            })
        };
        match extracted {
            Ok(extracted) => {
                let path = context.output_dir.join(&extracted.relative_path);
                if let Some(parent) = path.parent() {
                    fs::create_dir_all(parent)
                        .with_context(|| format!("failed to create {}", parent.display()))?;
                }
                write_source_xml_file(&path, extracted.xml, context.source_version)?;
                metadata_xml_rows = 1;
                timings.metadata_xml_cpu_ms += elapsed_ms(started);
                Some(extracted.relative_path.to_string_lossy().replace('\\', "/"))
            }
            Err(diagnostic) => {
                metadata_xml_diagnostic = Some(diagnostic);
                timings.metadata_xml_cpu_ms += elapsed_ms(started);
                None
            }
        }
    } else {
        None
    };

    let mut source_asset_rows = 0;
    let mut source_assets = SourceAssetCompletenessReport::default();
    let source_asset_relative = if metadata_xml_relative.is_none() {
        let started = Instant::now();
        let dynamic_asset;
        let asset = match context.source_assets.get(file_name) {
            Some(asset) => Some(asset),
            None => {
                dynamic_asset = dynamic_source_asset(context, file_name, &bytes);
                dynamic_asset.as_ref()
            }
        };
        match asset {
            Some(asset) => {
                let form_owner_reference = match &asset.kind {
                    SourceAssetKind::Form { owner_reference } => owner_reference.clone(),
                    _ => None,
                };
                let written = write_source_asset(
                    context,
                    asset,
                    &bytes,
                    parsed_form_body.as_ref(),
                    &mut timings,
                )?;
                let (emitted, primary_path, form_diagnostics) = match written {
                    WrittenSourceAsset::Emitted {
                        primary_path,
                        diagnostics,
                    } => (true, primary_path, diagnostics),
                    WrittenSourceAsset::OpaqueNotEmitted {
                        primary_path,
                        diagnostics,
                    } => (false, primary_path, diagnostics),
                    WrittenSourceAsset::RejectedNotEmitted {
                        primary_path,
                        diagnostics,
                    } => (false, primary_path, diagnostics),
                };
                if !emitted && form_diagnostics.is_empty() {
                    bail!(
                        "source asset {} was suppressed without an opaque diagnostic",
                        primary_path.display()
                    );
                }
                source_asset_rows = usize::from(emitted);
                let asset_path = primary_path.to_string_lossy().replace('\\', "/");
                let diagnostics = form_diagnostics
                    .into_iter()
                    .map(|diagnostic| SourceAssetCompletenessEntry {
                        family: "form".to_string(),
                        code: diagnostic.code.to_string(),
                        classification: diagnostic.classification.to_string(),
                        parse_error_class: diagnostic.parse_error_class.map(str::to_string),
                        table: context.table.to_string(),
                        source_row_id: file_name.to_string(),
                        asset_path: asset_path.clone(),
                        form_owner_reference: form_owner_reference.clone(),
                        form_item_id: diagnostic.form_item_id,
                        form_item_tag: diagnostic.form_item_tag.to_string(),
                        property: diagnostic.property.to_string(),
                        property_profile: diagnostic.property_profile.to_string(),
                        property_slot: diagnostic.property_slot,
                        raw_length: diagnostic.raw_length,
                        raw_sha256: diagnostic.raw_sha256,
                    })
                    .collect::<Vec<_>>();
                if diagnostics.is_empty() {
                    debug_assert!(emitted);
                    source_assets.record_emitted();
                } else {
                    source_assets.record_opaque(diagnostics);
                }
                let elapsed = elapsed_ms(started);
                timings.source_asset_cpu_ms += elapsed;
                timings.add_source_asset_kind(&asset.kind, elapsed);
                emitted.then_some(asset_path)
            }
            None => {
                timings.source_asset_cpu_ms += elapsed_ms(started);
                None
            }
        }
    } else {
        None
    };

    Ok(DumpedRow {
        manifest: MssqlDumpRowManifest {
            file_name: file_name.to_string(),
            part_no,
            data_size,
            binary_bytes: bytes.len(),
            binary_path: binary_relative.map(|path| path.to_string_lossy().replace('\\', "/")),
            inflated_path: inflated_relative,
            module_text_path: module_text_relative,
            metadata_xml_path: metadata_xml_relative,
            source_asset_path: source_asset_relative,
        },
        binary_bytes: bytes.len(),
        inflated_rows,
        module_text_rows,
        metadata_xml_rows,
        source_asset_rows,
        source_assets,
        metadata_xml_diagnostic,
        timings,
    })
}

#[derive(Debug)]
struct ExchangePlanContentItem {
    metadata_id: String,
    metadata: String,
    auto_record: &'static str,
}

struct BusinessProcessFlowchart {
    scheme: FlowchartScheme,
    items: Vec<FlowchartItem>,
}

/// Root properties of the graphical scheme, read off the header record.
struct FlowchartScheme {
    back_color: String,
    grid_enabled: bool,
    grid_horizontal_step: String,
    grid_vertical_step: String,
    draw_grid_mode: &'static str,
    print_parameters: FlowchartPrintParameters,
}

struct FlowchartPrintParameters {
    top_margin: String,
    left_margin: String,
    bottom_margin: String,
    right_margin: String,
    black_and_white: bool,
    fit_page_mode: &'static str,
}

struct FlowchartItem {
    tag: &'static str,
    id: String,
    uuid: Option<String>,
    name: String,
    title: Vec<(String, String)>,
    tab_order: String,
    properties: FlowchartItemProperties,
    events: Vec<FlowchartEvent>,
}

/// The style record every item carries: `{7, back, line, text, font,
/// tooltip, halign, 1, 1, zorder, 0, transparent, 0, 0}`. The three colours
/// are one and the same control-colour value the form writer reads, in the
/// order back / line / text; the two constant flag groups are pinned because
/// no item in the evidence base varies them.
struct FlowchartItemStyle {
    back_color: String,
    line_color: String,
    text_color: String,
    font: FlowchartFont,
    tooltip: Vec<(String, String)>,
    horizontal_align: &'static str,
    z_order: String,
    transparent: bool,
}

struct FlowchartItemProperties {
    style: FlowchartItemStyle,
    location: Option<FlowchartLocation>,
    pivot_points: Vec<FlowchartPoint>,
    manually_moved_segments: Vec<FlowchartSegment>,
    from: Option<FlowchartConnectionEnd>,
    to: Option<FlowchartConnectionEnd>,
    decorative_line: bool,
    line_style: &'static str,
    text_location: &'static str,
    begin_arrow: &'static str,
    end_arrow: &'static str,
    explanation: Option<String>,
    task_description: Option<String>,
    group: bool,
    addressing_attributes: Vec<FlowchartAddressingAttribute>,
    subprocess: Option<String>,
    true_port_index: Option<String>,
    false_port_index: Option<String>,
}

struct FlowchartSegment {
    index: String,
    start: FlowchartPoint,
    end: FlowchartPoint,
}

struct FlowchartAddressingAttribute {
    reference: String,
    value: FlowchartAddressingAttributeValue,
}

enum FlowchartAddressingAttributeValue {
    Nil,
    DesignTimeRef(String),
}

struct FlowchartLocation {
    left: String,
    top: String,
    right: String,
    bottom: String,
}

struct FlowchartPoint {
    x: String,
    y: String,
}

struct FlowchartConnectionEnd {
    item: String,
    port_index: String,
}

struct FlowchartFont {
    reference: String,
    kind: &'static str,
    height: Option<String>,
    bold: bool,
    italic: bool,
    underline: bool,
    strikeout: bool,
    scale: Option<String>,
}

struct FlowchartEvent {
    name: &'static str,
    handler: Option<String>,
}

struct FlowchartBase {
    id: String,
    uuid: Option<String>,
    name: String,
    title: Vec<(String, String)>,
    tab_order: String,
}

#[derive(Clone)]
struct MetadataCommandReference {
    kind: String,
    name: String,
    /// Whether the target metadata object itself declares
    /// `<UseStandardCommands>true</UseStandardCommands>`. Both command-interface
    /// readers (this object's own `Ext/CommandInterface.xml` and a form's
    /// embedded `<CommandInterface>`) must decline to synthesize a
    /// `.StandardCommand.X` name when this is `false`: the platform keeps the
    /// raw `code:uuid` sentinel instead, because the standard command does not
    /// exist on that target. Evidence: ERP UH `MDM_Management`,
    /// `Catalog.ТабличныеЧастиБД` (`UseStandardCommands=false`) is kept as
    /// `0:04c1ab92-f4fc-40e9-b0d6-a1c57a5a8b47` in
    /// `Subsystems/.../Ext/CommandInterface.xml`, and `Catalog.СправочникиБД`
    /// (also `false`) is kept as `4:67b8886f-f30d-480c-abb8-e3712f3c169c` in
    /// `Catalogs/ТипыБазДанных/Forms/ФормаЭлемента/Ext/Form.xml`. Defaults to
    /// `true` (today's behaviour) for every kind the index cannot yet prove a
    /// value for -- only `Catalog` is evidenced so far.
    use_standard_commands: bool,
}

fn parse_exchange_plan_content_blob(
    bytes: &[u8],
    object_refs: &BTreeMap<String, String>,
    type_index: &BTreeMap<String, String>,
    _metadata_order: &BTreeMap<String, usize>,
) -> Result<Vec<ExchangePlanContentItem>> {
    let inflated = inflate_raw_deflate(bytes).context("failed to inflate ExchangePlanContent")?;
    let text = String::from_utf8(inflated).context("ExchangePlanContent is not valid UTF-8")?;
    let fields = split_1c_braced_fields(text.trim_start_matches('\u{feff}'), 0)
        .context("ExchangePlanContent body is not a braced 1C value")?;
    let marker = fields
        .first()
        .map(|field| field.trim())
        .context("ExchangePlanContent body is empty")?;
    if marker != "2" {
        bail!("unsupported ExchangePlanContent marker {marker}, expected 2");
    }
    let count = fields
        .get(1)
        .context("ExchangePlanContent body has no item count")?
        .trim()
        .parse::<usize>()
        .context("ExchangePlanContent item count is not numeric")?;
    let mut items = Vec::with_capacity(count);
    let mut index = 2usize;
    for item_index in 0..count {
        let object_slot = fields
            .get(index)
            .with_context(|| format!("ExchangePlanContent item {item_index} has no metadata id"))?;
        let object_id = parse_uuid_field(object_slot.trim()).with_context(|| {
            format!(
                "ExchangePlanContent item {item_index} metadata id is not a UUID: {}",
                object_slot.trim()
            )
        })?;
        let auto_record_slot = fields.get(index + 1).with_context(|| {
            format!("ExchangePlanContent item {item_index} has no AutoRecord value")
        })?;
        let auto_record = exchange_plan_auto_record_xml(auto_record_slot.trim());
        let metadata = object_refs
            .get(&object_id)
            .or_else(|| type_index.get(&object_id))
            .cloned()
            .with_context(|| {
                format!(
                    "ExchangePlanContent item {item_index} references unsupported metadata id {object_id}"
                )
            })?;
        items.push(ExchangePlanContentItem {
            metadata_id: object_id,
            metadata,
            auto_record,
        });
        index += 2;
    }

    items.sort_by(|left, right| left.metadata_id.cmp(&right.metadata_id));

    Ok(items)
}

fn parse_business_process_flowchart_blob(
    bytes: &[u8],
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
) -> Option<BusinessProcessFlowchart> {
    let inflated = inflate_raw_deflate(bytes).ok()?;
    let text = String::from_utf8(inflated).ok()?;
    parse_business_process_flowchart_text_with_types(
        text.trim_start_matches('\u{feff}'),
        object_refs,
        metadata_object_refs,
        type_index,
        type_index_collisions,
    )
}

#[cfg(test)]
fn parse_business_process_flowchart_text(
    text: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<BusinessProcessFlowchart> {
    parse_business_process_flowchart_text_with_types(
        text,
        object_refs,
        object_refs,
        &BTreeMap::new(),
        &BTreeSet::new(),
    )
}

/// Structural, object-ref-free proof that raw-deflated text is a graphical-
/// scheme blob in the brace-tuple grammar `parse_business_process_
/// flowchart_text_with_types` decodes (shared by `BusinessProcess.
/// Flowchart` and, per the misclassification this function's caller in
/// `refs.rs` exists to fix, standalone `GraphicalSchema` Template bodies
/// too): the leading `"5"` discriminator plus a declared item count whose
/// implied record length exactly matches the text's own top-level field
/// count -- the same length check the real parser performs, factored out
/// so type-inference time (before the owning family's reference indexes
/// exist) and parse time can never drift apart. Returns the split fields
/// and declared item count on success so callers that go on to do the full
/// parse do not have to re-split the text.
fn flowchart_grammar_fields(text: &str) -> Option<(Vec<&str>, usize)> {
    let fields = split_1c_braced_fields(text, 0)?;
    if fields.first()?.trim() != "5" {
        return None;
    }
    let item_count = fields.get(2)?.trim().parse::<usize>().ok()?;
    // The record closes with one numeric field after the item pairs -- the
    // scheme's id counter; all seven evidenced flowcharts carry it and it is
    // not part of the exported XML.
    let trailer_index = item_count.checked_mul(2)?.checked_add(3)?;
    if fields.len() != trailer_index.checked_add(1)? {
        return None;
    }
    Some((fields, item_count))
}

/// Cheap, object-ref-free type-inference check: does this raw-deflated
/// template body look like a graphical-scheme blob in the flowchart
/// grammar? Used by `refs::infer_template_type_from_body` to recognize the
/// non-XML representation of a `GraphicalSchema` Template body (evidenced
/// on real ERP UH bytes -- see `output-path-collisions-and-module-text-
/// fallback-20260825.md` -- as the cause of every one of that corpus's
/// `extra` Template.txt files: the body defaulted to `TextDocument`
/// because none of `infer_template_type_from_body`'s three positive
/// markers recognized this shape). Does not attempt the full parse -- no
/// object refs are available yet at this point in the pipeline -- so a
/// body that passes this check can still fail to decode at write time,
/// which is a typed failure (fail-closed), not a silent wrong-content
/// default.
pub(super) fn looks_like_graphical_scheme_blob_text(text: &str) -> bool {
    flowchart_grammar_fields(text).is_some()
}

fn parse_business_process_flowchart_text_with_types(
    text: &str,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
) -> Option<BusinessProcessFlowchart> {
    let (fields, item_count) = flowchart_grammar_fields(text)?;
    let scheme = parse_flowchart_scheme(fields.get(1)?, object_refs)?;
    let trailer_index = item_count.checked_mul(2)?.checked_add(3)?;
    parse_flowchart_number(fields.get(trailer_index)?)?;
    let mut raw_items = Vec::<(String, String)>::with_capacity(item_count);
    let mut names = BTreeMap::<String, String>::new();
    let mut index = 3usize;
    for _ in 0..item_count {
        let code = fields.get(index)?.trim().to_string();
        let body = fields.get(index + 1)?.to_string();
        let base = parse_flowchart_base(&code, &body)?;
        names.insert(base.id, base.name);
        raw_items.push((code, body));
        index += 2;
    }

    let mut items = Vec::with_capacity(item_count);
    for (code, body) in raw_items {
        items.push(parse_flowchart_item(
            &code,
            &body,
            &names,
            object_refs,
            metadata_object_refs,
            type_index,
            type_index_collisions,
        )?);
    }

    Some(BusinessProcessFlowchart { scheme, items })
}

/// Header record: `{1, back, grid_enabled, hstep, vstep, draw_grid_mode,
/// count, key, {"N",value}, ...}` where the keyed tail carries the print
/// parameters (6..9 margins, 13 black-and-white, 16 fit-page mode). Read off
/// all seven flowcharts of the evidence base; any other key, mode or value
/// refuses the scheme.
fn parse_flowchart_scheme(
    text: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<FlowchartScheme> {
    let outer = split_1c_braced_fields(text, 0)?;
    if outer.len() != 1 {
        return None;
    }
    let fields = split_1c_braced_fields(outer.first()?, 0)?;
    if fields.first()?.trim() != "1" {
        return None;
    }
    let back_color = parse_flowchart_color(fields.get(1)?, object_refs)?;
    let grid_enabled = parse_flowchart_flag(fields.get(2)?)?;
    let grid_horizontal_step = parse_flowchart_number(fields.get(3)?)?;
    let grid_vertical_step = parse_flowchart_number(fields.get(4)?)?;
    let draw_grid_mode = match fields.get(5)?.trim() {
        "3" => "Lines",
        _ => return None,
    };
    let count = fields.get(6)?.trim().parse::<usize>().ok()?;
    if fields.len() != count.checked_mul(2)?.checked_add(7)? {
        return None;
    }
    let mut values = BTreeMap::new();
    for pair in fields[7..].chunks_exact(2) {
        let key = pair[0].trim().parse::<u32>().ok()?;
        let value = split_1c_braced_fields(pair[1], 0)?;
        if value.len() != 2 || value.first()?.trim() != r#""N""# {
            return None;
        }
        if values
            .insert(key, parse_flowchart_number(value.get(1)?)?)
            .is_some()
        {
            return None;
        }
    }
    if values.len() != 6 {
        return None;
    }
    let print_parameters = FlowchartPrintParameters {
        top_margin: values.remove(&6)?,
        left_margin: values.remove(&7)?,
        bottom_margin: values.remove(&8)?,
        right_margin: values.remove(&9)?,
        black_and_white: match values.remove(&13)?.as_str() {
            "0" => false,
            "1" => true,
            _ => return None,
        },
        fit_page_mode: match values.remove(&16)?.as_str() {
            "0" => "Auto",
            _ => return None,
        },
    };
    Some(FlowchartScheme {
        back_color,
        grid_enabled,
        grid_horizontal_step,
        grid_vertical_step,
        draw_grid_mode,
        print_parameters,
    })
}

fn parse_flowchart_number(value: &str) -> Option<String> {
    let value = value.trim();
    let digits = value.strip_prefix('-').unwrap_or(value);
    (!digits.is_empty() && digits.bytes().all(|byte| byte.is_ascii_digit()))
        .then(|| value.to_string())
}

fn parse_flowchart_flag(value: &str) -> Option<bool> {
    match value.trim() {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

/// A flowchart colour is the control-colour value the form reader decodes;
/// the unset shape `{3,4,{0}}`, which a form writes as no element, is the
/// scheme's `auto`.
fn parse_flowchart_color(value: &str, object_refs: &BTreeMap<String, String>) -> Option<String> {
    let fields = split_1c_braced_fields(value.trim(), 0)?;
    if fields.len() != 3 || fields.first()?.trim() != "3" {
        return None;
    }
    if fields.get(1)?.trim() == "4" {
        let payload = split_1c_braced_fields(fields.get(2)?, 0)?;
        return (payload.len() == 1 && payload.first()?.trim() == "0").then(|| "auto".to_string());
    }
    parse_form_control_color(value, object_refs)
}

fn parse_flowchart_item(
    code: &str,
    body: &str,
    names: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
) -> Option<FlowchartItem> {
    let fields = split_1c_braced_fields(body, 0)?;
    let base = parse_flowchart_base(code, body)?;
    let mut events = Vec::new();
    let (tag, properties) = match code {
        "0" => (
            "Decoration",
            parse_flowchart_decoration_graphics(fields.get(2)?, object_refs)?,
        ),
        "1" => {
            if fields.len() != 7 || fields.get(1)?.trim() != "3" {
                return None;
            }
            let mut properties = parse_flowchart_line_graphics(fields.get(6)?, object_refs)?;
            let from_id = fields.get(2)?.trim();
            let to_id = fields.get(4)?.trim();
            if from_id != "-1"
                && let Some(from) = &mut properties.from
            {
                from.item = names.get(from_id)?.clone();
            }
            if to_id != "-1"
                && let Some(to) = &mut properties.to
            {
                to.item = names.get(to_id)?.clone();
            }
            properties.decorative_line = parse_flowchart_flag(fields.get(5)?)?;
            ("ConnectionLine", properties)
        }
        "2" => {
            let properties = parse_flowchart_shape_graphics(fields.get(2)?, object_refs)?;
            events = parse_flowchart_named_events(fields.get(3)?, &["BeforeStart"])?;
            ("Start", properties)
        }
        "3" => {
            let properties = parse_flowchart_shape_graphics(fields.get(2)?, object_refs)?;
            events = parse_flowchart_named_events(fields.get(3)?, &["OnComplete"])?;
            ("Completion", properties)
        }
        "4" => {
            let (mut properties, tail) =
                parse_flowchart_shape_graphics_with_tail(fields.get(2)?, object_refs)?;
            if tail.len() != 3 || tail.first()?.trim() != "3" {
                return None;
            }
            properties.true_port_index = Some(parse_flowchart_number(tail.get(1)?)?);
            properties.false_port_index = Some(parse_flowchart_number(tail.get(2)?)?);
            events = parse_flowchart_named_events(fields.get(3)?, &["ConditionCheck"])?;
            ("Condition", properties)
        }
        "5" => {
            let (mut properties, tail) =
                parse_flowchart_shape_graphics_with_tail(fields.get(2)?, object_refs)?;
            if tail.len() != 3 || tail.first()?.trim() != "3" || tail.get(1)?.trim() != "2" {
                return None;
            }
            properties.group = parse_flowchart_flag(tail.get(2)?)?;
            properties.explanation = fields.get(3).and_then(|value| parse_1c_string(value));
            properties.task_description = fields.get(7).and_then(|value| parse_1c_string(value));
            properties.addressing_attributes = parse_flowchart_activity_addressing_attributes(
                &fields,
                object_refs,
                metadata_object_refs,
                type_index,
                type_index_collisions,
            )
            .unwrap_or_default();
            events = parse_flowchart_activity_events(fields.get(5)?)?;
            ("Activity", properties)
        }
        "7" => (
            "Split",
            parse_flowchart_shape_graphics(fields.get(2)?, object_refs)?,
        ),
        "8" => (
            "Join",
            parse_flowchart_shape_graphics(fields.get(2)?, object_refs)?,
        ),
        "9" => {
            let properties = parse_flowchart_shape_graphics(fields.get(2)?, object_refs)?;
            events = parse_flowchart_named_events(fields.get(3)?, &["Processing"])?;
            ("Processing", properties)
        }
        "10" => {
            let (mut properties, _tail) =
                parse_flowchart_shape_graphics_with_tail(fields.get(2)?, object_refs)?;
            properties.subprocess = fields
                .get(4)
                .and_then(|field| parse_non_zero_uuid(field.trim()))
                .and_then(|uuid| object_refs.get(&uuid).cloned());
            properties.task_description = fields.get(5).and_then(|value| parse_1c_string(value));
            events = parse_flowchart_named_events(
                fields.get(3)?,
                &[
                    "BeforeCreateTasks",
                    "OnCreateTask",
                    "OnCreateSubBusinessProcesses",
                    "OnExecute",
                    "BeforeExecute",
                    "BeforeCreateSubBusinessProcesses",
                ],
            )?;
            ("SubBusinessProcess", properties)
        }
        _ => return None,
    };

    Some(FlowchartItem {
        tag,
        id: base.id,
        uuid: base.uuid,
        name: base.name,
        title: base.title,
        tab_order: base.tab_order,
        properties,
        events,
    })
}

fn parse_flowchart_base(code: &str, body: &str) -> Option<FlowchartBase> {
    let fields = split_1c_braced_fields(body, 0)?;
    let head = split_1c_braced_fields(fields.first()?, 0)?;
    let uuid = if matches!(code, "2" | "3" | "4" | "5" | "7" | "8" | "9" | "10") {
        head.get(2).map(|value| value.trim().to_string())
    } else {
        None
    }
    .filter(|value| is_uuid_text(value));
    let base_fields = if matches!(code, "2" | "3" | "4" | "5" | "7" | "8" | "9" | "10") {
        split_1c_braced_fields(head.first()?, 0)?
    } else {
        head
    };
    let id = base_fields.get(1)?.trim().to_string();
    let title = parse_flowchart_title(base_fields.get(2)?);
    let name = parse_1c_string(base_fields.get(3)?)?;
    let tab_order = base_fields.get(4)?.trim().to_string();

    Some(FlowchartBase {
        id,
        uuid,
        name,
        title,
        tab_order,
    })
}

fn flowchart_item_properties(style: FlowchartItemStyle) -> FlowchartItemProperties {
    FlowchartItemProperties {
        style,
        location: None,
        pivot_points: Vec::new(),
        manually_moved_segments: Vec::new(),
        from: None,
        to: None,
        decorative_line: false,
        line_style: "Solid",
        text_location: "FirstSegment",
        begin_arrow: "None",
        end_arrow: "None",
        explanation: None,
        task_description: None,
        group: false,
        addressing_attributes: Vec::new(),
        subprocess: None,
        true_port_index: None,
        false_port_index: None,
    }
}

fn parse_flowchart_item_style(
    text: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<FlowchartItemStyle> {
    let fields = split_1c_braced_fields(text, 0)?;
    if fields.len() != 14
        || fields.first()?.trim() != "7"
        || fields.get(7)?.trim() != "1"
        || fields.get(8)?.trim() != "1"
        || fields.get(10)?.trim() != "0"
        || fields.get(12)?.trim() != "0"
        || fields.get(13)?.trim() != "0"
    {
        return None;
    }
    Some(FlowchartItemStyle {
        back_color: parse_flowchart_color(fields.get(1)?, object_refs)?,
        line_color: parse_flowchart_color(fields.get(2)?, object_refs)?,
        text_color: parse_flowchart_color(fields.get(3)?, object_refs)?,
        font: parse_flowchart_font_tuple(fields.get(4)?)?,
        tooltip: parse_flowchart_localized(fields.get(5)?)?,
        horizontal_align: match fields.get(6)?.trim() {
            "0" => "Left",
            "1" => "Center",
            _ => return None,
        },
        z_order: parse_flowchart_number(fields.get(9)?)?,
        transparent: parse_flowchart_flag(fields.get(11)?)?,
    })
}

/// Shape geometry: `{style, 5, left, top, right, bottom, n, points..., 4,
/// picture, border}` wrapped as `{{geometry, tail...}}`; the tail is the
/// item kind's own record and is handed back to the caller.
fn parse_flowchart_shape_graphics_with_tail<'a>(
    text: &'a str,
    object_refs: &BTreeMap<String, String>,
) -> Option<(FlowchartItemProperties, Vec<&'a str>)> {
    let outer = split_1c_braced_fields(text, 0)?;
    if outer.len() != 1 {
        return None;
    }
    let wrapper = split_1c_braced_fields(outer.first()?, 0)?;
    let geometry = split_1c_braced_fields(wrapper.first()?, 0)?;
    if geometry.get(1)?.trim() != "5" {
        return None;
    }
    let style = parse_flowchart_item_style(geometry.first()?, object_refs)?;
    let mut properties = flowchart_item_properties(style);
    properties.location = Some(FlowchartLocation {
        left: parse_flowchart_number(geometry.get(2)?)?,
        top: parse_flowchart_number(geometry.get(3)?)?,
        right: parse_flowchart_number(geometry.get(4)?)?,
        bottom: parse_flowchart_number(geometry.get(5)?)?,
    });
    let point_count = geometry.get(6)?.trim().parse::<usize>().ok()?;
    let rest = point_count.checked_mul(2)?.checked_add(7)?;
    if geometry.len() != rest.checked_add(3)? || geometry.get(rest)?.trim() != "4" {
        return None;
    }
    Some((properties, wrapper[1..].to_vec()))
}

fn parse_flowchart_shape_graphics(
    text: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<FlowchartItemProperties> {
    let (properties, tail) = parse_flowchart_shape_graphics_with_tail(text, object_refs)?;
    (tail.len() == 1 && tail.first()?.trim() == "1").then_some(properties)
}

/// Decoration geometry: `{{style, 6, left, top, right, bottom, 4, picture,
/// flag, shape, flip, angle}}`. Only the document shape with no flip and no
/// rotation is evidenced; anything else refuses.
fn parse_flowchart_decoration_graphics(
    text: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<FlowchartItemProperties> {
    let outer = split_1c_braced_fields(text, 0)?;
    if outer.len() != 1 {
        return None;
    }
    let geometry = split_1c_braced_fields(outer.first()?, 0)?;
    if geometry.len() != 12
        || geometry.get(1)?.trim() != "6"
        || geometry.get(6)?.trim() != "4"
        || !matches!(geometry.get(8)?.trim(), "0" | "1")
        || geometry.get(9)?.trim() != "10"
        || geometry.get(10)?.trim() != "0"
        || geometry.get(11)?.trim() != "0"
    {
        return None;
    }
    let style = parse_flowchart_item_style(geometry.first()?, object_refs)?;
    let mut properties = flowchart_item_properties(style);
    properties.location = Some(FlowchartLocation {
        left: parse_flowchart_number(geometry.get(2)?)?,
        top: parse_flowchart_number(geometry.get(3)?)?,
        right: parse_flowchart_number(geometry.get(4)?)?,
        bottom: parse_flowchart_number(geometry.get(5)?)?,
    });
    Some(properties)
}

/// Line geometry: `{{style, 6, n, points..., line, text_location, from_port,
/// to_port, m, segments..., begin_arrow, end_arrow}}` where each manually
/// moved segment is `x1, y1, x2, y2, index`.
fn parse_flowchart_line_graphics(
    text: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<FlowchartItemProperties> {
    let outer = split_1c_braced_fields(text, 0)?;
    if outer.len() != 1 {
        return None;
    }
    let geometry = split_1c_braced_fields(outer.first()?, 0)?;
    if geometry.get(1)?.trim() != "6" {
        return None;
    }
    let style = parse_flowchart_item_style(geometry.first()?, object_refs)?;
    let mut properties = flowchart_item_properties(style);
    let point_count = geometry.get(2)?.trim().parse::<usize>().ok()?;
    let mut points = Vec::with_capacity(point_count);
    let mut index = 3usize;
    for _ in 0..point_count {
        points.push(FlowchartPoint {
            x: parse_flowchart_number(geometry.get(index)?)?,
            y: parse_flowchart_number(geometry.get(index + 1)?)?,
        });
        index += 2;
    }
    properties.pivot_points = points;
    properties.line_style = parse_flowchart_line_style(geometry.get(index)?)?;
    properties.text_location = match geometry.get(index + 1)?.trim() {
        "0" => "FirstSegment",
        _ => return None,
    };
    properties.from = Some(FlowchartConnectionEnd {
        item: String::new(),
        port_index: parse_flowchart_number(geometry.get(index + 2)?)?,
    });
    properties.to = Some(FlowchartConnectionEnd {
        item: String::new(),
        port_index: parse_flowchart_number(geometry.get(index + 3)?)?,
    });
    let segment_count = geometry.get(index + 4)?.trim().parse::<usize>().ok()?;
    index += 5;
    let mut segments = Vec::with_capacity(segment_count);
    for _ in 0..segment_count {
        segments.push(FlowchartSegment {
            start: FlowchartPoint {
                x: parse_flowchart_number(geometry.get(index)?)?,
                y: parse_flowchart_number(geometry.get(index + 1)?)?,
            },
            end: FlowchartPoint {
                x: parse_flowchart_number(geometry.get(index + 2)?)?,
                y: parse_flowchart_number(geometry.get(index + 3)?)?,
            },
            index: parse_flowchart_number(geometry.get(index + 4)?)?,
        });
        index += 5;
    }
    properties.manually_moved_segments = segments;
    if geometry.len() != index + 2 {
        return None;
    }
    properties.begin_arrow = parse_flowchart_arrow(geometry.get(index)?)?;
    properties.end_arrow = parse_flowchart_arrow(geometry.get(index + 1)?)?;
    Some(properties)
}

fn parse_flowchart_arrow(value: &str) -> Option<&'static str> {
    match value.trim() {
        "0" => Some("None"),
        "1" => Some("Filled"),
        "2" => Some("Blank"),
        _ => None,
    }
}

impl Default for FlowchartFont {
    fn default() -> Self {
        Self {
            reference: "sys:DefaultGUIFont".to_string(),
            kind: "WindowsFont",
            height: None,
            bold: false,
            italic: false,
            underline: false,
            strikeout: false,
            scale: None,
        }
    }
}

/// Font tuple `{7, kind, ...}`: kind 1 is the system default GUI font, kind
/// 2 a style item with member fields, kind 3 the automatic font, which is
/// written with no reference at all.
fn parse_flowchart_font_tuple(text: &str) -> Option<FlowchartFont> {
    let fields = split_1c_braced_fields(text, 0)?;
    if fields.first()?.trim() != "7" {
        return None;
    }
    let kind = fields.get(1).map(|field| field.trim()).unwrap_or("1");
    let (reference, kind_xml) = match kind {
        "1" => ("sys:DefaultGUIFont".to_string(), "WindowsFont"),
        "2" => {
            let reference = fields
                .get(3)
                .and_then(|field| {
                    split_1c_braced_fields(field, 0)?
                        .first()
                        .and_then(|code| code.trim().parse::<i32>().ok())
                })
                .and_then(standard_style_item_for_code)
                .map(|(_, name)| format!("style:{name}"))
                .unwrap_or_else(|| "style:TextFont".to_string());
            (reference, "StyleItem")
        }
        "3" => {
            if fields.len() != 5
                || fields.get(2)?.trim() != "0"
                || fields.get(3)?.trim() != "1"
                || fields.get(4)?.trim() != "100"
            {
                return None;
            }
            return Some(FlowchartFont {
                reference: String::new(),
                kind: "AutoFont",
                ..FlowchartFont::default()
            });
        }
        _ => return None,
    };
    let height = font_height_xml(fields.get(2).map(|field| field.trim()));
    let (weight, italic, underline, strikeout, scale) = if fields.len() >= 10 {
        (
            fields
                .get(4)
                .and_then(|field| field.trim().parse::<i32>().ok())
                .unwrap_or(400),
            fields
                .get(5)
                .and_then(|field| parse_1c_bool_flag(field.trim()))
                .unwrap_or(false),
            fields
                .get(6)
                .and_then(|field| parse_1c_bool_flag(field.trim()))
                .unwrap_or(false),
            fields
                .get(7)
                .and_then(|field| parse_1c_bool_flag(field.trim()))
                .unwrap_or(false),
            fields.get(9).map(|field| field.trim()).unwrap_or("100"),
        )
    } else {
        (
            400,
            false,
            false,
            false,
            fields.get(5).map(|field| field.trim()).unwrap_or("100"),
        )
    };
    let scale = (scale != "100").then(|| scale.to_string());
    Some(FlowchartFont {
        reference,
        kind: kind_xml,
        height,
        bold: weight >= 700,
        italic,
        underline,
        strikeout,
        scale,
    })
}

/// Line record `{4, 0, {0}, style, 1, 0, uuid, 0}`: style 1 solid, 2 dashed.
fn parse_flowchart_line_style(text: &str) -> Option<&'static str> {
    let fields = split_1c_braced_fields(text, 0)?;
    if fields.len() != 8 || fields.first()?.trim() != "4" {
        return None;
    }
    match fields.get(3)?.trim() {
        "1" => Some("Solid"),
        "2" => Some("Dashed"),
        _ => None,
    }
}

/// Localized value `{1, count, {lang, content}...}` used by titles and
/// tooltips alike.
fn parse_flowchart_localized(text: &str) -> Option<Vec<(String, String)>> {
    let fields = split_1c_braced_fields(text, 0)?;
    if fields.first()?.trim() != "1" {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    if fields.len() != count.checked_add(2)? {
        return None;
    }
    fields[2..]
        .iter()
        .map(|field| {
            let pair = split_1c_braced_fields(field, 0)?;
            if pair.len() != 2 {
                return None;
            }
            Some((
                parse_1c_string(pair.first()?)?,
                parse_1c_string(pair.get(1)?)?,
            ))
        })
        .collect()
}

fn parse_flowchart_activity_events(text: &str) -> Option<Vec<FlowchartEvent>> {
    let handlers = parse_flowchart_event_handlers(text)?;
    Some(vec![
        FlowchartEvent {
            name: "InteractiveActivationProcessing",
            handler: None,
        },
        FlowchartEvent {
            name: "BeforeCreateTasks",
            handler: handlers.get(&1).cloned(),
        },
        FlowchartEvent {
            name: "OnCreateTask",
            handler: handlers.get(&2).cloned(),
        },
        FlowchartEvent {
            name: "OnExecute",
            handler: handlers.get(&3).cloned(),
        },
        FlowchartEvent {
            name: "CheckExecutionProcessing",
            handler: handlers.get(&4).cloned(),
        },
        FlowchartEvent {
            name: "BeforeExecute",
            handler: None,
        },
        FlowchartEvent {
            name: "BeforeExecuteInteractively",
            handler: None,
        },
    ])
}

fn parse_flowchart_activity_addressing_attributes(
    activity_fields: &[&str],
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
) -> Option<Vec<FlowchartAddressingAttribute>> {
    if activity_fields.len() != 8 {
        return None;
    }
    let collection = split_1c_braced_fields(activity_fields.get(6)?, 0)?;
    if collection.len() != 5 || collection.first()?.trim() != "4" {
        return None;
    }

    let mut owner = None::<String>;
    let mut references = BTreeSet::new();
    let mut attributes = Vec::with_capacity(4);
    for raw_member in &collection[1..] {
        let member = split_1c_braced_fields(raw_member, 0)?;
        if member.len() != 2 {
            return None;
        }
        let reference_uuid = parse_uuid_field(member.first()?.trim())?;
        let reference = object_refs.get(&reference_uuid)?.clone();
        let reference_owner = flowchart_task_addressing_attribute_owner(&reference)?;
        if owner
            .as_ref()
            .is_some_and(|expected| expected != reference_owner)
        {
            return None;
        }
        owner.get_or_insert_with(|| reference_owner.to_string());
        if !references.insert(reference.clone()) {
            return None;
        }
        attributes.push(FlowchartAddressingAttribute {
            reference,
            value: parse_flowchart_addressing_attribute_value(
                member.get(1)?,
                metadata_object_refs,
                type_index,
                type_index_collisions,
            )?,
        });
    }
    if attributes.len() != 4 || references.len() != 4 {
        return None;
    }
    attributes.sort_by(|left, right| left.reference.cmp(&right.reference));
    Some(attributes)
}

fn flowchart_task_addressing_attribute_owner(reference: &str) -> Option<&str> {
    let parts = reference.split('.').collect::<Vec<_>>();
    match parts.as_slice() {
        ["Task", owner, "AddressingAttribute", child] if !owner.is_empty() && !child.is_empty() => {
            Some(owner)
        }
        _ => None,
    }
}

fn parse_flowchart_addressing_attribute_value(
    value: &str,
    metadata_object_refs: &BTreeMap<String, String>,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
) -> Option<FlowchartAddressingAttributeValue> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.len() == 1 && fields.first()?.trim() == r#""U""# {
        return Some(FlowchartAddressingAttributeValue::Nil);
    }
    if let Some((_, value_uuid)) = parse_information_register_design_time_ref_ids(value)
        && !information_register_uuid_is_zero(&value_uuid)
    {
        // A populated reference resolves through the same owner-qualified
        // index every design-time fill value uses.
        return parse_information_register_design_time_ref(value, type_index, metadata_object_refs)
            .filter(|reference| !reference.is_empty())
            .map(FlowchartAddressingAttributeValue::DesignTimeRef);
    }
    let owner_type_id = parse_data_processor_empty_ref_fill_owner(value)?;
    let type_reference =
        unique_metadata_type_reference(type_index, type_index_collisions, &owner_type_id)?;
    let owner_reference =
        parse_generated_metadata_reference_owner(type_reference)?.owner_reference();
    Some(FlowchartAddressingAttributeValue::DesignTimeRef(format!(
        "{owner_reference}.EmptyRef"
    )))
}

fn parse_flowchart_named_events(text: &str, names: &[&'static str]) -> Option<Vec<FlowchartEvent>> {
    let handlers = parse_flowchart_event_handlers(text)?;
    Some(
        names
            .iter()
            .enumerate()
            .map(|(index, name)| FlowchartEvent {
                name,
                handler: handlers.get(&(index as i32)).cloned(),
            })
            .collect(),
    )
}

fn parse_flowchart_event_handlers(text: &str) -> Option<BTreeMap<i32, String>> {
    let fields = split_1c_braced_fields(text, 0)?;
    let count = fields.first()?.trim().parse::<usize>().ok()?;
    let mut handlers = BTreeMap::new();
    for field in fields.iter().skip(1).take(count) {
        let event = split_1c_braced_fields(field, 0)?;
        let index = event.first()?.trim().parse::<i32>().ok()?;
        let handler = parse_1c_string(event.get(1)?)?;
        handlers.insert(index, handler);
    }
    Some(handlers)
}

fn parse_flowchart_title(text: &str) -> Vec<(String, String)> {
    let Some(fields) = split_1c_braced_fields(text, 0) else {
        return Vec::new();
    };
    let count = fields
        .get(1)
        .and_then(|value| value.trim().parse::<usize>().ok())
        .unwrap_or(0);
    fields
        .iter()
        .skip(2)
        .take(count)
        .filter_map(|field| {
            let pair = split_1c_braced_fields(field, 0)?;
            Some((
                parse_1c_string(pair.first()?)?,
                parse_1c_string(pair.get(1)?)?,
            ))
        })
        .collect()
}

fn parse_1c_string(text: &str) -> Option<String> {
    let text = text.trim();
    let inner = text.strip_prefix('"')?.strip_suffix('"')?;
    Some(inner.replace("\"\"", "\""))
}

fn exchange_plan_auto_record_xml(value: &str) -> &'static str {
    match value {
        "0" => "Deny",
        "1" => "Allow",
        "2" => "Auto",
        _ => "Auto",
    }
}

fn format_exchange_plan_content_xml(items: &[ExchangePlanContentItem]) -> String {
    let mut xml = String::from(
        "\u{feff}<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n\
<ExchangePlanContent xmlns=\"http://v8.1c.ru/8.3/xcf/extrnprops\" xmlns:xr=\"http://v8.1c.ru/8.3/xcf/readable\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" version=\"2.20\">\r\n",
    );
    for item in items {
        xml.push_str(&format!(
            "\t<Item>\r\n\
\t\t<Metadata>{}</Metadata>\r\n\
\t\t<AutoRecord>{}</AutoRecord>\r\n\
\t</Item>\r\n",
            escape_xml_text(&item.metadata),
            item.auto_record
        ));
    }
    xml.push_str("</ExchangePlanContent>");
    xml
}

fn format_business_process_flowchart_xml(flowchart: &BusinessProcessFlowchart) -> String {
    let scheme = &flowchart.scheme;
    let mut xml = String::from(
        "\u{feff}<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n\
<GraphicalSchema xmlns=\"http://v8.1c.ru/8.3/xcf/scheme\" xmlns:sch=\"http://v8.1c.ru/8.2/data/graphscheme\" xmlns:style=\"http://v8.1c.ru/8.1/data/ui/style\" xmlns:v8=\"http://v8.1c.ru/8.1/data/core\" xmlns:v8ui=\"http://v8.1c.ru/8.1/data/ui\" xmlns:web=\"http://v8.1c.ru/8.1/data/ui/colors/web\" xmlns:win=\"http://v8.1c.ru/8.1/data/ui/colors/windows\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" version=\"2.20\">\r\n",
    );
    xml.push_str(&format!(
        "\t<BackColor>{}</BackColor>\r\n\
\t<GridEnabled>{}</GridEnabled>\r\n\
\t<DrawGridMode>{}</DrawGridMode>\r\n\
\t<GridHorizontalStep>{}</GridHorizontalStep>\r\n\
\t<GridVerticalStep>{}</GridVerticalStep>\r\n",
        escape_xml_element_text(&scheme.back_color),
        xml_bool(scheme.grid_enabled),
        scheme.draw_grid_mode,
        escape_xml_element_text(&scheme.grid_horizontal_step),
        escape_xml_element_text(&scheme.grid_vertical_step),
    ));
    let print = &scheme.print_parameters;
    xml.push_str(&format!(
        "\t<PrintParameters>\r\n\
\t\t<TopMargin>{}</TopMargin>\r\n\
\t\t<LeftMargin>{}</LeftMargin>\r\n\
\t\t<BottomMargin>{}</BottomMargin>\r\n\
\t\t<RightMargin>{}</RightMargin>\r\n\
\t\t<BlackAndWhite>{}</BlackAndWhite>\r\n\
\t\t<FitPageMode>{}</FitPageMode>\r\n\
\t</PrintParameters>\r\n\
\t<Items>\r\n",
        escape_xml_element_text(&print.top_margin),
        escape_xml_element_text(&print.left_margin),
        escape_xml_element_text(&print.bottom_margin),
        escape_xml_element_text(&print.right_margin),
        xml_bool(print.black_and_white),
        print.fit_page_mode,
    ));
    for item in &flowchart.items {
        push_flowchart_item_xml(&mut xml, item);
    }
    xml.push_str("\t</Items>\r\n</GraphicalSchema>");
    xml
}

fn push_flowchart_item_xml(xml: &mut String, item: &FlowchartItem) {
    if let Some(uuid) = &item.uuid {
        xml.push_str(&format!(
            "\t\t<{} id=\"{}\" uuid=\"{}\">\r\n",
            item.tag,
            escape_xml_text(&item.id),
            escape_xml_text(uuid)
        ));
    } else {
        xml.push_str(&format!(
            "\t\t<{} id=\"{}\">\r\n",
            item.tag,
            escape_xml_text(&item.id)
        ));
    }
    let style = &item.properties.style;
    xml.push_str("\t\t\t<Properties>\r\n");
    xml.push_str(&format!(
        "\t\t\t\t<Name>{}</Name>\r\n",
        escape_xml_element_text(&item.name)
    ));
    push_flowchart_localized_xml(xml, "Title", &item.title);
    push_flowchart_localized_xml(xml, "ToolTip", &style.tooltip);
    xml.push_str(&format!(
        "\t\t\t\t<TabOrder>{}</TabOrder>\r\n",
        escape_xml_element_text(&item.tab_order)
    ));
    xml.push_str(&format!(
        "\t\t\t\t<BackColor>{}</BackColor>\r\n",
        escape_xml_element_text(&style.back_color)
    ));
    xml.push_str(&format!(
        "\t\t\t\t<TextColor>{}</TextColor>\r\n",
        escape_xml_element_text(&style.text_color)
    ));
    xml.push_str(&format!(
        "\t\t\t\t<LineColor>{}</LineColor>\r\n",
        escape_xml_element_text(&style.line_color)
    ));
    xml.push_str("\t\t\t\t<GroupNumber>0</GroupNumber>\r\n");
    xml.push_str(&format!(
        "\t\t\t\t<ZOrder>{}</ZOrder>\r\n",
        escape_xml_element_text(&style.z_order)
    ));
    xml.push_str("\t\t\t\t<Hyperlink>false</Hyperlink>\r\n");
    xml.push_str(&format!(
        "\t\t\t\t<Transparent>{}</Transparent>\r\n",
        xml_bool(style.transparent)
    ));
    push_flowchart_font_xml(xml, &style.font);
    xml.push_str(&format!(
        "\t\t\t\t<HorizontalAlign>{}</HorizontalAlign>\r\n",
        style.horizontal_align
    ));
    xml.push_str("\t\t\t\t<VerticalAlign>Center</VerticalAlign>\r\n");
    xml.push_str("\t\t\t\t<PictureLocation>Left</PictureLocation>\r\n");
    if item.tag == "ConnectionLine" {
        push_flowchart_line_properties_xml(xml, &item.properties);
    } else {
        push_flowchart_shape_properties_xml(xml, item);
    }
    xml.push_str("\t\t\t</Properties>\r\n");
    if !item.events.is_empty() {
        xml.push_str("\t\t\t<Events>\r\n");
        for event in &item.events {
            if let Some(handler) = &event.handler {
                xml.push_str(&format!(
                    "\t\t\t\t<Event name=\"{}\">{}</Event>\r\n",
                    event.name,
                    escape_xml_element_text(handler)
                ));
            } else {
                xml.push_str(&format!("\t\t\t\t<Event name=\"{}\"/>\r\n", event.name));
            }
        }
        xml.push_str("\t\t\t</Events>\r\n");
    }
    xml.push_str(&format!("\t\t</{}>\r\n", item.tag));
}

fn push_flowchart_localized_xml(xml: &mut String, tag: &str, values: &[(String, String)]) {
    if values.is_empty() {
        xml.push_str(&format!("\t\t\t\t<{tag}/>\r\n"));
        return;
    }
    xml.push_str(&format!("\t\t\t\t<{tag}>\r\n"));
    for (lang, content) in values {
        xml.push_str("\t\t\t\t\t<v8:item>\r\n");
        xml.push_str(&format!(
            "\t\t\t\t\t\t<v8:lang>{}</v8:lang>\r\n",
            escape_xml_element_text(lang)
        ));
        xml.push_str(&format!(
            "\t\t\t\t\t\t<v8:content>{}</v8:content>\r\n",
            escape_xml_element_text(content)
        ));
        xml.push_str("\t\t\t\t\t</v8:item>\r\n");
    }
    xml.push_str(&format!("\t\t\t\t</{tag}>\r\n"));
}

fn push_flowchart_font_xml(xml: &mut String, font: &FlowchartFont) {
    if font.kind == "AutoFont" {
        xml.push_str("\t\t\t\t<Font kind=\"AutoFont\"/>\r\n");
        return;
    }
    xml.push_str("\t\t\t\t<Font");
    if font.reference.starts_with("sys:") {
        xml.push_str(" xmlns:sys=\"http://v8.1c.ru/8.1/data/ui/fonts/system\"");
    }
    xml.push_str(&format!(" ref=\"{}\"", escape_xml_text(&font.reference)));
    if let Some(height) = &font.height {
        xml.push_str(&format!(" height=\"{}\"", escape_xml_text(height)));
    }
    if font.bold || font.italic || font.underline || font.strikeout {
        xml.push_str(&format!(
            " bold=\"{}\" italic=\"{}\" underline=\"{}\" strikeout=\"{}\"",
            xml_bool(font.bold),
            xml_bool(font.italic),
            xml_bool(font.underline),
            xml_bool(font.strikeout)
        ));
    }
    xml.push_str(&format!(" kind=\"{}\"", font.kind));
    if let Some(scale) = &font.scale {
        xml.push_str(&format!(" scale=\"{}\"", escape_xml_text(scale)));
    }
    xml.push_str("/>\r\n");
}

fn push_flowchart_shape_properties_xml(xml: &mut String, item: &FlowchartItem) {
    if let Some(location) = &item.properties.location {
        xml.push_str(&format!(
            "\t\t\t\t<Location top=\"{}\" left=\"{}\" bottom=\"{}\" right=\"{}\"/>\r\n",
            escape_xml_text(&location.top),
            escape_xml_text(&location.left),
            escape_xml_text(&location.bottom),
            escape_xml_text(&location.right)
        ));
    }
    if matches!(
        item.tag,
        "Start"
            | "Activity"
            | "Condition"
            | "Completion"
            | "Processing"
            | "Split"
            | "Join"
            | "SubBusinessProcess"
    ) {
        xml.push_str("\t\t\t\t<Border width=\"1\" gap=\"false\">\r\n");
        xml.push_str(
            "\t\t\t\t\t<v8ui:style xsi:type=\"sch:ConnectorLineType\">Solid</v8ui:style>\r\n",
        );
        xml.push_str("\t\t\t\t</Border>\r\n");
    }
    xml.push_str("\t\t\t\t<Picture/>\r\n");
    xml.push_str("\t\t\t\t<PictureSize>AutoSize</PictureSize>\r\n");
    if item.tag == "Activity" {
        xml.push_str(&format!(
            "\t\t\t\t<TaskDescription>{}</TaskDescription>\r\n",
            escape_xml_element_text(item.properties.task_description.as_deref().unwrap_or(""))
        ));
        xml.push_str(&format!(
            "\t\t\t\t<Explanation>{}</Explanation>\r\n",
            escape_xml_element_text(item.properties.explanation.as_deref().unwrap_or(""))
        ));
        xml.push_str(&format!(
            "\t\t\t\t<Group>{}</Group>\r\n",
            xml_bool(item.properties.group)
        ));
        push_flowchart_addressing_attributes_xml(xml, &item.properties.addressing_attributes);
    }
    if item.tag == "SubBusinessProcess" {
        if let Some(subprocess) = &item.properties.subprocess {
            xml.push_str(&format!(
                "\t\t\t\t<Subprocess>{}</Subprocess>\r\n",
                escape_xml_element_text(subprocess)
            ));
        }
        xml.push_str(&format!(
            "\t\t\t\t<TaskDescription>{}</TaskDescription>\r\n",
            escape_xml_element_text(item.properties.task_description.as_deref().unwrap_or(""))
        ));
    }
    if item.tag == "Condition" {
        xml.push_str(&format!(
            "\t\t\t\t<TruePortIndex>{}</TruePortIndex>\r\n",
            item.properties.true_port_index.as_deref().unwrap_or("3")
        ));
        xml.push_str(&format!(
            "\t\t\t\t<FalsePortIndex>{}</FalsePortIndex>\r\n",
            item.properties.false_port_index.as_deref().unwrap_or("1")
        ));
    }
    if item.tag == "Decoration" {
        xml.push_str("\t\t\t\t<Shape>Document</Shape>\r\n");
        xml.push_str("\t\t\t\t<FlipMode>0</FlipMode>\r\n");
        xml.push_str("\t\t\t\t<Angle xsi:type=\"xs:decimal\">0</Angle>\r\n");
    }
}

fn push_flowchart_addressing_attributes_xml(
    xml: &mut String,
    attributes: &[FlowchartAddressingAttribute],
) {
    if attributes.is_empty() {
        return;
    }
    xml.push_str("\t\t\t\t<AddressingAttributes>\r\n");
    for attribute in attributes {
        xml.push_str(&format!(
            "\t\t\t\t\t<AddressingAttribute ref=\"{}\">\r\n",
            escape_xml_text(&attribute.reference)
        ));
        match &attribute.value {
            FlowchartAddressingAttributeValue::Nil => {
                xml.push_str("\t\t\t\t\t\t<Value xsi:nil=\"true\"/>\r\n");
            }
            FlowchartAddressingAttributeValue::DesignTimeRef(reference) => {
                xml.push_str(&format!(
                    "\t\t\t\t\t\t<Value xmlns:d7p1=\"http://v8.1c.ru/8.3/xcf/readable\" xsi:type=\"d7p1:DesignTimeRef\">{}</Value>\r\n",
                    escape_xml_element_text(reference)
                ));
            }
        }
        xml.push_str("\t\t\t\t\t</AddressingAttribute>\r\n");
    }
    xml.push_str("\t\t\t\t</AddressingAttributes>\r\n");
}

fn push_flowchart_line_properties_xml(xml: &mut String, properties: &FlowchartItemProperties) {
    xml.push_str("\t\t\t\t<PivotPoints>\r\n");
    for point in &properties.pivot_points {
        xml.push_str(&format!(
            "\t\t\t\t\t<Point x=\"{}\" y=\"{}\"/>\r\n",
            escape_xml_text(&point.x),
            escape_xml_text(&point.y)
        ));
    }
    xml.push_str("\t\t\t\t</PivotPoints>\r\n");
    if !properties.manually_moved_segments.is_empty() {
        xml.push_str("\t\t\t\t<ManualyMovedSegments>\r\n");
        for segment in &properties.manually_moved_segments {
            xml.push_str(&format!(
                "\t\t\t\t\t<Segment index=\"{}\">\r\n",
                escape_xml_text(&segment.index)
            ));
            xml.push_str(&format!(
                "\t\t\t\t\t\t<Start x=\"{}\" y=\"{}\"/>\r\n",
                escape_xml_text(&segment.start.x),
                escape_xml_text(&segment.start.y)
            ));
            xml.push_str(&format!(
                "\t\t\t\t\t\t<End x=\"{}\" y=\"{}\"/>\r\n",
                escape_xml_text(&segment.end.x),
                escape_xml_text(&segment.end.y)
            ));
            xml.push_str("\t\t\t\t\t</Segment>\r\n");
        }
        xml.push_str("\t\t\t\t</ManualyMovedSegments>\r\n");
    }
    xml.push_str("\t\t\t\t<Connect>\r\n");
    push_flowchart_connection_end_xml(xml, "From", properties.from.as_ref());
    push_flowchart_connection_end_xml(xml, "To", properties.to.as_ref());
    xml.push_str("\t\t\t\t</Connect>\r\n");
    xml.push_str("\t\t\t\t<Line width=\"1\" gap=\"false\">\r\n");
    xml.push_str(&format!(
        "\t\t\t\t\t<v8ui:style xsi:type=\"sch:ConnectorLineType\">{}</v8ui:style>\r\n",
        properties.line_style
    ));
    xml.push_str("\t\t\t\t</Line>\r\n");
    xml.push_str(&format!(
        "\t\t\t\t<DecorativeLine>{}</DecorativeLine>\r\n",
        xml_bool(properties.decorative_line)
    ));
    xml.push_str(&format!(
        "\t\t\t\t<TextLocation>{}</TextLocation>\r\n",
        properties.text_location
    ));
    xml.push_str(&format!(
        "\t\t\t\t<BeginArrow>{}</BeginArrow>\r\n",
        properties.begin_arrow
    ));
    xml.push_str(&format!(
        "\t\t\t\t<EndArrow>{}</EndArrow>\r\n",
        properties.end_arrow
    ));
}

fn push_flowchart_connection_end_xml(
    xml: &mut String,
    tag: &str,
    end: Option<&FlowchartConnectionEnd>,
) {
    let item = end.map(|end| end.item.as_str()).unwrap_or("");
    let port_index = end.map(|end| end.port_index.as_str()).unwrap_or("0");
    xml.push_str(&format!("\t\t\t\t\t<{tag}>\r\n"));
    if item.is_empty() {
        xml.push_str("\t\t\t\t\t\t<Item/>\r\n");
    } else {
        xml.push_str(&format!(
            "\t\t\t\t\t\t<Item>{}</Item>\r\n",
            escape_xml_element_text(item)
        ));
    }
    xml.push_str(&format!(
        "\t\t\t\t\t\t<PortIndex>{}</PortIndex>\r\n",
        escape_xml_element_text(port_index)
    ));
    xml.push_str(&format!("\t\t\t\t\t</{tag}>\r\n"));
}

#[allow(dead_code)]
fn module_body_paths(rows: &[ConfigRow]) -> BTreeMap<String, PathBuf> {
    let metadata_texts = build_metadata_text_rows(rows);
    module_body_paths_from_texts(rows, &metadata_texts)
}

fn module_body_paths_from_texts(
    rows: &[ConfigRow],
    metadata_texts: &[MetadataTextRow],
) -> BTreeMap<String, PathBuf> {
    let file_names = rows
        .iter()
        .map(|row| row.file_name.as_str())
        .collect::<BTreeSet<_>>();
    let mut paths = configuration_module_body_paths(&file_names);

    for row in metadata_texts {
        let Some(entries) = parse_module_body_source_paths_from_metadata_text(row, &file_names)
        else {
            continue;
        };
        paths.extend(entries);
    }
    let form_refs = build_complete_form_source_reference_index(metadata_texts);
    paths.extend(form_module_body_paths(&form_refs, &file_names));

    paths
}

fn configuration_module_body_paths(file_names: &BTreeSet<&str>) -> BTreeMap<String, PathBuf> {
    let mut suffixes_by_id = BTreeMap::<&str, BTreeSet<&str>>::new();
    for file_name in file_names {
        let Some((metadata_id, suffix)) = file_name.rsplit_once('.') else {
            continue;
        };
        if metadata_id.is_empty() {
            continue;
        }
        suffixes_by_id
            .entry(metadata_id)
            .or_default()
            .insert(suffix);
    }

    let mut paths = BTreeMap::new();
    for (metadata_id, suffixes) in suffixes_by_id {
        if file_names.contains(metadata_id) || !is_configuration_module_group(&suffixes) {
            continue;
        }
        for route in
            crate::compiler::families::assets::SourceAssetRegistry.module_routes("Configuration")
        {
            let suffix = route.suffix().trim_start_matches('.');
            let body_id = format!("{metadata_id}.{suffix}");
            if file_names.contains(body_id.as_str()) {
                paths.insert(body_id, PathBuf::from(route.relative_path()));
            }
        }
    }

    paths
}

fn form_module_body_paths(
    form_refs: &BTreeMap<String, FormSourceReference>,
    file_names: &BTreeSet<&str>,
) -> BTreeMap<String, PathBuf> {
    let mut paths = BTreeMap::new();
    for (form_uuid, form_ref) in form_refs {
        let body_id = format!("{form_uuid}.0");
        if !file_names.contains(body_id.as_str()) {
            continue;
        }
        let mut form_dir = form_ref.relative_path.clone();
        form_dir.set_extension("");
        let route = crate::compiler::families::assets::SourceAssetRegistry
            .route(
                "Form",
                crate::compiler::families::assets::SourceAssetRole::FormModule,
            )
            .expect("form-module route is registered");
        paths.insert(body_id, form_dir.join(route.relative_path()));
    }
    paths
}

fn is_configuration_module_group(suffixes: &BTreeSet<&str>) -> bool {
    let registry = crate::compiler::families::assets::SourceAssetRegistry;
    registry
        .module_routes("Configuration")
        .all(|route| suffixes.contains(route.suffix().trim_start_matches('.')))
        && registry
            .configuration_routes()
            .filter(|route| {
                route.codec() != crate::compiler::families::assets::SourceAssetCodec::Module
            })
            .any(|route| suffixes.contains(route.suffix().trim_start_matches('.')))
}

#[allow(dead_code)]
fn parse_module_body_source_paths_from_metadata_blob(
    blob: &[u8],
    uuid: &str,
    file_names: &BTreeSet<&str>,
) -> Option<BTreeMap<String, PathBuf>> {
    let row = metadata_text_row_from_blob(uuid, blob)?;
    parse_module_body_source_paths_from_metadata_text(&row, file_names)
}

fn parse_module_body_source_paths_from_metadata_text(
    row: &MetadataTextRow,
    file_names: &BTreeSet<&str>,
) -> Option<BTreeMap<String, PathBuf>> {
    let uuid = row.file_name.as_str();
    let kind = row.kind.as_deref()?;
    let folder = row.folder?;
    let header = row.header.as_ref()?;
    let mut paths = BTreeMap::new();
    for suffix in MODULE_BODY_SUFFIXES {
        let body_id = format!("{uuid}.{suffix}");
        if !file_names.contains(body_id.as_str()) {
            continue;
        }
        if let Some(path) = module_owner_source_path(kind, folder, &header.name, suffix) {
            paths.insert(body_id, path);
        }
    }
    paths.extend(nested_command_module_source_paths(
        kind,
        folder,
        &header.name,
        uuid,
        &row.text,
        file_names,
    ));

    Some(paths)
}

fn nested_command_module_source_paths(
    kind: &str,
    folder: &str,
    owner_name: &str,
    owner_uuid: &str,
    text: &str,
    file_names: &BTreeSet<&str>,
) -> BTreeMap<String, PathBuf> {
    if !metadata_kind_can_own_commands(kind) {
        return BTreeMap::new();
    }

    let mut paths = BTreeMap::new();
    for command in nested_command_headers_for_owner_from_text(kind, text, owner_uuid) {
        let body_id = format!("{}.2", command.uuid);
        if !file_names.contains(body_id.as_str()) {
            continue;
        }
        let route = crate::compiler::families::assets::SourceAssetRegistry
            .route(
                "Command",
                crate::compiler::families::assets::SourceAssetRole::CommandModule,
            )
            .expect("nested-command module route is registered");
        let path = PathBuf::from(folder)
            .join(sanitize_source_path_segment(owner_name))
            .join("Commands")
            .join(sanitize_source_path_segment(&command.name))
            .join(route.relative_path());
        paths.insert(body_id, path);
    }

    paths
}

fn metadata_kind_can_own_commands(kind: &str) -> bool {
    !matches!(
        kind,
        "CommonModule"
            | "CommonCommand"
            | "CommonForm"
            | "CommonPicture"
            | "CommonTemplate"
            | "CommandGroup"
            | "Constant"
            | "DefinedType"
            | "EventSubscription"
            | "FunctionalOption"
            | "FunctionalOptionsParameter"
            | "Language"
            | "Role"
            | "SessionParameter"
            | "StyleItem"
            | "XDTOPackage"
    )
}

fn metadata_kind_can_own_forms(kind: &str) -> bool {
    matches!(
        kind,
        "AccumulationRegister"
            | "AccountingRegister"
            | "BusinessProcess"
            | "CalculationRegister"
            | "Catalog"
            | "ChartOfAccounts"
            | "ChartOfCalculationTypes"
            | "ChartOfCharacteristicTypes"
            | "DataProcessor"
            | "Document"
            | "DocumentJournal"
            | "Enum"
            | "ExchangePlan"
            // Confirmed against native `Forms/` subdirectories across all
            // seven gate corpora (uh-r1: 4 023 `Forms/` dirs by family, plus
            // sslbase/ssl-r1/ut-r1/MDM_Management): every family the native
            // tree actually nests forms under is listed here. `FilterCriterion`
            // (metadata_source_for_text's code-14 kind, distinct from the
            // `FilterCriteria` folder name) is the one gap this swept up --
            // two ERP УХ forms (uuid 4db7c7f9-d81c-4a93-91b1-3f1eff5c57ae,
            // 475fb3fb-ae3f-4375-a79d-87be89d68830) fell to the CommonForms
            // fallback and collided there for want of it. No corpus's
            // FilterCriteria objects own a Templates/ subdirectory, so
            // metadata_kind_can_own_templates is left alone (see
            // docs/evidence/output-path-collisions-and-module-text-fallback-20260825.md).
            | "FilterCriterion"
            | "InformationRegister"
            | "Report"
            | "SettingsStorage"
            | "Task"
    )
}

fn metadata_kind_can_own_templates(kind: &str) -> bool {
    matches!(
        kind,
        "AccumulationRegister"
            | "AccountingRegister"
            | "BusinessProcess"
            | "CalculationRegister"
            | "Catalog"
            | "ChartOfAccounts"
            | "ChartOfCalculationTypes"
            | "ChartOfCharacteristicTypes"
            | "DataProcessor"
            | "Document"
            | "DocumentJournal"
            | "Enum"
            | "ExchangePlan"
            | "InformationRegister"
            | "Report"
            | "SettingsStorage"
            | "Task"
    )
}

fn metadata_kind_needs_form_template_reference_indexes(kind: &str) -> bool {
    matches!(kind, "Enum") || metadata_kind_uses_simple_form_template_child_objects(kind)
}

fn nested_command_headers_from_text(text: &str, owner_uuid: &str) -> Vec<MetadataHeader> {
    nested_headers_from_text_inside_object_code(text, owner_uuid, 9)
}

fn nested_command_headers_for_owner_from_text(
    owner_kind: &str,
    text: &str,
    owner_uuid: &str,
) -> Vec<MetadataHeader> {
    nested_headers_with_offsets_from_text(text, owner_uuid, |marker_start| {
        // A command entry comes in two shapes. The long one wraps its payload
        // in `{9, …}` and its header in `{3, …}`; the short one uses `{8, …}`
        // and `{2, …}` and was invisible to the code-9 test alone -- 19 of ERP
        // УХ 3.2.12.6's 1,097 commands are written that way, among them every
        // command of `DataProcessors/ЗакрытиеПериодаМСФО`,
        // `Reports/АнализПоставок` and
        // `InformationRegisters/ВерсииОбъектовДляЕИС`, whose owners' role
        // rights therefore lost the object entirely.
        //
        // The shape is not what identifies a command; the collection it sits
        // in is. `COMMAND_COLLECTION_LIST_MARKERS` carries that measurement:
        // inside those spans there are only commands, and outside them there
        // are none. The code-9 arm is kept exactly as it was so this can only
        // add names, never move one.
        (is_offset_inside_command_collection(text, marker_start)
            || (is_offset_inside_metadata_object_code(text, marker_start, 9)
                && register_child_object_tag(owner_kind, text, marker_start).is_none()))
    })
    .into_iter()
    .map(|(header, _)| header)
    .collect()
}

/// Owned commands carry the same `<Properties>` block whichever family owns
/// them; the families that read it were simply enumerated one at a time. This
/// reads the block for every remaining owner through the shared command reader
/// instead of emitting a header-only `<Command>` and calling it done -- an
/// owner whose command the reader cannot decode still degrades to the header,
/// exactly as before.
fn nested_child_commands_for_owner_from_text(
    owner_kind: &str,
    text: &str,
    owner_uuid: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Vec<MetadataChildCommand> {
    nested_command_headers_for_owner_from_text(owner_kind, text, owner_uuid)
        .into_iter()
        .map(|header| {
            let properties = parse_common_command_properties_from_text(
                text,
                &header.uuid,
                type_index,
                object_refs,
            );
            MetadataChildCommand { header, properties }
        })
        .collect()
}

fn nested_child_commands_from_text(
    text: &str,
    owner_uuid: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Vec<MetadataChildCommand> {
    nested_command_headers_from_text(text, owner_uuid)
        .into_iter()
        .map(|header| {
            let properties = parse_common_command_properties_from_text(
                text,
                &header.uuid,
                type_index,
                object_refs,
            );
            MetadataChildCommand { header, properties }
        })
        .collect()
}

fn parse_information_register_child_commands(
    text: &str,
    owner_uuid: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Vec<MetadataChildCommand> {
    nested_headers_with_offsets_from_text(text, owner_uuid, |marker_start| {
        is_offset_inside_metadata_object_code(text, marker_start, 9)
            && register_child_object_tag("InformationRegister", text, marker_start).is_none()
    })
    .into_iter()
    .map(|(header, marker_start)| MetadataChildCommand {
        properties: parse_information_register_child_command_properties(
            text,
            marker_start,
            &header,
            type_index,
            object_refs,
        ),
        header,
    })
    .collect()
}

fn parse_information_register_child_command_properties(
    text: &str,
    marker_start: usize,
    header: &MetadataHeader,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<CommonCommandProperties> {
    let mut parsed =
        metadata_object_field_candidates_around_header(text, marker_start, &header.uuid)
            .into_iter()
            .filter_map(|fields| {
                parse_information_register_child_command_properties_from_fields(
                    &fields,
                    header,
                    type_index,
                    object_refs,
                )
            });
    let value = parsed.next()?;
    if parsed.next().is_some() {
        return None;
    }
    Some(value)
}

fn parse_information_register_child_command_properties_from_fields(
    fields: &[&str],
    header: &MetadataHeader,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<CommonCommandProperties> {
    // Two independent instances of the same recurring omitted-trailing-
    // default-field defect in this one function: the outer command block
    // itself (mirrors `parse_common_command_properties_from_text`'s
    // already-evidenced `{9,`/`{8,` pair -- the trailing
    // `OnMainServerUnavailableBehavior` slot at index 12 is omitted, not
    // written `0`, whenever left at default), and the nested header at
    // index 9 (the same code27-adjacent short-wrapper omission
    // `register_common_child_header_matches` just above and `06249bd`
    // document). This function is InformationRegister-child-command-only,
    // so smaller blast radius than either sibling, but the same class.
    let command_has_trailing_default = match fields.len() {
        13 => true,
        12 => false,
        _ => return None,
    };
    if fields.first()?.trim()
        != (if command_has_trailing_default {
            "9"
        } else {
            "8"
        })
        || fields.get(4)?.trim() != "1"
        || fields.get(6)?.trim() != "0"
        || (command_has_trailing_default && fields.get(12)?.trim() != "0")
    {
        return None;
    }
    let (picture_ref, picture_load_transparent) =
        parse_information_register_command_picture_descriptor(fields.get(1)?, object_refs)?;
    let header_fields = split_1c_braced_fields(fields.get(9)?, 0)?;
    let header_has_trailing_default = match header_fields.len() {
        9 => true,
        8 => false,
        _ => return None,
    };
    if header_fields.first()?.trim()
        != (if header_has_trailing_default {
            "3"
        } else {
            "2"
        })
        || metadata_header_field_index(&header_fields, &header.uuid) != Some(1)
    {
        return None;
    }
    let parsed_header = parse_metadata_header_from_text(fields.get(9)?, &header.uuid)?;
    if parsed_header.uuid != header.uuid
        || parsed_header.name != header.name
        || parsed_header.synonyms != header.synonyms
        || parsed_header.comment != header.comment
    {
        return None;
    }

    let representation = match fields.get(2)?.trim() {
        "0" => "Text",
        "1" => "Picture",
        "2" => "PictureAndText",
        "3" => "Auto",
        _ => return None,
    };
    let shortcut = parse_information_register_command_shortcut(fields.get(5)?)?;
    let group_fields = split_1c_braced_fields(fields.get(7)?, 0)?;
    if group_fields.len() != 2
        || group_fields.first()?.trim() != "1"
        || parse_non_zero_uuid(group_fields.get(1)?.trim()).is_none()
    {
        return None;
    }
    let group = parse_common_command_group_value(fields.get(7)?, object_refs)?;
    let command_parameter_types = stable_partition_metadata_types(
        parse_information_register_type_pattern(fields.get(8)?, type_index)?,
    );
    let parameter_use_mode = match fields.get(11)?.trim() {
        "0" => "Single",
        "1" => "Multiple",
        _ => return None,
    };

    Some(CommonCommandProperties {
        representation,
        picture_ref,
        picture_load_transparent,
        tooltip: parse_information_register_localized_value(fields.get(3)?)?,
        shortcut,
        include_help_in_contents: false,
        group: Some(group),
        command_parameter_types,
        parameter_use_mode,
        modifies_data: information_register_bool(fields.get(10)?)?,
        on_main_server_unavailable_behavior: "Auto",
    })
}

fn parse_information_register_command_picture_descriptor(
    value: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<(Option<String>, bool)> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.len() != 9
        || fields.first()?.trim() != "4"
        || parse_1c_quoted_string(fields.get(3)?.trim())?.as_str() != ""
        || fields.get(4)?.trim() != "-1"
        || fields.get(5)?.trim() != "-1"
        || fields.get(7)?.trim() != "0"
        || parse_1c_quoted_string(fields.get(8)?.trim())?.as_str() != ""
    {
        return None;
    }

    let load_transparent = information_register_bool(fields.get(6)?)?;
    let reference = split_1c_braced_fields(fields.get(2)?, 0)?;
    match fields.get(1)?.trim() {
        "0" if reference.len() == 1 && reference.first()?.trim() == "0" && load_transparent => {
            Some((None, load_transparent))
        }
        "1" if reference.len() == 1
            && reference.first()?.trim() == STD_PICTURE_PRINT_DESCRIPTOR_CODE =>
        {
            Some((Some("StdPicture.Print".to_string()), load_transparent))
        }
        // A set picture whose reference is the bare index `0` and carries no
        // identifier. The platform has no name for that index, so it writes the
        // index itself: `<xr:Ref>0</xr:Ref>`. Both readings of the reference
        // tuple agree here -- `{0}` as the index-only form of `{0,<uuid>}` and
        // `{0}` as the index form the negative standard-picture codes use --
        // and neither leaves room for another rendering. The guard is the exact
        // shape, so no other descriptor can reach it.
        "1" if reference.len() == 1 && reference.first()?.trim() == "0" => {
            Some((Some("0".to_string()), load_transparent))
        }
        "1" if reference.len() == 2 && reference.first()?.trim() == "0" => {
            let uuid = parse_non_zero_uuid(reference.get(1)?.trim())?;
            if let Some(picture) = information_register_command_standard_picture_name(&uuid) {
                return Some((Some(picture.to_string()), load_transparent));
            }
            let picture = object_refs.get(&uuid)?;
            let name = picture.strip_prefix("CommonPicture.")?;
            if name.is_empty() || name.contains('.') {
                return None;
            }
            Some((Some(picture.clone()), load_transparent))
        }
        _ => None,
    }
}

fn information_register_command_standard_picture_name(uuid: &str) -> Option<&'static str> {
    match uuid.to_ascii_lowercase().as_str() {
        "46598f81-5f95-4485-9b33-bfe4fd1276d0" => Some("StdPicture.SpreadsheetShowHeaders"),
        "caf2e58b-ca3d-4b63-82c9-f21f1c9bc9eb" => Some("StdPicture.Setting"),
        _ => common_command_standard_picture_name(uuid),
    }
}

fn parse_information_register_command_shortcut(value: &str) -> Option<Option<String>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.len() != 3 || fields.first()?.trim() != "0" {
        return None;
    }
    let key_code = fields.get(1)?.trim().parse::<u16>().ok()?;
    let modifier_code = fields.get(2)?.trim().parse::<u16>().ok()?;
    match (key_code, modifier_code) {
        (0, 0) => Some(None),
        (112..=123, 0) => Some(Some(format!("F{}", key_code - 111))),
        _ => None,
    }
}

fn nested_metadata_headers_from_text(text: &str, owner_uuid: &str) -> Vec<MetadataHeader> {
    nested_headers_from_text(text, owner_uuid, |_| true)
}

fn nested_web_service_operation_headers_from_text(
    text: &str,
    owner_uuid: &str,
) -> Vec<MetadataHeader> {
    nested_headers_from_text_inside_object_code(text, owner_uuid, 1)
}

fn nested_headers_from_text_inside_object_code(
    text: &str,
    owner_uuid: &str,
    code: u32,
) -> Vec<MetadataHeader> {
    nested_headers_from_text(text, owner_uuid, |marker_start| {
        is_offset_inside_metadata_object_code(text, marker_start, code)
    })
}

fn nested_headers_from_text(
    text: &str,
    owner_uuid: &str,
    accepts_marker: impl Fn(usize) -> bool,
) -> Vec<MetadataHeader> {
    nested_headers_with_offsets_from_text(text, owner_uuid, accepts_marker)
        .into_iter()
        .map(|(header, _)| header)
        .collect()
}

fn nested_headers_with_offsets_from_text(
    text: &str,
    owner_uuid: &str,
    accepts_marker: impl Fn(usize) -> bool,
) -> Vec<(MetadataHeader, usize)> {
    let mut headers = Vec::new();
    let mut seen = BTreeSet::new();
    let mut offset = 0usize;
    let marker = "{1,0,";

    while let Some(relative) = text[offset..].find(marker) {
        let marker_start = offset + relative;
        let uuid_start = marker_start + marker.len();
        let uuid_end = uuid_start + 36;
        offset = uuid_start;

        let Some(uuid) = text.get(uuid_start..uuid_end) else {
            continue;
        };
        if uuid == owner_uuid || !is_uuid_text(uuid) || !is_metadata_header_marker(text, uuid_end) {
            continue;
        }
        if !accepts_marker(marker_start) {
            continue;
        }
        if !seen.insert(uuid.to_string()) {
            continue;
        }
        if let Some(header) = parse_metadata_header_from_text(text, uuid) {
            headers.push((header, marker_start));
        }
    }

    headers
}

fn is_metadata_header_marker(text: &str, uuid_end: usize) -> bool {
    matches!(text.get(uuid_end..uuid_end + 2), Some("},"))
}

fn is_offset_inside_metadata_object_code(text: &str, offset: usize, code: u32) -> bool {
    let code_marker = format!("{{{code},");
    let Some(start) = text[..offset].rfind(&code_marker) else {
        return false;
    };
    scan_1c_braced_value(text, start)
        .map(|end| offset < end)
        .unwrap_or(false)
}

fn enclosing_metadata_header_for_code(
    text: &str,
    offset: usize,
    code: u32,
) -> Option<MetadataHeader> {
    let code_marker = format!("{{{code},");
    let mut search_end = offset;
    while let Some(relative_start) = text[..search_end].rfind(&code_marker) {
        let start = relative_start;
        search_end = start;
        let Some(end) = scan_1c_braced_value(text, start) else {
            continue;
        };
        if offset >= end {
            continue;
        }
        let Some(marker_relative) = text[start..end].find("{1,0,") else {
            continue;
        };
        let uuid_start = start + marker_relative + "{1,0,".len();
        let uuid_end = uuid_start + 36;
        let Some(uuid) = text.get(uuid_start..uuid_end) else {
            continue;
        };
        if !is_uuid_text(uuid) || !is_metadata_header_marker(text, uuid_end) {
            continue;
        }
        if let Some(header) = parse_metadata_header_from_text(text, uuid) {
            return Some(header);
        }
    }
    None
}

fn preceding_metadata_header_for_code(
    text: &str,
    offset: usize,
    code: u32,
) -> Option<MetadataHeader> {
    preceding_metadata_header_for_code_with_bounds(text, offset, code).map(|(header, _)| header)
}

fn preceding_metadata_header_for_code_with_bounds(
    text: &str,
    offset: usize,
    code: u32,
) -> Option<(MetadataHeader, usize)> {
    let code_marker = format!("{{{code},");
    let mut search_end = offset;
    while let Some(start) = text[..search_end].rfind(&code_marker) {
        search_end = start;
        let Some(end) = scan_1c_braced_value(text, start) else {
            continue;
        };
        let Some(marker_relative) = text[start..end].find("{1,0,") else {
            continue;
        };
        let uuid_start = start + marker_relative + "{1,0,".len();
        let uuid_end = uuid_start + 36;
        let Some(uuid) = text.get(uuid_start..uuid_end) else {
            continue;
        };
        if !is_uuid_text(uuid) || !is_metadata_header_marker(text, uuid_end) {
            continue;
        }
        if let Some(header) = parse_metadata_header_from_text(text, uuid) {
            return Some((header, end));
        }
    }
    None
}

fn contains_metadata_header_uuid_between(text: &str, start: usize, end: usize, uuid: &str) -> bool {
    start < end && text[start..end].contains(&format!("{{1,0,{uuid}}}"))
}

fn contains_metadata_header_name_between(text: &str, start: usize, end: usize, name: &str) -> bool {
    if start >= end {
        return false;
    }
    let mut offset = start;
    let marker = "{1,0,";
    while offset < end {
        let Some(relative) = text[offset..end].find(marker) else {
            return false;
        };
        let marker_start = offset + relative;
        let uuid_start = marker_start + marker.len();
        let uuid_end = uuid_start + 36;
        offset = uuid_start;
        let Some(uuid) = text.get(uuid_start..uuid_end) else {
            continue;
        };
        if !is_uuid_text(uuid) || !is_metadata_header_marker(text, uuid_end) {
            continue;
        }
        let Some(name_start) =
            expect_comma_at(text, uuid_end + 1).map(|pos| skip_ascii_ws_at(text, pos))
        else {
            continue;
        };
        let Some((header_name, consumed)) = parse_1c_quoted_string_with_len(&text[name_start..])
        else {
            continue;
        };
        if name_start + consumed <= end && header_name == name {
            return true;
        }
    }
    false
}

fn module_owner_source_path(kind: &str, folder: &str, name: &str, suffix: &str) -> Option<PathBuf> {
    module_owner_route(kind, suffix).map(|route| {
        PathBuf::from(folder)
            .join(sanitize_source_path_segment(name))
            .join(route.relative_path())
    })
}

fn module_owner_route(
    kind: &str,
    suffix: &str,
) -> Option<&'static crate::compiler::families::assets::SourceAssetRoute> {
    crate::compiler::families::assets::SourceAssetRegistry
        .route_by_suffix(kind, suffix)
        .filter(|route| {
            route.codec() == crate::compiler::families::assets::SourceAssetCodec::Module
        })
}

