fn parse_owner_graph_child_uuid_collection(
    items: &[&str],
    family: owner_graph::OwnerGraphFamily,
    role: owner_graph::OwnerCollectionRole,
    reference: owner_graph::OwnerGraphReference,
    diagnostic: &mut Option<MetadataSourceExtractionDiagnostic>,
) -> Option<Vec<String>> {
    let mut seen = BTreeSet::new();
    let mut uuids = Vec::with_capacity(items.len());
    for (item_index, value) in items.iter().enumerate() {
        let Some(uuid) = parse_information_register_non_zero_uuid(value) else {
            *diagnostic = Some(owner_graph_owned_child_diagnostic(
                family,
                role,
                item_index,
                reference,
                owner_graph::OwnerGraphOwnedChildReason::HeaderMismatch,
            ));
            return None;
        };
        let uuid = uuid.to_ascii_lowercase();
        if !seen.insert(uuid.clone()) {
            *diagnostic = Some(owner_graph_owned_child_diagnostic(
                family,
                role,
                item_index,
                reference,
                owner_graph::OwnerGraphOwnedChildReason::Ambiguous,
            ));
            return None;
        }
        uuids.push(uuid);
    }
    Some(uuids)
}

fn decode_owner_graph_collection<'a>(
    family: owner_graph::OwnerGraphFamily,
    raw: &'a str,
    collection_layout: owner_graph::OwnerCollectionLayout,
) -> std::result::Result<owner_graph::DecodedOwnerCollection<'a>, MetadataSourceExtractionDiagnostic>
{
    let collection_index = collection_layout.index;
    let fields = split_information_register_braced_fields(raw).ok_or_else(|| {
        owner_graph_extraction_diagnostic(
            family,
            owner_graph::OwnerGraphDiagnosticKind::CollectionBracedShape,
            None,
            Some(collection_index),
            None,
        )
    })?;
    if fields.len() < 2 {
        return Err(owner_graph_extraction_diagnostic(
            family,
            owner_graph::OwnerGraphDiagnosticKind::CollectionMinimumShape,
            None,
            Some(collection_index),
            None,
        ));
    }
    if !fields[0]
        .trim()
        .eq_ignore_ascii_case(collection_layout.marker)
    {
        return Err(owner_graph_extraction_diagnostic(
            family,
            owner_graph::OwnerGraphDiagnosticKind::CollectionMarker,
            None,
            Some(collection_index),
            Some(owner_graph::OwnerGraphReference::CollectionMarker),
        ));
    }
    let count = parse_information_register_usize(fields[1]).ok_or_else(|| {
        owner_graph_extraction_diagnostic(
            family,
            owner_graph::OwnerGraphDiagnosticKind::CollectionCount,
            None,
            Some(collection_index),
            None,
        )
    })?;
    if count.checked_add(2) != Some(fields.len()) {
        return Err(owner_graph_extraction_diagnostic(
            family,
            owner_graph::OwnerGraphDiagnosticKind::CollectionCountMismatch,
            None,
            Some(collection_index),
            None,
        ));
    }
    Ok(owner_graph::DecodedOwnerCollection::new(
        fields[2..].to_vec(),
        owner_graph::OwnerCollectionProvenance::from_layout(collection_layout),
    ))
}

fn decode_owner_graph_uuid(
    raw: &str,
    family: owner_graph::OwnerGraphFamily,
    field_index: usize,
    syntax: owner_graph::OwnerGraphDiagnosticKind,
    nil: owner_graph::OwnerGraphDiagnosticKind,
    reference: owner_graph::OwnerGraphReference,
) -> std::result::Result<String, MetadataSourceExtractionDiagnostic> {
    let uuid = parse_information_register_uuid(raw).ok_or_else(|| {
        owner_graph_extraction_diagnostic(family, syntax, Some(field_index), None, Some(reference))
    })?;
    if information_register_uuid_is_zero(&uuid) {
        return Err(owner_graph_extraction_diagnostic(
            family,
            nil,
            Some(field_index),
            None,
            Some(reference),
        ));
    }
    Ok(uuid)
}

fn owner_graph_collision_diagnostic(
    family: owner_graph::OwnerGraphFamily,
    collision: owner_graph::OwnerIdentityCollision,
) -> MetadataSourceExtractionDiagnostic {
    let mut diagnostic = owner_graph_extraction_diagnostic(
        family,
        owner_graph::OwnerGraphDiagnosticKind::DuplicateIdentity,
        Some(collision.field_index),
        None,
        None,
    );
    diagnostic.offending_reference = Some(collision.previous.diagnostic_reference().to_owned());
    diagnostic
}

fn owner_graph_extraction_diagnostic(
    family: owner_graph::OwnerGraphFamily,
    kind: owner_graph::OwnerGraphDiagnosticKind,
    field_index: Option<usize>,
    collection_index: Option<usize>,
    reference: Option<owner_graph::OwnerGraphReference>,
) -> MetadataSourceExtractionDiagnostic {
    let (class, parser_stage, structural_signature) = kind.facts();
    let class = match class {
        owner_graph::OwnerGraphDiagnosticClass::Malformed => MetadataSourceFailureClass::Malformed,
        owner_graph::OwnerGraphDiagnosticClass::Unsupported => {
            MetadataSourceFailureClass::Unsupported
        }
        owner_graph::OwnerGraphDiagnosticClass::Invariant => MetadataSourceFailureClass::Invariant,
    };
    let mut diagnostic = MetadataSourceExtractionDiagnostic::new(
        class,
        family.as_str(),
        parser_stage,
        structural_signature,
    );
    diagnostic.field_index = field_index;
    diagnostic.collection_index = collection_index;
    diagnostic.offending_reference = reference.map(|value| value.as_str().to_owned());
    diagnostic
}

fn characteristics_extraction_diagnostic(
    failure: characteristics::CharacteristicsDiagnostic,
) -> MetadataSourceExtractionDiagnostic {
    let class = match failure.reason {
        characteristics::CharacteristicsReason::UnsupportedFamily
        | characteristics::CharacteristicsReason::UnsupportedMarker
        | characteristics::CharacteristicsReason::UnsupportedFilterUnion => {
            MetadataSourceFailureClass::Unsupported
        }
        characteristics::CharacteristicsReason::UnresolvedReference => {
            MetadataSourceFailureClass::Unresolved
        }
        characteristics::CharacteristicsReason::ReferenceOutsideSource
        | characteristics::CharacteristicsReason::InvalidCanonicalModel => {
            MetadataSourceFailureClass::Invariant
        }
        characteristics::CharacteristicsReason::InvalidEnvelope
        | characteristics::CharacteristicsReason::InvalidCount
        | characteristics::CharacteristicsReason::InvalidTypeTag
        | characteristics::CharacteristicsReason::InvalidBodyShape => {
            MetadataSourceFailureClass::Malformed
        }
    };
    let mut diagnostic = MetadataSourceExtractionDiagnostic::new(
        class,
        failure.family.as_str(),
        failure.stage.as_str(),
        failure.reason.as_str(),
    );
    diagnostic.field_index = Some(failure.field_index);
    diagnostic.item_index = failure.item_index;
    diagnostic.collection_role = Some(failure.role.token().to_owned());
    diagnostic.offending_reference = failure
        .reference_kind
        .map(|reference| reference.as_str().to_owned());
    diagnostic
}

fn decode_owner_characteristics(
    family: owner_graph::OwnerGraphFamily,
    fields: &[&str],
    type_index: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    diagnostic: &mut Option<MetadataSourceExtractionDiagnostic>,
) -> Option<Characteristics> {
    let slot = match characteristics::characteristics_slot(family) {
        Ok(slot) => slot,
        Err(failure) => {
            *diagnostic = Some(characteristics_extraction_diagnostic(failure));
            return None;
        }
    };
    match characteristics::decode_characteristics_with_owner_code(
        family,
        fields.first().map(|value| value.trim()),
        fields.get(slot)?,
        type_index,
        metadata_object_refs,
        object_refs,
    ) {
        Ok(model) => Some(model),
        Err(failure) => {
            *diagnostic = Some(characteristics_extraction_diagnostic(failure));
            None
        }
    }
}

fn parse_information_register_non_zero_uuid(value: &str) -> Option<String> {
    let value = parse_information_register_uuid(value)?;
    (!information_register_uuid_is_zero(&value)).then_some(value)
}

fn parse_information_register_quoted_string(value: &str) -> Option<String> {
    let value = value.trim();
    let (parsed, consumed) = parse_1c_quoted_string_with_len(value)?;
    (consumed == value.len() && parsed.chars().all(is_xml_1_0_char)).then_some(parsed)
}

fn parse_information_register_owner_localized_value(value: &str) -> Option<Vec<(String, String)>> {
    let fields = split_information_register_braced_fields(value)?;
    let count = parse_information_register_usize(fields.first()?)?;
    if fields.len() != count.checked_mul(2)?.checked_add(1)? {
        return None;
    }
    let mut languages = BTreeSet::new();
    let mut values = Vec::with_capacity(count);
    for pair in fields[1..].chunks_exact(2) {
        let language = parse_information_register_quoted_string(pair[0])?;
        let content = parse_information_register_quoted_string(pair[1])?;
        if !languages.insert(language.clone()) {
            return None;
        }
        values.push((language, content));
    }
    Some(values)
}

fn parse_information_register_owner_header(value: &str) -> Option<MetadataHeader> {
    let fields = split_information_register_braced_fields(value)?;
    // Mirrors the header-wrapper shape `enclosing_counted_block_start`
    // (mssql_dump::mod, `ab58c3f`) already closed for the marker/rfind
    // parsers: the platform omits the trailing default `0` (and drops the
    // wrapper's own leading count from `3` to `2`) whenever the object
    // leaves this slot at default. Confirmed on real ERP УХ 3.2.12.6 data
    // (`Catalogs/АлгоритмыОпределенияБазовойДаты`, uuid
    // `0b69b382-479d-4709-bd5d-bc499e5b3bf5`, owner_header_slot 9 of the
    // Catalog owner-graph layout): an 8-member wrapper with no counterpart
    // to what used to be the hardcoded `fields.len() != 9` check below.
    let has_trailing_default = match fields.len() {
        9 => true,
        8 => false,
        _ => return None,
    };
    if fields.first()?.trim() != (if has_trailing_default { "3" } else { "2" })
        || fields.get(5)?.trim() != "0"
        || fields.get(6)?.trim() != "0"
        || !parse_information_register_uuid(fields.get(7)?)
            .is_some_and(|uuid| information_register_uuid_is_zero(&uuid))
        || (has_trailing_default && fields.get(8)?.trim() != "0")
    {
        return None;
    }
    let identity = split_information_register_braced_fields(fields.get(1)?)?;
    if identity.len() != 3 || identity.first()?.trim() != "1" || identity.get(1)?.trim() != "0" {
        return None;
    }
    Some(MetadataHeader {
        uuid: parse_information_register_non_zero_uuid(identity.get(2)?)?,
        name: parse_information_register_quoted_string(fields.get(2)?)?,
        synonyms: parse_information_register_owner_localized_value(fields.get(3)?)?,
        comment: parse_information_register_quoted_string(fields.get(4)?)?,
        template_type_code: None,
    })
}

fn information_register_root_collection_is_valid(value: &str) -> bool {
    let Some(fields) = split_information_register_braced_fields(value) else {
        return false;
    };
    if fields.len() < 2 || parse_information_register_non_zero_uuid(fields[0]).is_none() {
        return false;
    }
    let Some(count) = fields
        .get(1)
        .and_then(|value| parse_information_register_usize(value))
    else {
        return false;
    };
    if count == 0 {
        return fields.len() == 2;
    }
    if fields.len() != count.checked_add(2).unwrap_or(usize::MAX) {
        return false;
    }
    let items = &fields[2..];
    let uuids = items
        .iter()
        .map(|value| {
            parse_information_register_non_zero_uuid(value).map(|uuid| uuid.to_ascii_lowercase())
        })
        .collect::<Option<BTreeSet<_>>>();
    if uuids.is_some_and(|uuids| uuids.len() == count) {
        return true;
    }

    let mut object_items = BTreeSet::new();
    items.iter().all(|value| {
        if !object_items.insert(value.trim()) {
            return false;
        }
        let Some(item) = split_information_register_braced_fields(value) else {
            return false;
        };
        if item.len() != 2 || item[1].trim() != "0" {
            return false;
        }
        split_information_register_braced_fields(item[0]).is_some_and(|wrapper| {
            wrapper.len() >= 2
                && parse_information_register_usize(wrapper[0]).is_some()
                && split_information_register_braced_fields(wrapper[1]).is_some()
        })
    })
}

fn parse_information_register_owner_fields<'a>(
    text: &'a str,
    expected_header: &MetadataHeader,
) -> Option<InformationRegisterOwnerFields<'a>> {
    let root = split_information_register_braced_fields(text.trim_start_matches('\u{feff}'))?;
    if root.len() != 9
        || root.first()?.trim() != "1"
        || root.get(2)?.trim() != "6"
        || !root[3..]
            .iter()
            .all(|field| information_register_root_collection_is_valid(field))
    {
        return None;
    }
    let collection_type_ids = root[3..]
        .iter()
        .map(|field| {
            split_information_register_braced_fields(field)
                .and_then(|fields| parse_information_register_non_zero_uuid(fields.first()?))
                .map(|uuid| uuid.to_ascii_lowercase())
        })
        .collect::<Option<BTreeSet<_>>>()?;
    if collection_type_ids.len() != 6 {
        return None;
    }

    let owner = split_information_register_braced_fields(root.get(1)?)?;
    if owner.len() != 39 || owner.first()?.trim() != "33" {
        return None;
    }
    let generated_type_ids = owner[1..15]
        .iter()
        .map(|field| {
            parse_information_register_non_zero_uuid(field).map(|uuid| uuid.to_ascii_lowercase())
        })
        .collect::<Option<BTreeSet<_>>>()?;
    if generated_type_ids.len() != 14 {
        return None;
    }

    let header_wrapper = split_information_register_braced_fields(owner.get(15)?)?;
    if header_wrapper.len() != 2 || header_wrapper.first()?.trim() != "0" {
        return None;
    }
    let header_field = header_wrapper.get(1)?;
    let parsed_header = parse_information_register_owner_header(header_field)?;
    if !parsed_header
        .uuid
        .eq_ignore_ascii_case(&expected_header.uuid)
        || parsed_header.name != expected_header.name
        || parsed_header.synonyms != expected_header.synonyms
        || parsed_header.comment != expected_header.comment
    {
        return None;
    }

    let matching_headers = owner
        .iter()
        .filter(|field| {
            let Some(wrapper) = split_information_register_braced_fields(field) else {
                return false;
            };
            if wrapper.len() != 2 || wrapper.first().map(|value| value.trim()) != Some("0") {
                return false;
            }
            let Some(header) = wrapper
                .get(1)
                .and_then(|value| parse_information_register_owner_header(value))
            else {
                return false;
            };
            header.uuid.eq_ignore_ascii_case(&expected_header.uuid)
        })
        .count();
    if matching_headers != 1 {
        return None;
    }

    let mut logical = Vec::with_capacity(25);
    logical.extend(header_wrapper);
    logical.extend(owner[16..].iter().copied());
    Some(InformationRegisterOwnerFields {
        logical: logical.try_into().ok()?,
    })
}

fn information_register_periodicity_xml(value: &str) -> Option<&'static str> {
    match value.trim() {
        "0" => Some("Nonperiodical"),
        "1" => Some("Year"),
        "2" => Some("Quarter"),
        "3" => Some("Month"),
        "4" => Some("Day"),
        "5" => Some("Second"),
        "6" => Some("RecorderPosition"),
        _ => None,
    }
}

fn information_register_write_mode_xml(value: &str) -> Option<&'static str> {
    match value.trim() {
        "0" => Some("Independent"),
        "1" => Some("RecorderSubordinate"),
        _ => None,
    }
}

fn information_register_edit_type_xml(value: &str) -> Option<&'static str> {
    match value.trim() {
        "0" => Some("InList"),
        "1" => Some("InDialog"),
        "2" => Some("BothWays"),
        _ => None,
    }
}

fn information_register_data_lock_control_mode_xml(value: &str) -> Option<&'static str> {
    match value.trim() {
        "0" => Some("Automatic"),
        "1" => Some("Managed"),
        _ => None,
    }
}

fn parse_information_register_owned_form_ref(
    value: &str,
    owner_name: &str,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<Option<String>> {
    let uuid = parse_information_register_uuid(value)?;
    if information_register_uuid_is_zero(&uuid) {
        return Some(None);
    }
    let mut matches = form_refs
        .iter()
        .filter(|(candidate, _)| candidate.eq_ignore_ascii_case(&uuid));
    let (_, form) = matches.next()?;
    if matches.next().is_some()
        || form.kind != "Form"
        || !is_owned_metadata_child_path(
            &form.relative_path,
            "InformationRegisters",
            owner_name,
            "Forms",
        )
    {
        return None;
    }
    let reference = form_source_reference_name(form)?;
    let prefix = format!("InformationRegister.{owner_name}.Form.");
    reference
        .strip_prefix(&prefix)
        .is_some_and(|name| !name.is_empty() && !name.contains('.'))
        .then_some(Some(reference))
}

