fn parse_register_full_text_search(
    kind: &str,
    fields: &[&str],
    uuid: &str,
) -> Option<&'static str> {
    let header_index = metadata_header_field_index(fields, uuid)?;
    let field_offset = match kind {
        "AccountingRegister" => 14,
        "AccumulationRegister" => 6,
        _ => return None,
    };
    match fields
        .get(header_index + field_offset)
        .map(|field| field.trim())
    {
        Some("0") => Some("DontUse"),
        Some("1") => Some("Use"),
        _ => None,
    }
}

fn parse_register_use_standard_commands(fields: &[&str], uuid: &str) -> bool {
    let Some(header_index) = metadata_header_field_index(fields, uuid) else {
        return true;
    };
    fields
        .get(header_index + 1)
        .and_then(|field| parse_1c_bool_field(Some(*field)))
        .unwrap_or(true)
}

fn parse_register_include_help_in_contents(
    kind: &str,
    fields: &[&str],
    uuid: &str,
) -> Option<bool> {
    match kind {
        "AccumulationRegister" => Some(false),
        "AccountingRegister" => {
            let header_index = metadata_header_field_index(fields, uuid)?;
            parse_1c_bool_field(fields.get(header_index + 2).copied())
        }
        _ => None,
    }
}

fn parse_register_presentations(
    kind: &str,
    fields: &[&str],
    uuid: &str,
) -> (
    Vec<(String, String)>,
    Vec<(String, String)>,
    Vec<(String, String)>,
) {
    if kind != "AccountingRegister" {
        return (Vec::new(), Vec::new(), Vec::new());
    }
    let Some(header_index) = metadata_header_field_index(fields, uuid) else {
        return (Vec::new(), Vec::new(), Vec::new());
    };
    (
        fields
            .get(header_index + 11)
            .map(|field| parse_1c_synonyms(field))
            .unwrap_or_default(),
        fields
            .get(header_index + 12)
            .map(|field| parse_1c_synonyms(field))
            .unwrap_or_default(),
        fields
            .get(header_index + 13)
            .map(|field| parse_1c_synonyms(field))
            .unwrap_or_default(),
    )
}

fn push_register_generated_type_entries(
    entries: &mut Vec<GeneratedTypeEntry>,
    fields: &[&str],
    start_index: usize,
    type_prefix: &str,
    name: &str,
) {
    for (offset, suffix) in register_generated_type_suffixes() {
        let xml_suffix = register_generated_type_xml_suffix(type_prefix, suffix);
        push_generated_type_entry(
            entries,
            fields,
            start_index + offset,
            start_index + offset + 1,
            &format!("{type_prefix}{xml_suffix}.{name}"),
            register_generated_type_category(type_prefix, suffix),
        );
    }
}

const CALCULATION_REGISTER_GENERATED_TYPE_SLOTS: &[(usize, usize, &str, &str)] = &[
    (1, 2, "CalculationRegisterRecord", "Record"),
    (3, 4, "CalculationRegisterManager", "Manager"),
    (5, 6, "CalculationRegisterSelection", "Selection"),
    (7, 8, "CalculationRegisterList", "List"),
    (9, 10, "CalculationRegisterRecordSet", "RecordSet"),
    (11, 12, "CalculationRegisterRecordKey", "RecordKey"),
    (13, 14, "RecalculationsManager", "Recalcs"),
];
const CALCULATION_REGISTER_RECALCULATION_LIST_MARKER: &str = "274bf899-db0e-4df6-8ab5-67bf6371ec0b";
type CalculationRootRecalculationReferences = BTreeMap<String, Vec<(String, String)>>;

fn parse_exact_calculation_register_generated_types(
    fields: &[&str],
    expected_header: &MetadataHeader,
) -> Option<Option<Vec<GeneratedTypeEntry>>> {
    if !validate_exact_wrapped_register_owner_layout(fields, expected_header, "21", 33, 15)? {
        return Some(None);
    }

    let mut ids = BTreeSet::new();
    let mut entries = Vec::with_capacity(CALCULATION_REGISTER_GENERATED_TYPE_SLOTS.len());
    for (type_index, value_index, name, category) in CALCULATION_REGISTER_GENERATED_TYPE_SLOTS {
        let type_id = parse_information_register_non_zero_uuid(fields.get(*type_index)?)?;
        let value_id = parse_information_register_non_zero_uuid(fields.get(*value_index)?)?;
        if !ids.insert(type_id.to_ascii_lowercase()) || !ids.insert(value_id.to_ascii_lowercase()) {
            return None;
        }
        entries.push(GeneratedTypeEntry {
            name: format!("{name}.{}", expected_header.name),
            category,
            type_id,
            value_id,
        });
    }

    Some(Some(entries))
}

fn parse_exact_calculation_register_recalculation_uuids(
    text: &str,
    expected_header: &MetadataHeader,
) -> Option<Option<Vec<String>>> {
    let fields = metadata_object_fields(text)?;
    if !validate_exact_wrapped_register_owner_layout(&fields, expected_header, "21", 33, 15)? {
        return Some(None);
    }

    let Some(root_fields) = split_1c_braced_fields(text, 0) else {
        return Some(Some(Vec::new()));
    };
    let owner_indexes = root_fields
        .iter()
        .enumerate()
        .filter_map(|(index, field)| {
            let candidate = split_1c_braced_fields(field.trim(), 0)?;
            validate_exact_wrapped_register_owner_layout(&candidate, expected_header, "21", 33, 15)
                .is_some_and(|is_exact| is_exact)
                .then_some(index)
        })
        .collect::<Vec<_>>();
    let [owner_index] = owner_indexes.as_slice() else {
        return Some(Some(Vec::new()));
    };
    let collections = root_fields
        .iter()
        .enumerate()
        .filter_map(|(index, field)| {
            if index <= *owner_index {
                return None;
            }
            let collection = split_1c_braced_fields(field.trim(), 0)?;
            (collection.first().map(|field| field.trim())
                == Some(CALCULATION_REGISTER_RECALCULATION_LIST_MARKER))
            .then_some(collection)
        })
        .collect::<Vec<_>>();
    let [collection] = collections.as_slice() else {
        return Some(Some(Vec::new()));
    };
    let Some(count) = collection
        .get(1)
        .and_then(|field| parse_information_register_usize(field))
    else {
        return Some(Some(Vec::new()));
    };
    if collection.first().map(|field| field.trim())
        != Some(CALCULATION_REGISTER_RECALCULATION_LIST_MARKER)
        || collection.len() != count.saturating_add(2)
    {
        return Some(Some(Vec::new()));
    }

    let mut seen = BTreeSet::new();
    let mut uuids = Vec::with_capacity(count);
    for field in collection.iter().skip(2) {
        let Some(uuid) = parse_information_register_non_zero_uuid(field) else {
            return Some(Some(Vec::new()));
        };
        if !seen.insert(uuid.to_ascii_lowercase()) {
            return Some(Some(Vec::new()));
        }
        uuids.push(uuid);
    }
    Some(Some(uuids))
}

fn parse_calculation_register_recalculation_child_names(
    text: &str,
    expected_header: &MetadataHeader,
    root_recalculation_refs: &CalculationRootRecalculationReferences,
) -> Option<Vec<String>> {
    let Some(uuids) = parse_exact_calculation_register_recalculation_uuids(text, expected_header)?
    else {
        return Some(Vec::new());
    };

    let mut owners = root_recalculation_refs
        .iter()
        .filter(|(uuid, _)| uuid.eq_ignore_ascii_case(&expected_header.uuid));
    let Some((_, references)) = owners.next() else {
        return Some(Vec::new());
    };
    if owners.next().is_some()
        || references.len() != uuids.len()
        || !references
            .iter()
            .zip(&uuids)
            .all(|((reference_uuid, _), uuid)| reference_uuid.eq_ignore_ascii_case(uuid))
    {
        return Some(Vec::new());
    }
    Some(references.iter().map(|(_, name)| name.clone()).collect())
}

fn build_calculation_root_recalculation_reference_index(
    rows: &[MetadataTextRow],
) -> CalculationRootRecalculationReferences {
    let mut rows_by_uuid = BTreeMap::<String, Vec<&MetadataTextRow>>::new();
    for row in rows {
        rows_by_uuid
            .entry(row.file_name.to_ascii_lowercase())
            .or_default()
            .push(row);
    }

    let calculation_owners = rows
        .iter()
        .filter_map(|row| match (row.kind.as_deref(), row.header.as_ref()) {
            (Some("CalculationRegister"), Some(header)) => Some((row, header)),
            _ => None,
        })
        .collect::<Vec<_>>();
    let mut declaring_owners_by_child = BTreeMap::<String, BTreeSet<String>>::new();
    for (row, owner) in &calculation_owners {
        for uuid in calculation_register_recalculation_uuids_from_text(&row.text) {
            declaring_owners_by_child
                .entry(uuid.to_ascii_lowercase())
                .or_default()
                .insert(owner.uuid.to_ascii_lowercase());
        }
    }

    let mut candidates = Vec::<(String, Vec<(String, String)>)>::new();
    for (row, owner) in calculation_owners {
        if rows_by_uuid
            .get(&owner.uuid.to_ascii_lowercase())
            .is_none_or(|owner_rows| owner_rows.len() != 1)
        {
            continue;
        }
        let Some(declared) =
            parse_exact_calculation_register_recalculation_uuids(&row.text, owner).flatten()
        else {
            continue;
        };
        let resolved = declared
            .into_iter()
            .map(|uuid| {
                let owner_ids = declaring_owners_by_child.get(&uuid.to_ascii_lowercase())?;
                if owner_ids.len() != 1 || !owner_ids.contains(&owner.uuid.to_ascii_lowercase()) {
                    return None;
                }
                let [recalculation_row] = rows_by_uuid.get(&uuid.to_ascii_lowercase())?.as_slice()
                else {
                    return None;
                };
                let recalculation = recalculation_row.header.as_ref()?;
                if recalculation_row.object_code != Some(4)
                    || !recalculation_row.file_name.eq_ignore_ascii_case(&uuid)
                    || !recalculation.uuid.eq_ignore_ascii_case(&uuid)
                    || recalculation_object_fields(
                        &recalculation_row.text,
                        &recalculation_row.file_name,
                    )
                    .is_none()
                {
                    return None;
                }
                Some((uuid, recalculation.name.clone()))
            })
            .collect::<Option<Vec<_>>>();
        if let Some(resolved) = resolved {
            candidates.push((owner.uuid.to_ascii_lowercase(), resolved));
        }
    }

    let mut owners_by_path = BTreeMap::<(String, String), Vec<(String, String)>>::new();
    for (owner_uuid, references) in &candidates {
        let Some(owner) = rows_by_uuid
            .get(owner_uuid)
            .and_then(|rows| rows.iter().find_map(|row| row.header.as_ref()))
        else {
            continue;
        };
        for (child_uuid, child_name) in references {
            owners_by_path
                .entry((
                    sanitize_source_path_segment(&owner.name).to_lowercase(),
                    sanitize_source_path_segment(child_name).to_lowercase(),
                ))
                .or_default()
                .push((owner_uuid.clone(), child_uuid.to_ascii_lowercase()));
        }
    }
    let invalid_owners = owners_by_path
        .values()
        .filter(|entries| entries.iter().collect::<BTreeSet<_>>().len() > 1)
        .flat_map(|entries| entries.iter().map(|(owner_uuid, _)| owner_uuid.clone()))
        .collect::<BTreeSet<_>>();

    candidates
        .into_iter()
        .filter(|(owner_uuid, _)| !invalid_owners.contains(owner_uuid))
        .collect()
}

fn push_accounting_register_generated_type_entries(
    entries: &mut Vec<GeneratedTypeEntry>,
    fields: &[&str],
    start_index: usize,
    name: &str,
) {
    for (offset, suffix, category) in accounting_register_generated_type_slots() {
        push_generated_type_entry(
            entries,
            fields,
            start_index + offset,
            start_index + offset + 1,
            &format!("AccountingRegister{suffix}.{name}"),
            category,
        );
    }
}

fn register_generated_type_start_index(kind: &str, fields: &[&str], uuid: &str) -> Option<usize> {
    match kind {
        "AccountingRegister" if is_code21_accounting_register_fields(fields, uuid) => Some(1),
        "AccountingRegister" => Some(2),
        "AccumulationRegister" | "CalculationRegister" => Some(1),
        _ => None,
    }
}

fn register_generated_type_suffixes() -> &'static [(usize, &'static str)] {
    &[
        (0, "Object"),
        (2, "Manager"),
        (4, "Selection"),
        (6, "List"),
        (8, "RecordSet"),
        (10, "RecordKey"),
    ]
}

fn accounting_register_generated_type_slots() -> &'static [(usize, &'static str, &'static str)] {
    &[
        (0, "Record", "Record"),
        (2, "ExtDimensions", "ExtDimensions"),
        (4, "RecordSet", "RecordSet"),
        (6, "RecordKey", "RecordKey"),
        (8, "Selection", "Selection"),
        (10, "List", "List"),
        (12, "Manager", "Manager"),
    ]
}

fn register_generated_type_xml_suffix<'a>(type_prefix: &str, suffix: &'a str) -> &'a str {
    match (type_prefix, suffix) {
        ("AccumulationRegister", "Object") => "Record",
        _ => suffix,
    }
}

fn register_generated_type_category(type_prefix: &str, suffix: &str) -> &'static str {
    if type_prefix == "AccumulationRegister" && suffix == "Object" {
        return "Record";
    }
    match suffix {
        "Object" => "Object",
        "Manager" => "Manager",
        "Selection" => "Selection",
        "List" => "List",
        "RecordSet" => "RecordSet",
        "RecordKey" => "RecordKey",
        _ => unreachable!("unknown register generated type suffix"),
    }
}

fn register_child_object_tag(kind: &str, text: &str, marker_start: usize) -> Option<&'static str> {
    if !metadata_kind_uses_register_resources(kind) {
        return None;
    }
    if kind == "InformationRegister"
        && is_offset_inside_metadata_object_code(text, marker_start, 27)
    {
        if is_offset_inside_metadata_object_code(text, marker_start, 9) {
            return Some("Dimension");
        }
        if is_offset_inside_metadata_object_code(text, marker_start, 7) {
            return Some("Resource");
        }
    }
    if kind == "AccountingRegister"
        && is_offset_inside_register_dimension_list(text, marker_start)
        && is_offset_inside_metadata_object_code(text, marker_start, 6)
    {
        return Some("Dimension");
    }
    if kind == "AccountingRegister"
        && is_offset_inside_register_resource_list(text, marker_start)
        && is_offset_inside_metadata_object_code(text, marker_start, 2)
    {
        return Some("Resource");
    }
    if kind == "AccountingRegister"
        && is_offset_inside_accounting_register_attribute_list(text, marker_start)
        && is_offset_inside_metadata_object_code(text, marker_start, 2)
    {
        return Some("Attribute");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 5)
        && is_offset_inside_register_resource_list(text, marker_start)
    {
        return Some("Resource");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 4)
        && is_offset_inside_metadata_object_code(text, marker_start, 27)
    {
        return Some("Attribute");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 5) {
        return Some("Attribute");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 6) {
        return Some("Attribute");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 8)
        && is_offset_inside_register_dimension_list(text, marker_start)
    {
        return Some("Dimension");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 8) {
        return Some("Resource");
    }
    if is_offset_inside_metadata_object_code(text, marker_start, 10) {
        return Some("Dimension");
    }
    None
}

#[derive(Clone, Debug)]
struct DeclaredOwnerChildInventory {
    direct_attributes: Vec<String>,
    tabular_sections: Vec<(String, Vec<String>)>,
}

const OWNER_CHILD_ATTRIBUTE_TAG: &str = "Attribute";
const OWNER_CHILD_TABULAR_SECTION_TAG: &str = "TabularSection";
const NATIVE_COLLECTION_ITEM_TAIL: &str = "0";
const NATIVE_COLLECTION_ITEM_PRESENT: &str = "1";
const TABULAR_SECTION_PAYLOAD_CODE: &str = "11";
const METADATA_NAME_SEPARATOR: char = '.';
const DIAGNOSTIC_TOKEN_SEPARATORS: [char; 3] = ['_', '-', METADATA_NAME_SEPARATOR];
const PASSWORD_SOURCE_NONE: &str = "none";
const PASSWORD_SOURCE_INLINE: &str = "inline";
const PASSWORD_SOURCE_ENVIRONMENT: &str = "environment";
const OWNER_KIND_BUSINESS_PROCESS: &str = "BusinessProcess";

impl DeclaredOwnerChildInventory {
    fn failure_for_observed(
        &self,
        tag: &str,
        uuid: &str,
        parent: Option<&MetadataHeader>,
    ) -> Option<DeclaredOwnerChildFailure> {
        let direct = |index, reason| DeclaredOwnerChildFailure {
            role: owner_graph::OwnerCollectionRole::DirectAttribute,
            item_index: index,
            reason,
        };
        let section = |index, reason| DeclaredOwnerChildFailure {
            role: owner_graph::OwnerCollectionRole::TabularSection,
            item_index: index,
            reason,
        };
        match (tag, parent) {
            (OWNER_CHILD_TABULAR_SECTION_TAG, None) => self
                .tabular_sections
                .iter()
                .position(|(candidate, _)| candidate.eq_ignore_ascii_case(uuid))
                .map_or_else(
                    || {
                        Some(section(
                            self.tabular_sections.len(),
                            owner_graph::OwnerGraphOwnedChildReason::Unexpected,
                        ))
                    },
                    |_| None,
                ),
            (OWNER_CHILD_ATTRIBUTE_TAG, None) => {
                if self
                    .direct_attributes
                    .iter()
                    .any(|candidate| candidate.eq_ignore_ascii_case(uuid))
                {
                    None
                } else if let Some((section_index, _)) = self
                    .tabular_sections
                    .iter()
                    .enumerate()
                    .find(|(_, (_, attributes))| {
                        attributes
                            .iter()
                            .any(|candidate| candidate.eq_ignore_ascii_case(uuid))
                    })
                {
                    Some(section(
                        section_index,
                        owner_graph::OwnerGraphOwnedChildReason::WrongOwner,
                    ))
                } else {
                    Some(direct(
                        self.direct_attributes.len(),
                        owner_graph::OwnerGraphOwnedChildReason::Unexpected,
                    ))
                }
            }
            (OWNER_CHILD_ATTRIBUTE_TAG, Some(parent)) => {
                let parent_index = self
                    .tabular_sections
                    .iter()
                    .position(|(candidate, _)| candidate.eq_ignore_ascii_case(&parent.uuid));
                let Some(parent_index) = parent_index else {
                    return Some(section(
                        self.tabular_sections.len(),
                        owner_graph::OwnerGraphOwnedChildReason::WrongOwner,
                    ));
                };
                if self.tabular_sections[parent_index]
                    .1
                    .iter()
                    .any(|candidate| candidate.eq_ignore_ascii_case(uuid))
                {
                    None
                } else if let Some(direct_index) = self
                    .direct_attributes
                    .iter()
                    .position(|candidate| candidate.eq_ignore_ascii_case(uuid))
                {
                    Some(direct(
                        direct_index,
                        owner_graph::OwnerGraphOwnedChildReason::WrongOwner,
                    ))
                } else if let Some((other_index, _)) = self
                    .tabular_sections
                    .iter()
                    .enumerate()
                    .find(|(_, (_, attributes))| {
                        attributes
                            .iter()
                            .any(|candidate| candidate.eq_ignore_ascii_case(uuid))
                    })
                {
                    Some(section(
                        other_index,
                        owner_graph::OwnerGraphOwnedChildReason::WrongOwner,
                    ))
                } else {
                    Some(section(
                        parent_index,
                        owner_graph::OwnerGraphOwnedChildReason::Unexpected,
                    ))
                }
            }
            _ => Some(direct(
                0,
                owner_graph::OwnerGraphOwnedChildReason::WrongKind,
            )),
        }
    }

    fn location_for(
        &self,
        tag: &str,
        uuid: &str,
        parent: Option<&MetadataHeader>,
    ) -> DeclaredOwnerChildFailure {
        self.failure_for_observed(tag, uuid, parent)
            .unwrap_or_else(|| match parent {
                Some(parent) => DeclaredOwnerChildFailure {
                    role: owner_graph::OwnerCollectionRole::TabularSection,
                    item_index: self
                        .tabular_sections
                        .iter()
                        .position(|(candidate, _)| candidate.eq_ignore_ascii_case(&parent.uuid))
                        .unwrap_or(0),
                    reason: owner_graph::OwnerGraphOwnedChildReason::PropertyParse,
                },
                None if tag == OWNER_CHILD_TABULAR_SECTION_TAG => DeclaredOwnerChildFailure {
                    role: owner_graph::OwnerCollectionRole::TabularSection,
                    item_index: self
                        .tabular_sections
                        .iter()
                        .position(|(candidate, _)| candidate.eq_ignore_ascii_case(uuid))
                        .unwrap_or(0),
                    reason: owner_graph::OwnerGraphOwnedChildReason::PropertyParse,
                },
                None => DeclaredOwnerChildFailure {
                    role: owner_graph::OwnerCollectionRole::DirectAttribute,
                    item_index: self
                        .direct_attributes
                        .iter()
                        .position(|candidate| candidate.eq_ignore_ascii_case(uuid))
                        .unwrap_or(0),
                    reason: owner_graph::OwnerGraphOwnedChildReason::PropertyParse,
                },
            })
    }

    fn first_missing(&self, roots: &[MetadataChildObject]) -> Option<DeclaredOwnerChildFailure> {
        for (index, uuid) in self.direct_attributes.iter().enumerate() {
            if !roots.iter().any(|child| {
                child.tag == OWNER_CHILD_ATTRIBUTE_TAG
                    && child.header.uuid.eq_ignore_ascii_case(uuid)
            }) {
                return Some(DeclaredOwnerChildFailure {
                    role: owner_graph::OwnerCollectionRole::DirectAttribute,
                    item_index: index,
                    reason: owner_graph::OwnerGraphOwnedChildReason::Missing,
                });
            }
        }
        for (section_index, (section_uuid, attributes)) in self.tabular_sections.iter().enumerate()
        {
            let Some(section) = roots.iter().find(|child| {
                child.tag == OWNER_CHILD_TABULAR_SECTION_TAG
                    && child.header.uuid.eq_ignore_ascii_case(section_uuid)
            }) else {
                return Some(DeclaredOwnerChildFailure {
                    role: owner_graph::OwnerCollectionRole::TabularSection,
                    item_index: section_index,
                    reason: owner_graph::OwnerGraphOwnedChildReason::Missing,
                });
            };
            if attributes.iter().any(|uuid| {
                !section
                    .child_objects
                    .iter()
                    .any(|child| child.header.uuid.eq_ignore_ascii_case(uuid))
            }) {
                return Some(DeclaredOwnerChildFailure {
                    role: owner_graph::OwnerCollectionRole::TabularSection,
                    item_index: section_index,
                    reason: owner_graph::OwnerGraphOwnedChildReason::Missing,
                });
            }
        }
        None
    }
    fn root_order(&self, child: &MetadataChildObject) -> Option<usize> {
        self.root_order_for(child.tag, &child.header.uuid)
    }

    fn root_order_for(&self, tag: &str, uuid: &str) -> Option<usize> {
        match tag {
            OWNER_CHILD_ATTRIBUTE_TAG => self
                .direct_attributes
                .iter()
                .position(|candidate| candidate.eq_ignore_ascii_case(uuid)),
            OWNER_CHILD_TABULAR_SECTION_TAG => self
                .tabular_sections
                .iter()
                .position(|(candidate, _)| candidate.eq_ignore_ascii_case(uuid))
                .map(|index| self.direct_attributes.len() + index),
            _ => None,
        }
    }

    fn child_order(&self, section_uuid: &str, child_uuid: &str) -> Option<usize> {
        self.tabular_sections
            .iter()
            .find(|(uuid, _)| uuid.eq_ignore_ascii_case(section_uuid))
            .and_then(|(_, attributes)| {
                attributes
                    .iter()
                    .position(|uuid| uuid.eq_ignore_ascii_case(child_uuid))
            })
    }
}

#[derive(Clone, Copy, Debug)]
struct DeclaredOwnerChildFailure {
    role: owner_graph::OwnerCollectionRole,
    item_index: usize,
    reason: owner_graph::OwnerGraphOwnedChildReason,
}

#[derive(Clone, Copy, Debug)]
struct OwnerCollectionItemFailure {
    item_index: usize,
    reference: owner_graph::OwnerGraphReference,
    reason: owner_graph::OwnerGraphOwnedChildReason,
}

fn owner_collection_failure(
    item_index: usize,
    reference: owner_graph::OwnerGraphReference,
    reason: owner_graph::OwnerGraphOwnedChildReason,
) -> OwnerCollectionItemFailure {
    OwnerCollectionItemFailure {
        item_index,
        reference,
        reason,
    }
}

fn owner_collection_item_failure(
    role: owner_graph::OwnerCollectionRole,
    item_index: usize,
    reason: owner_graph::OwnerGraphOwnedChildReason,
) -> DeclaredOwnerChildFailure {
    DeclaredOwnerChildFailure {
        role,
        item_index,
        reason,
    }
}

fn parse_attribute_tabular_section_child_objects(
    owner_kind: &str,
    owner_name: &str,
    text: &str,
    owner_uuid: &str,
    catalog_direct_wrapper_code: Option<u32>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Vec<MetadataChildObject> {
    parse_attribute_tabular_section_child_objects_with_declared_failure(
        owner_kind,
        owner_name,
        text,
        owner_uuid,
        catalog_direct_wrapper_code,
        type_index,
        object_refs,
        metadata_object_refs,
        form_refs,
        None,
    )
    .expect("legacy child scanner has no declared-inventory failure path")
}

fn parse_declared_owner_child_objects(
    owner_kind: &str,
    owner_name: &str,
    text: &str,
    owner_uuid: &str,
    catalog_direct_wrapper_code: Option<u32>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    declared_inventory: &DeclaredOwnerChildInventory,
) -> Result<Vec<MetadataChildObject>, DeclaredOwnerChildFailure> {
    parse_attribute_tabular_section_child_objects_with_declared_failure(
        owner_kind,
        owner_name,
        text,
        owner_uuid,
        catalog_direct_wrapper_code,
        type_index,
        object_refs,
        metadata_object_refs,
        form_refs,
        Some(declared_inventory),
    )
}

fn parse_attribute_tabular_section_child_objects_with_declared_failure(
    owner_kind: &str,
    owner_name: &str,
    text: &str,
    owner_uuid: &str,
    catalog_direct_wrapper_code: Option<u32>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    declared_inventory: Option<&DeclaredOwnerChildInventory>,
) -> Result<Vec<MetadataChildObject>, DeclaredOwnerChildFailure> {
    let mut roots = Vec::<MetadataChildObject>::new();
    let mut tabular_section_indexes = BTreeMap::<String, usize>::new();
    let mut pending_by_tabular_section = BTreeMap::<String, Vec<MetadataChildObject>>::new();
    let mut attribute_first_order = false;
    let document_data_path_owner_proof = (owner_kind == "Document")
        .then(|| build_document_data_path_owner_proof(owner_name, text, owner_uuid));

    for (header, marker_start) in nested_headers_with_offsets_from_text(text, owner_uuid, |_| true)
    {
        let Some((tag, parent_tabular_section)) = attribute_tabular_section_child_object_tag(
            owner_kind,
            owner_name,
            owner_uuid,
            text,
            marker_start,
            &header,
        ) else {
            continue;
        };
        if let Some(failure) = declared_inventory.and_then(|inventory| {
            inventory.failure_for_observed(&tag, &header.uuid, parent_tabular_section.as_ref())
        }) {
            return Err(failure);
        }
        let mut value_types = if tag == "Attribute" && owner_kind == "Catalog" {
            parse_metadata_child_value_types_with_builtin(
                text,
                marker_start,
                &header.uuid,
                type_index,
                platform_reference_family_type_reference,
            )
        } else if tag == "Attribute" && owner_kind == "DataProcessor" {
            parse_metadata_child_value_types_with_builtin(
                text,
                marker_start,
                &header.uuid,
                type_index,
                data_processor_builtin_type_reference,
            )
        } else if tag == "Attribute" {
            parse_metadata_child_value_types(text, marker_start, &header.uuid, type_index)
        } else {
            Vec::new()
        };
        // A Document orders its attribute types exactly like a Catalog, a
        // BusinessProcess or a DataProcessor: ordinary types first, type sets
        // last. Documents used to keep the raw pattern order instead, which was
        // indistinguishable for every Document whose pattern already listed its
        // type sets last, and wrong for the two that do not - the `Основание`
        // attribute of `Documents/ПоручениеЭкспедитору` (pattern
        // `cfg:DocumentRef` before `xs:string`) and the `ОбъектВладелец`
        // attribute of `Documents/ТранспортныйКонтейнерЭДО` (pattern
        // `cfg:DocumentRef` before `cfg:CatalogRef.…`). Applying the shared
        // partition to Documents makes both match and moves no other file of
        // the 50 898 in the native tree of 1C:Trade Management 11.5.27.75.
        if matches!(
            owner_kind,
            OWNER_KIND_BUSINESS_PROCESS | "Catalog" | "DataProcessor" | "Document"
        ) {
            attribute_first_order = matches!(owner_kind, "Catalog" | "DataProcessor");
            value_types =
                stable_partition_metadata_types(classify_metadata_reference_type_sets(value_types));
        }
        let properties = if tag == "Attribute" && owner_kind == "Catalog" {
            let expected_wrapper_code = if parent_tabular_section.is_some() {
                8
            } else {
                let Some(wrapper_code) = catalog_direct_wrapper_code else {
                    continue;
                };
                wrapper_code
            };
            parse_catalog_child_properties(
                owner_name,
                text,
                marker_start,
                &header.uuid,
                expected_wrapper_code,
                &value_types,
                type_index,
                object_refs,
                metadata_object_refs,
                form_refs,
            )
        } else if tag == "Attribute" && owner_kind == "Document" {
            document_data_path_owner_proof.as_ref().and_then(|proof| {
                parse_document_child_properties(
                    owner_name,
                    text,
                    marker_start,
                    &header.uuid,
                    parent_tabular_section.is_some(),
                    &value_types,
                    type_index,
                    object_refs,
                    metadata_object_refs,
                    form_refs,
                    proof,
                )
            })
        } else if tag == "Attribute" && owner_kind == "BusinessProcess" {
            parse_business_process_child_properties(
                text,
                marker_start,
                &header.uuid,
                parent_tabular_section.is_some(),
                type_index,
                metadata_object_refs,
            )
        } else if tag == "Attribute" {
            parse_metadata_child_properties(
                owner_kind,
                text,
                marker_start,
                &header.uuid,
                &value_types,
                type_index,
                object_refs,
                metadata_object_refs,
                form_refs,
            )
        } else {
            None
        };
        if tag == OWNER_CHILD_ATTRIBUTE_TAG && declared_inventory.is_some() && properties.is_none()
        {
            return Err(declared_inventory
                .expect("attribute property failure is declared-only")
                .location_for(&tag, &header.uuid, parent_tabular_section.as_ref()));
        }
        let (generated_types, tabular_section_properties) = if tag == "TabularSection" {
            match parse_exact_metadata_tabular_section(
                owner_kind,
                owner_name,
                text,
                marker_start,
                &header,
            ) {
                Some(Some(exact)) => (exact.generated_types, Some(exact.properties)),
                Some(None) | None => (
                    (owner_kind == "DataProcessor")
                        .then(|| {
                            parse_data_processor_tabular_section_generated_types(
                                text,
                                marker_start,
                                &header,
                                owner_name,
                            )
                        })
                        .unwrap_or_default(),
                    parse_metadata_tabular_section_properties(
                        owner_kind,
                        text,
                        marker_start,
                        &header.uuid,
                    ),
                ),
            }
        } else {
            (Vec::new(), None)
        };
        if tag == OWNER_CHILD_TABULAR_SECTION_TAG
            && declared_inventory.is_some()
            && tabular_section_properties.is_none()
        {
            return Err(declared_inventory
                .expect("tabular-section property failure is declared-only")
                .location_for(&tag, &header.uuid, parent_tabular_section.as_ref()));
        }
        let child = MetadataChildObject {
            tag,
            generated_types,
            value_types,
            emit_empty_type: tag == "Attribute",
            properties,
            register_properties: None,
            tabular_section_properties,
            header,
            child_objects: Vec::new(),
        };
        if tag == "TabularSection" {
            let tabular_section_uuid = child.header.uuid.clone();
            let root_index = roots.len();
            roots.push(child);
            tabular_section_indexes.insert(tabular_section_uuid.clone(), root_index);
            if let Some(pending) = pending_by_tabular_section.remove(&tabular_section_uuid) {
                roots[root_index].child_objects.extend(pending);
            }
            continue;
        }
        if let Some(tabular_section) = parent_tabular_section {
            if let Some(root_index) = tabular_section_indexes.get(&tabular_section.uuid).copied() {
                roots[root_index].child_objects.push(child);
            } else {
                pending_by_tabular_section
                    .entry(tabular_section.uuid)
                    .or_default()
                    .push(child);
            }
            continue;
        }
        roots.push(child);
    }

    if let Some(inventory) = declared_inventory {
        if let Some(failure) = inventory.first_missing(&roots) {
            return Err(failure);
        }
        roots.sort_by_key(|child| inventory.root_order(child).unwrap_or(usize::MAX));
        for section in roots
            .iter_mut()
            .filter(|child| child.tag == OWNER_CHILD_TABULAR_SECTION_TAG)
        {
            section.child_objects.sort_by_key(|child| {
                inventory
                    .child_order(&section.header.uuid, &child.header.uuid)
                    .unwrap_or(usize::MAX)
            });
        }
    } else if attribute_first_order {
        roots.sort_by_key(|child| match child.tag {
            "Attribute" => 0usize,
            "TabularSection" => 1usize,
            _ => 2usize,
        });
    }

    Ok(roots)
}

fn parse_metadata_child_value_types(
    text: &str,
    marker_start: usize,
    child_uuid: &str,
    type_index: &BTreeMap<String, String>,
) -> Vec<ConstantValueType> {
    let Some((_, _, fields)) =
        innermost_metadata_object_fields_around_header(text, marker_start, child_uuid)
    else {
        return Vec::new();
    };

    fields
        .iter()
        .filter_map(|field| parse_metadata_type_pattern_from_child_field(field, type_index))
        .find(|value_types| !value_types.is_empty())
        .unwrap_or_default()
}

pub(super) fn parse_metadata_child_value_types_with_builtin(
    text: &str,
    marker_start: usize,
    child_uuid: &str,
    type_index: &BTreeMap<String, String>,
    builtin_reference: fn(&str) -> Option<&'static str>,
) -> Vec<ConstantValueType> {
    let Some((_, _, fields)) =
        innermost_metadata_object_fields_around_header(text, marker_start, child_uuid)
    else {
        return Vec::new();
    };

    fields
        .iter()
        .filter_map(|field| {
            parse_metadata_type_pattern_from_child_field_with_builtin(
                field,
                type_index,
                builtin_reference,
            )
        })
        .find(|value_types| !value_types.is_empty())
        .unwrap_or_default()
}

struct DataProcessorEmptyRefExpectation {
    type_reference: String,
    fill_value: String,
}

fn parse_data_processor_empty_ref_fill_values(
    text: &str,
    owner_header: &MetadataHeader,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<BTreeMap<String, DataProcessorEmptyRefExpectation>> {
    let mut attributes = BTreeMap::new();

    for (header, marker_start) in
        nested_headers_with_offsets_from_text(text, &owner_header.uuid, |_| true)
    {
        if !is_offset_inside_metadata_object_code(text, marker_start, 27)
            || !is_offset_inside_tabular_section_attribute_list(text, marker_start)
            || !matches!(
                attribute_tabular_section_child_object_tag(
                    "DataProcessor",
                    &owner_header.name,
                    &owner_header.uuid,
                    text,
                    marker_start,
                    &header,
                ),
                Some(("Attribute", Some(_)))
            )
        {
            continue;
        }

        let mut matching_object = None;
        for fields in
            metadata_object_field_candidates_around_header(text, marker_start, &header.uuid)
                .into_iter()
                .filter(|fields| fields.first().is_some_and(|field| field.trim() == "27"))
        {
            if !fields
                .iter()
                .any(|field| data_processor_design_time_ref_descriptor(field))
            {
                continue;
            }
            if matching_object.is_some() {
                return None;
            }
            let flattened = flatten_data_processor_wrapped_child_fields(&fields)?;
            let fill_value = flattened.get(20).copied()?;
            matching_object = Some((fields, flattened, fill_value));
        }

        let Some((fields, flattened, fill_value)) = matching_object else {
            continue;
        };
        if data_processor_tabular_attribute_identity_count(text, &header.uuid) != 1 {
            return None;
        }
        if !has_exact_data_processor_tabular_attribute_wrappers(
            text,
            marker_start,
            &header.uuid,
            &fields,
        ) {
            return None;
        }
        if flattened.len() != 24 {
            return None;
        }
        let (_, parsed_child_uuid) = parse_metadata_code27_payload_fields(fields.clone())?;
        if !parsed_child_uuid.eq_ignore_ascii_case(&header.uuid) {
            return None;
        }
        let pattern = data_processor_code27_type_pattern(&fields, &header)?;
        let pattern_type_ids = data_processor_reference_pattern_type_ids(pattern)?;
        let fill_owner_type_id = parse_data_processor_empty_ref_fill_owner(fill_value)?;
        let selected_count = pattern_type_ids
            .iter()
            .filter(|type_id| type_id.eq_ignore_ascii_case(&fill_owner_type_id))
            .count();
        if selected_count != 1
            || object_refs
                .keys()
                .any(|key| key.eq_ignore_ascii_case(&fill_owner_type_id))
        {
            return None;
        }
        let type_reference =
            unique_metadata_type_reference(type_index, type_index_collisions, &fill_owner_type_id)?;
        let owner_reference =
            parse_generated_metadata_reference_owner(type_reference)?.owner_reference();
        let key = header.uuid.to_ascii_lowercase();
        if attributes
            .insert(
                key,
                DataProcessorEmptyRefExpectation {
                    type_reference: type_reference.to_string(),
                    fill_value: format!("{owner_reference}.EmptyRef"),
                },
            )
            .is_some()
        {
            return None;
        }
    }

    Some(attributes)
}

fn data_processor_tabular_attribute_identity_count(text: &str, child_uuid: &str) -> usize {
    let lower_text = text.to_ascii_lowercase();
    let lower_uuid = child_uuid.to_ascii_lowercase();
    lower_text
        .match_indices(&lower_uuid)
        .filter(|(offset, _)| {
            is_offset_inside_metadata_object_code(text, *offset, 27)
                && is_offset_inside_tabular_section_attribute_list(text, *offset)
                && text[..*offset].rfind('{').is_some_and(|start| {
                    split_1c_braced_fields(text, start).is_some_and(|identity| {
                        identity.len() == 3
                            && identity.first().map(|field| field.trim()) == Some("1")
                            && identity.get(1).map(|field| field.trim()) == Some("0")
                            && identity
                                .get(2)
                                .is_some_and(|field| field.trim().eq_ignore_ascii_case(child_uuid))
                    })
                })
        })
        .count()
}

fn data_processor_design_time_ref_descriptor(field: &str) -> bool {
    let Some(fields) = split_1c_braced_fields(field.trim(), 0) else {
        return false;
    };
    fields.first().map(|field| field.trim()) == Some(r##""#""##)
        && fields
            .get(1)
            .and_then(|field| parse_uuid_field(field.trim()))
            .is_some_and(|type_id| type_id.eq_ignore_ascii_case(DESIGN_TIME_REF_TYPE_UUID))
}

fn has_exact_data_processor_tabular_attribute_wrappers(
    text: &str,
    marker_start: usize,
    child_uuid: &str,
    expected_payload: &[&str],
) -> bool {
    let mut matching_wrappers = 0;
    for outer in metadata_object_field_candidates_around_header(text, marker_start, child_uuid) {
        if outer.len() != 2 || outer.get(1).map(|field| field.trim()) != Some("0") {
            continue;
        }
        let Some(inner) = outer
            .first()
            .and_then(|field| split_1c_braced_fields(field.trim(), 0))
        else {
            continue;
        };
        if inner.len() != 2 || inner.first().map(|field| field.trim()) != Some("0") {
            continue;
        }
        let Some(payload) = inner
            .get(1)
            .and_then(|field| split_1c_braced_fields(field.trim(), 0))
        else {
            continue;
        };
        if payload == expected_payload {
            matching_wrappers += 1;
        }
    }
    matching_wrappers == 1
}

fn data_processor_reference_pattern_type_ids(pattern: &str) -> Option<Vec<String>> {
    let fields = split_information_register_braced_fields(pattern)?;
    if fields.len() < 2
        || !owner_graph::DataProcessorPhysicalSchema::reference_pattern(fields.first()?.trim())
    {
        return None;
    }
    let mut seen = BTreeSet::new();
    fields
        .iter()
        .skip(1)
        .map(|member| {
            let member = split_information_register_braced_fields(member)?;
            if member.len() != 2
                || !owner_graph::DataProcessorPhysicalSchema::reference_member(
                    member.first()?.trim(),
                )
            {
                return None;
            }
            let type_id = parse_information_register_non_zero_uuid(member.get(1)?)?;
            seen.insert(type_id.to_ascii_lowercase()).then_some(type_id)
        })
        .collect()
}

fn parse_data_processor_empty_ref_fill_owner(value: &str) -> Option<String> {
    let fields = split_information_register_braced_fields(value)?;
    if fields.len() != 3
        || fields.first()?.trim() != r##""#""##
        || !fields
            .get(1)?
            .trim()
            .eq_ignore_ascii_case(DESIGN_TIME_REF_TYPE_UUID)
    {
        return None;
    }
    let reference = split_information_register_braced_fields(fields.get(2)?)?;
    if reference.len() != 3 || reference.first()?.trim() != "0" {
        return None;
    }
    let owner_type_id = parse_information_register_non_zero_uuid(reference.get(1)?)?;
    let value_id = parse_information_register_uuid(reference.get(2)?)?;
    information_register_uuid_is_zero(&value_id).then_some(owner_type_id)
}

fn apply_data_processor_empty_ref_fill_values(
    child_objects: &mut [MetadataChildObject],
    expected_attributes: &BTreeMap<String, DataProcessorEmptyRefExpectation>,
) -> bool {
    let mut matched_attributes = BTreeSet::new();
    apply_data_processor_empty_ref_fill_values_inner(
        child_objects,
        expected_attributes,
        &mut matched_attributes,
    ) && matched_attributes.len() == expected_attributes.len()
}

fn apply_data_processor_empty_ref_fill_values_inner(
    child_objects: &mut [MetadataChildObject],
    expected_attributes: &BTreeMap<String, DataProcessorEmptyRefExpectation>,
    matched_attributes: &mut BTreeSet<String>,
) -> bool {
    for child in child_objects {
        let uuid = child.header.uuid.to_ascii_lowercase();
        if let Some(expected) = expected_attributes.get(&uuid) {
            let value_type_matches = child
                .value_types
                .iter()
                .filter(|value_type| {
                    matches!(
                        value_type,
                        ConstantValueType::Reference { reference }
                            if reference == &expected.type_reference
                    )
                })
                .count()
                == 1;
            let Some(properties) = child.properties.as_mut() else {
                return false;
            };
            if child.tag != "Attribute"
                || !value_type_matches
                || !properties.emit_fill_value
                || properties.fill_value.is_some()
                || !matched_attributes.insert(uuid)
            {
                return false;
            }
            properties.fill_value = Some(MetadataChildFillValue::DesignTimeRef(
                expected.fill_value.clone(),
            ));
        }
        if !apply_data_processor_empty_ref_fill_values_inner(
            &mut child.child_objects,
            expected_attributes,
            matched_attributes,
        ) {
            return false;
        }
    }
    true
}

fn parse_data_processor_settings_composer_attributes(
    text: &str,
    owner_header: &MetadataHeader,
    type_index: &BTreeMap<String, String>,
) -> Option<BTreeSet<String>> {
    let mut attributes = BTreeSet::new();

    for (header, marker_start) in
        nested_headers_with_offsets_from_text(text, &owner_header.uuid, |_| true)
    {
        if !is_offset_inside_metadata_object_code(text, marker_start, 27)
            || !matches!(
                attribute_tabular_section_child_object_tag(
                    "DataProcessor",
                    &owner_header.name,
                    &owner_header.uuid,
                    text,
                    marker_start,
                    &header,
                ),
                Some(("Attribute", _))
            )
        {
            continue;
        }

        let mut matching_object = None;
        for fields in
            metadata_object_field_candidates_around_header(text, marker_start, &header.uuid)
                .into_iter()
                .filter(|fields| fields.first().is_some_and(|field| field.trim() == "27"))
        {
            let Some(pattern) = data_processor_code27_type_pattern(&fields, &header) else {
                continue;
            };
            if !pattern
                .to_ascii_lowercase()
                .contains(DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_UUID)
            {
                continue;
            }
            if matching_object.is_some() {
                return None;
            }
            matching_object = Some((fields, pattern));
        }

        let Some((fields, pattern)) = matching_object else {
            continue;
        };
        if type_index
            .keys()
            .any(|type_id| type_id.eq_ignore_ascii_case(DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_UUID))
            || parse_metadata_code27_payload_fields(fields).is_none()
            || !data_processor_settings_composer_pattern_is_exact(pattern)
            || !attributes.insert(header.uuid.to_ascii_lowercase())
        {
            return None;
        }
    }

    Some(attributes)
}

fn data_processor_code27_type_pattern<'a>(
    fields: &[&'a str],
    expected_header: &MetadataHeader,
) -> Option<&'a str> {
    if fields.first()?.trim() != "27" {
        return None;
    }
    let detail = split_information_register_braced_fields(fields.get(1)?)?;
    if detail.len() != 3 || detail.first()?.trim() != "2" {
        return None;
    }
    let parsed_header = parse_information_register_owner_header(detail.get(1)?)?;
    if !parsed_header
        .uuid
        .eq_ignore_ascii_case(&expected_header.uuid)
        || parsed_header.name != expected_header.name
        || parsed_header.synonyms != expected_header.synonyms
        || parsed_header.comment != expected_header.comment
    {
        return None;
    }
    detail.get(2).copied()
}

fn data_processor_settings_composer_pattern_is_exact(pattern: &str) -> bool {
    let Some(pattern) = split_information_register_braced_fields(pattern) else {
        return false;
    };
    if pattern.len() != 2
        || pattern
            .first()
            .is_none_or(|value| value.trim() != r#""Pattern""#)
    {
        return false;
    }
    let Some(member) = split_information_register_braced_fields(pattern[1]) else {
        return false;
    };
    member.len() == 2
        && member
            .first()
            .is_some_and(|value| value.trim() == r##""#""##)
        && parse_information_register_non_zero_uuid(member[1]).is_some_and(|type_id| {
            type_id.eq_ignore_ascii_case(DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_UUID)
        })
}

fn apply_data_processor_settings_composer_types(
    child_objects: &mut [MetadataChildObject],
    expected_attributes: &BTreeSet<String>,
) -> bool {
    let mut matched_attributes = BTreeSet::new();
    apply_data_processor_settings_composer_types_inner(
        child_objects,
        expected_attributes,
        &mut matched_attributes,
    ) && matched_attributes == *expected_attributes
}

fn apply_data_processor_settings_composer_types_inner(
    child_objects: &mut [MetadataChildObject],
    expected_attributes: &BTreeSet<String>,
    matched_attributes: &mut BTreeSet<String>,
) -> bool {
    for child in child_objects {
        let uuid = child.header.uuid.to_ascii_lowercase();
        if expected_attributes.contains(&uuid) {
            if child.tag != "Attribute"
                || !child.value_types.is_empty()
                || !matched_attributes.insert(uuid)
            {
                return false;
            }
            child.value_types.push(ConstantValueType::Reference {
                reference: DATA_PROCESSOR_SETTINGS_COMPOSER_TYPE_NAME.to_string(),
            });
        }
        if !apply_data_processor_settings_composer_types_inner(
            &mut child.child_objects,
            expected_attributes,
            matched_attributes,
        ) {
            return false;
        }
    }
    true
}

fn parse_exact_metadata_tabular_section(
    owner_kind: &str,
    owner_name: &str,
    text: &str,
    marker_start: usize,
    header: &MetadataHeader,
) -> Option<Option<ExactMetadataTabularSection>> {
    if !matches!(
        owner_kind,
        "Catalog"
            | "Document"
            | "ExchangePlan"
            | "ChartOfCharacteristicTypes"
            | "Report"
            | "BusinessProcess"
            | "DataProcessor"
    ) {
        return Some(None);
    }

    let mut candidates =
        metadata_object_field_candidates_around_header(text, marker_start, &header.uuid)
            .into_iter()
            .filter(|fields| {
                fields.len() == 9
                    && fields.first().map(|field| field.trim()) == Some("11")
                    && metadata_header_field_index(fields, &header.uuid) == Some(5)
            });
    let Some(fields) = candidates.next() else {
        return Some(None);
    };
    if candidates.next().is_some() {
        return None;
    }

    let parsed_header = parse_wrapped_register_owner_header(fields.get(5)?)?;
    if !parsed_header.uuid.eq_ignore_ascii_case(&header.uuid)
        || parsed_header.name != header.name
        || parsed_header.synonyms != header.synonyms
        || parsed_header.comment != header.comment
    {
        return None;
    }

    let generated_ids = fields[1..5]
        .iter()
        .map(|field| parse_information_register_non_zero_uuid(field))
        .collect::<Option<Vec<_>>>()?;
    if generated_ids
        .iter()
        .map(|uuid| uuid.to_ascii_lowercase())
        .collect::<BTreeSet<_>>()
        .len()
        != generated_ids.len()
    {
        return None;
    }

    let fill_checking = match fields.get(6)?.trim() {
        "0" => "DontCheck",
        "1" => "ShowError",
        _ => return None,
    };
    let (line_number_fill_value, line_number_synonym) =
        match parse_exact_tabular_section_standard_attributes_presence(owner_kind, fields.get(7)?)?
        {
            Some((fill_value, synonym)) => (Some(fill_value), synonym),
            None => (None, Vec::new()),
        };
    let tooltip = parse_information_register_owner_localized_value(fields.get(8)?)?;
    let TabularSectionEnvelope {
        use_mode,
        line_number_length,
    } = parse_exact_tabular_section_envelope(owner_kind, text, marker_start, &header.uuid)?;

    Some(Some(ExactMetadataTabularSection {
        generated_types: vec![
            GeneratedTypeEntry {
                name: format!("{owner_kind}TabularSection.{owner_name}.{}", header.name),
                category: "TabularSection",
                type_id: generated_ids[0].clone(),
                value_id: generated_ids[1].clone(),
            },
            GeneratedTypeEntry {
                name: format!("{owner_kind}TabularSectionRow.{owner_name}.{}", header.name),
                category: "TabularSectionRow",
                type_id: generated_ids[2].clone(),
                value_id: generated_ids[3].clone(),
            },
        ],
        properties: MetadataTabularSectionProperties {
            tooltip,
            fill_checking,
            line_number_fill_checking: if line_number_fill_value.is_some() {
                "DontCheck"
            } else {
                ""
            },
            line_number_fill_value,
            line_number_synonym,
            use_mode,
            line_number_length,
        },
    }))
}

fn parse_exact_tabular_section_standard_attributes_presence(
    owner_kind: &str,
    value: &str,
) -> Option<Option<(MetadataChildFillValue, Vec<(String, String)>)>> {
    let outer = split_information_register_braced_fields(value)?;
    match outer.as_slice() {
        [marker] if marker.trim() == "0" => Some(None),
        [marker, payload] if marker.trim() == "1" => {
            let expected_attribute_marker = match owner_kind {
                // A BusinessProcess writes the same `-10` LineNumber marker as
                // the four families already listed: all five tabular sections
                // of the seven business processes of UT 11.5.27.75 carry it,
                // byte for byte the same standard-attribute record the
                // catalogs, documents and characteristic charts carry.
                "Catalog"
                | "Document"
                | "ExchangePlan"
                | "ChartOfCharacteristicTypes"
                | OWNER_KIND_BUSINESS_PROCESS => "-10",
                "Report" | "DataProcessor" => "-3",
                _ => return None,
            };
            let payload = split_information_register_braced_fields(payload)?;
            if payload.len() != 5
                || payload.first()?.trim() != "1"
                || parse_information_register_usize(payload.get(1)?)? != 1
            {
                return None;
            }
            let attribute_marker = split_information_register_braced_fields(payload.get(2)?)?;
            if attribute_marker.len() != 1
                || attribute_marker.first()?.trim() != expected_attribute_marker
                || !information_register_uuid_matches(
                    payload.get(3)?,
                    INFORMATION_REGISTER_STANDARD_ATTRIBUTE_SECTION_UUID,
                )
            {
                return None;
            }
            let bag = parse_information_register_standard_attribute_bag(payload.get(4)?)?;
            let fill_value = split_information_register_braced_fields(
                bag.get(INFORMATION_REGISTER_STANDARD_ATTRIBUTE_FILL_VALUE_PROPERTY_UUID)?,
            )?;
            let fill_value = match fill_value.as_slice() {
                [kind] if kind.trim() == r#""U""# => MetadataChildFillValue::Nil,
                [kind, value]
                    if kind.trim() == r#""N""#
                        && information_register_decimal_is_valid(value.trim()) =>
                {
                    MetadataChildFillValue::Decimal(value.trim().to_string())
                }
                _ => return None,
            };
            let synonym = parse_information_register_standard_attribute_localized(
                bag.get(INFORMATION_REGISTER_STANDARD_ATTRIBUTE_SYNONYM_PROPERTY_UUID)?,
            )?;
            Some(Some((fill_value, synonym)))
        }
        _ => None,
    }
}

/// Locates the envelope that wraps this section's nine-field payload and reads
/// the section's own stored properties out of it.
///
/// The enclosing envelope is unambiguous: across the 1 438 tabular sections
/// that reach this scan in UT 11.5.27.75 exactly one brace group encloses the
/// marker and carries the section as its second field.
fn parse_exact_tabular_section_envelope(
    owner_kind: &str,
    text: &str,
    marker_start: usize,
    child_uuid: &str,
) -> Option<TabularSectionEnvelope> {
    let mut search_end = marker_start;
    let mut matches = Vec::<(usize, TabularSectionEnvelope)>::new();
    while let Some(start) = text[..search_end].rfind('{') {
        search_end = start;
        let Some(end) = scan_1c_braced_value(text, start) else {
            continue;
        };
        if marker_start >= end {
            continue;
        }
        let Some(fields) = split_information_register_braced_fields(&text[start..end]) else {
            continue;
        };
        let Some(section) = split_information_register_braced_fields(fields.get(1)?) else {
            continue;
        };
        if section.len() != 9
            || section.first().map(|field| field.trim()) != Some("11")
            || metadata_header_field_index(&section, child_uuid) != Some(5)
        {
            continue;
        }
        let Some(envelope) = parse_tabular_section_envelope(owner_kind, &fields) else {
            continue;
        };
        matches.push((end.saturating_sub(start), envelope));
    }
    matches.sort_by_key(|(span, _)| *span);
    match matches.as_slice() {
        [(_, envelope)] => Some(*envelope),
        _ => None,
    }
}

/// The section's own stored properties, read out of the envelope that wraps its
/// nine-field payload.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct TabularSectionEnvelope {
    use_mode: Option<&'static str>,
    line_number_length: Option<u32>,
}

/// `(envelope code, carries Use, carries LineNumberLength)` for one owner
/// family.
///
/// The tabular-section envelope is one grammar across every family that owns
/// tabular sections: slot 0 is a per-family envelope code, slot 1 is the
/// nine-field section payload, and the trailing slots hold the section's own
/// stored properties - `Use` for the two families whose native XML carries it,
/// then `LineNumberLength`. The families that store no length also carry the
/// code one lower, so a single rule reproduces every observed envelope:
/// `Catalog` and `Document` write code 2, `ChartOfCharacteristicTypes`,
/// `BusinessProcess` and `ExchangePlan` write code 1, and `Report` and
/// `DataProcessor` - whose native XML has no `LineNumberLength` at all - write
/// code 0 with no trailing slots.
fn tabular_section_envelope_spec(owner_kind: &str) -> Option<(u32, bool, bool)> {
    Some(match owner_kind {
        "Catalog" => (2, true, true),
        "Document" => (2, false, true),
        "ChartOfCharacteristicTypes" => (1, true, true),
        OWNER_KIND_BUSINESS_PROCESS | "ExchangePlan" => (1, false, true),
        "Report" | "DataProcessor" => (0, false, false),
        _ => return None,
    })
}

/// `LineNumberLength` for the predecessor envelope, which stores none.
///
/// UT 11.5.27.75 never writes that envelope; the reference trees that do are
/// byte-exact with this value, so it is the platform's answer for them rather
/// than a guess carried into the observed shape.
const TABULAR_SECTION_PREDECESSOR_LINE_NUMBER_LENGTH: u32 = 5;

/// Reads the tabular-section envelope through the single family grammar.
///
/// Both trailing slots used to be pinned to constants in four separate
/// hand-written tables - `Use` to `ForItem` and `LineNumberLength` to 5 - so
/// every owner holding a section that stores anything else was refused whole.
/// Across the 1 203 tabular sections of UT 11.5.27.75 the last slot equals the
/// native `LineNumberLength` in every case (1 195 write 5, eight write 9) and
/// the `Use` slot equals the native `Use` in every case (387 `ForItem`, 11
/// `ForFolderAndItem`).
fn parse_tabular_section_envelope(
    owner_kind: &str,
    fields: &[&str],
) -> Option<TabularSectionEnvelope> {
    let (code, carries_use, carries_line_number_length) =
        tabular_section_envelope_spec(owner_kind)?;
    let use_slots = usize::from(carries_use);
    let observed_code = parse_information_register_usize(fields.first()?)
        .and_then(|value| u32::try_from(value).ok())?;
    let stores_length =
        carries_line_number_length && fields.len() == 2 + use_slots + 1 && observed_code == code;
    if !stores_length
        && (fields.len() != 2 + use_slots
            || observed_code != code.checked_sub(u32::from(carries_line_number_length))?)
    {
        return None;
    }
    let use_mode = if carries_use {
        Some(metadata_attribute_use_mode_xml(fields.get(2)?.trim())?)
    } else {
        None
    };
    let line_number_length = if carries_line_number_length {
        Some(if stores_length {
            parse_information_register_usize(fields.get(2 + use_slots)?)
                .and_then(|value| u32::try_from(value).ok())?
        } else {
            TABULAR_SECTION_PREDECESSOR_LINE_NUMBER_LENGTH
        })
    } else {
        None
    };
    Some(TabularSectionEnvelope {
        use_mode,
        line_number_length,
    })
}

fn parse_data_processor_tabular_section_generated_types(
    text: &str,
    marker_start: usize,
    header: &MetadataHeader,
    owner_name: &str,
) -> Vec<GeneratedTypeEntry> {
    for fields in metadata_object_field_candidates_around_header(text, marker_start, &header.uuid) {
        if fields.first().map(|field| field.trim()) != Some("11") {
            continue;
        }
        let mut generated_types = Vec::new();
        push_generated_type_entry(
            &mut generated_types,
            &fields,
            1,
            2,
            &format!("DataProcessorTabularSection.{owner_name}.{}", header.name),
            "TabularSection",
        );
        push_generated_type_entry(
            &mut generated_types,
            &fields,
            3,
            4,
            &format!(
                "DataProcessorTabularSectionRow.{owner_name}.{}",
                header.name
            ),
            "TabularSectionRow",
        );
        if !generated_types.is_empty() {
            return generated_types;
        }
    }
    Vec::new()
}

fn parse_metadata_child_properties(
    owner_kind: &str,
    text: &str,
    marker_start: usize,
    child_uuid: &str,
    value_types: &[ConstantValueType],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<MetadataChildProperties> {
    if owner_kind == "AccountingRegister" {
        for fields in metadata_object_field_candidates_around_header(text, marker_start, child_uuid)
        {
            if let Some(properties) =
                parse_accounting_register_child_properties_from_fields(&fields, child_uuid)
            {
                return Some(properties);
            }
        }
    }
    for fields in metadata_object_field_candidates_around_header(text, marker_start, child_uuid) {
        if let Some(mut properties) = parse_metadata_child_properties_from_fields(
            owner_kind,
            &fields,
            child_uuid,
            value_types,
            type_index,
            object_refs,
            metadata_object_refs,
            form_refs,
        ) {
            if owner_kind == "DataProcessor"
                && is_offset_inside_metadata_object_code(text, marker_start, 27)
                && is_offset_inside_data_processor_legacy_attribute_list(text, marker_start)
            {
                properties.emit_fill_from_filling_value = false;
                properties.emit_fill_value = false;
            }
            return Some(properties);
        }
    }
    None
}

struct AccumulationCalculationRegisterChildPayload {
    tag: &'static str,
    value_types: Vec<ConstantValueType>,
    properties: MetadataChildProperties,
    register_properties: RegisterMetadataChildProperties,
}

/// Parses the code-4 wrapper used for accumulation-register attributes.
///
/// Unlike dimensions and resources, these attributes have no register-specific
/// tail.  Their common code-27 payload is nevertheless complete and native
/// `ibcmd` writes its attribute defaults from it.  Keeping the outer wrapper
/// exact prevents applying those defaults to arbitrary code-27 children.
fn parse_accumulation_register_attribute_payload(
    owner_kind: &str,
    tag: &str,
    text: &str,
    marker_start: usize,
    child_header: &MetadataHeader,
    owner_name: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    preserve_raw_data_paths: bool,
) -> Option<(Vec<ConstantValueType>, MetadataChildProperties)> {
    if owner_kind != "AccumulationRegister" || tag != "Attribute" {
        return None;
    }
    let mut parsed =
        metadata_object_field_candidates_around_header(text, marker_start, &child_header.uuid)
            .into_iter()
            .filter_map(|fields| {
                if fields.len() != 6 || fields.first().map(|field| field.trim()) != Some("4") {
                    return None;
                }
                let indexing = metadata_attribute_indexing_xml(fields.get(2)?.trim())?;
                let full_text_search = register_child_full_text_search_xml(fields.get(3)?.trim())?;
                if fields.get(4).map(|field| field.trim()) != Some("0") {
                    return None;
                }
                let data_history = split_1c_braced_fields(fields.get(5)?.trim(), 0)?;
                if data_history.len() != 2
                    || data_history.first().map(|field| field.trim()) != Some("1")
                    || !information_register_uuid_is_zero(&parse_uuid_field(
                        data_history.get(1)?.trim(),
                    )?)
                {
                    return None;
                }
                let common_fields = split_1c_braced_fields(fields.get(1)?, 0)?;
                let value_types = parse_register_common_child_value_types(
                    &common_fields,
                    child_header,
                    type_index,
                )?;
                let mut properties = parse_information_register_common_child_properties(
                    &common_fields,
                    owner_kind,
                    owner_name,
                    type_index,
                    object_refs,
                    form_refs,
                    preserve_raw_data_paths,
                )?;
                // This wrapper has neither FillFromFillingValue nor FillValue in its
                // XCF property sequence; native emits the remaining common defaults.
                properties.emit_fill_from_filling_value = false;
                properties.emit_fill_value = false;
                properties.indexing = Some(indexing);
                properties.full_text_search = Some(full_text_search);
                Some((value_types, properties))
            });
    let payload = parsed.next()?;
    parsed.next().is_none().then_some(payload)
}

fn parse_accumulation_calculation_register_child_tag(
    owner_kind: &str,
    text: &str,
    marker_start: usize,
    child_header: &MetadataHeader,
) -> Option<&'static str> {
    let mut parsed =
        metadata_object_field_candidates_around_header(text, marker_start, &child_header.uuid)
            .into_iter()
            .filter_map(|fields| {
                parse_accumulation_calculation_register_child_tag_from_fields(
                    owner_kind,
                    &fields,
                    child_header,
                )
            });
    let tag = parsed.next()?;
    parsed.next().is_none().then_some(tag)
}

fn parse_accumulation_calculation_register_child_tag_from_fields(
    owner_kind: &str,
    fields: &[&str],
    child_header: &MetadataHeader,
) -> Option<&'static str> {
    let tag = match (owner_kind, fields.first()?.trim(), fields.len()) {
        ("AccumulationRegister", "5", 3) | ("CalculationRegister", "4", 3) => "Resource",
        ("AccumulationRegister", "8", 6) | ("CalculationRegister", "5", 7) => "Dimension",
        _ => return None,
    };
    let common_fields = split_1c_braced_fields(fields.get(1)?, 0)?;
    register_common_child_header_matches(&common_fields, child_header).then_some(tag)
}

fn parse_accumulation_calculation_register_child_payload(
    owner_kind: &str,
    text: &str,
    marker_start: usize,
    child_header: &MetadataHeader,
    owner_name: &str,
    calculation_schedule: Option<&CalculationRegisterScheduleProperties>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    preserve_raw_data_paths: bool,
) -> Option<AccumulationCalculationRegisterChildPayload> {
    if !matches!(owner_kind, "AccumulationRegister" | "CalculationRegister") {
        return None;
    }
    let mut parsed =
        metadata_object_field_candidates_around_header(text, marker_start, &child_header.uuid)
            .into_iter()
            .filter_map(|fields| {
                parse_accumulation_calculation_register_child_payload_from_fields(
                    owner_kind,
                    &fields,
                    child_header,
                    owner_name,
                    calculation_schedule,
                    type_index,
                    object_refs,
                    form_refs,
                    preserve_raw_data_paths,
                )
            });
    let value = parsed.next()?;
    if parsed.next().is_some() {
        return None;
    }
    Some(value)
}

fn parse_accumulation_calculation_register_child_payload_from_fields(
    owner_kind: &str,
    fields: &[&str],
    child_header: &MetadataHeader,
    owner_name: &str,
    calculation_schedule: Option<&CalculationRegisterScheduleProperties>,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    preserve_raw_data_paths: bool,
) -> Option<AccumulationCalculationRegisterChildPayload> {
    let (tag, register_properties) = match (owner_kind, fields.first()?.trim(), fields.len()) {
        ("AccumulationRegister", "5", 3) => (
            "Resource",
            RegisterMetadataChildProperties {
                deny_incomplete_values: None,
                base_dimension: None,
                schedule_link: None,
                indexing: None,
                full_text_search: register_child_full_text_search_xml(fields.get(2)?.trim())?,
                use_in_totals: None,
            },
        ),
        ("AccumulationRegister", "8", 6) => (
            "Dimension",
            RegisterMetadataChildProperties {
                deny_incomplete_values: Some(information_register_bool(fields.get(2)?)?),
                base_dimension: None,
                schedule_link: None,
                indexing: Some(metadata_attribute_indexing_xml(fields.get(3)?.trim())?),
                full_text_search: register_child_full_text_search_xml(fields.get(4)?.trim())?,
                use_in_totals: Some(information_register_bool(fields.get(5)?)?),
            },
        ),
        ("CalculationRegister", "4", 3) => (
            "Resource",
            RegisterMetadataChildProperties {
                deny_incomplete_values: None,
                base_dimension: None,
                schedule_link: None,
                indexing: None,
                full_text_search: register_child_full_text_search_xml(fields.get(2)?.trim())?,
                use_in_totals: None,
            },
        ),
        ("CalculationRegister", "5", 7) => {
            let schedule_link = parse_calculation_register_dimension_reference(
                fields.get(4)?,
                calculation_schedule,
                object_refs,
            )?;
            (
                "Dimension",
                RegisterMetadataChildProperties {
                    deny_incomplete_values: Some(information_register_bool(fields.get(2)?)?),
                    base_dimension: Some(information_register_bool(fields.get(3)?)?),
                    schedule_link: Some(schedule_link),
                    indexing: Some(metadata_attribute_indexing_xml(fields.get(5)?.trim())?),
                    full_text_search: register_child_full_text_search_xml(fields.get(6)?.trim())?,
                    use_in_totals: None,
                },
            )
        }
        _ => return None,
    };
    let common_fields = split_1c_braced_fields(fields.get(1)?, 0)?;
    let value_types =
        parse_register_common_child_value_types(&common_fields, child_header, type_index)?;
    let mut properties = parse_information_register_common_child_properties(
        &common_fields,
        owner_kind,
        owner_name,
        type_index,
        object_refs,
        form_refs,
        preserve_raw_data_paths,
    )?;
    properties.emit_fill_from_filling_value = false;
    properties.emit_fill_value = false;
    Some(AccumulationCalculationRegisterChildPayload {
        tag,
        value_types,
        properties,
        register_properties,
    })
}

fn parse_calculation_register_dimension_reference(
    value: &str,
    calculation_schedule: Option<&CalculationRegisterScheduleProperties>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let uuid = parse_uuid_field(value.trim())?;
    if information_register_uuid_is_zero(&uuid) {
        return Some(String::new());
    }
    let schedule = calculation_schedule?;
    let reference = unique_case_insensitive_object_reference(&uuid, object_refs)?.to_string();
    let schedule_parts = schedule.schedule.split('.').collect::<Vec<_>>();
    let parts = reference.split('.').collect::<Vec<_>>();
    let ["InformationRegister", schedule_owner] = schedule_parts.as_slice() else {
        return None;
    };
    let [
        "InformationRegister",
        candidate_owner,
        "Dimension",
        dimension,
    ] = parts.as_slice()
    else {
        return None;
    };
    (!dimension.is_empty() && candidate_owner == schedule_owner).then_some(reference)
}

fn parse_register_common_child_value_types(
    common_fields: &[&str],
    child_header: &MetadataHeader,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    if !register_common_child_header_matches(common_fields, child_header) {
        return None;
    }
    let typed_header = split_1c_braced_fields(common_fields.get(1)?, 0)?;
    Some(stable_partition_metadata_types(
        parse_information_register_type_pattern(typed_header.get(2)?, type_index)?,
    ))
}

fn register_common_child_header_matches(
    common_fields: &[&str],
    child_header: &MetadataHeader,
) -> bool {
    if common_fields.len() != 23 || common_fields.first().map(|field| field.trim()) != Some("27") {
        return false;
    }
    let Some(typed_header) = common_fields
        .get(1)
        .and_then(|field| split_1c_braced_fields(field, 0))
    else {
        return false;
    };
    if typed_header.len() != 3 || typed_header.first().map(|field| field.trim()) != Some("2") {
        return false;
    }
    let Some(header_fields) = typed_header
        .get(1)
        .and_then(|field| split_1c_braced_fields(field, 0))
    else {
        return false;
    };
    // Same code27 attribute-header short-wrapper omission `06249bd`
    // documents for `parse_metadata_code27_payload_fields`: this is a hand
    // reimplementation of that exact `{27,{2,header,{"Pattern",...}}}`
    // shape for InformationRegister-owned children specifically, so it
    // needs the same 9/8-member branch instead of hard-requiring 9.
    let header_has_trailing_default = match header_fields.len() {
        9 => true,
        8 => false,
        _ => return false,
    };
    if header_fields.first().map(|field| field.trim())
        != Some(if header_has_trailing_default {
            "3"
        } else {
            "2"
        })
        || metadata_header_field_index(&header_fields, &child_header.uuid) != Some(1)
    {
        return false;
    }
    let Some(parsed_header) = typed_header
        .get(1)
        .and_then(|field| parse_metadata_header_from_text(field, &child_header.uuid))
    else {
        return false;
    };
    parsed_header.uuid == child_header.uuid
        && parsed_header.name == child_header.name
        && parsed_header.synonyms == child_header.synonyms
        && parsed_header.comment == child_header.comment
}

fn parse_information_register_child_payload(
    text: &str,
    marker_start: usize,
    child_header: &MetadataHeader,
    owner_name: &str,
    tag: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    preserve_raw_data_paths: bool,
) -> Option<(Vec<ConstantValueType>, MetadataChildProperties)> {
    let mut parsed =
        metadata_object_field_candidates_around_header(text, marker_start, &child_header.uuid)
            .into_iter()
            .filter_map(|fields| {
                parse_information_register_child_payload_from_fields(
                    &fields,
                    child_header,
                    owner_name,
                    tag,
                    type_index,
                    object_refs,
                    form_refs,
                    preserve_raw_data_paths,
                )
            });
    let value = parsed.next()?;
    if parsed.next().is_some() {
        return None;
    }
    Some(value)
}

fn parse_information_register_child_payload_from_fields(
    fields: &[&str],
    child_header: &MetadataHeader,
    owner_name: &str,
    tag: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    preserve_raw_data_paths: bool,
) -> Option<(Vec<ConstantValueType>, MetadataChildProperties)> {
    let value_types = parse_information_register_child_value_types_from_fields(
        fields,
        child_header,
        tag,
        type_index,
    )?;
    let common_field = fields.get(1)?;
    let common_fields = split_1c_braced_fields(common_field, 0)?;
    let mut properties = parse_information_register_common_child_properties(
        &common_fields,
        "InformationRegister",
        owner_name,
        type_index,
        object_refs,
        form_refs,
        preserve_raw_data_paths,
    )?;

    match (fields.first()?.trim(), fields.len()) {
        ("7", 5) | ("4", 5) => {
            properties.indexing = information_register_indexing(fields.get(2)?);
            properties.full_text_search = information_register_full_text_search(fields.get(3)?);
            properties.data_history = information_register_data_history(fields.get(4)?);
        }
        ("8", 7) | ("5", 7) => {
            if fields.get(5)?.trim() != "0"
                || !information_register_new_child_tail_is_valid(fields.get(6)?)
            {
                return None;
            }
            properties.indexing = information_register_indexing(fields.get(2)?);
            properties.full_text_search = information_register_full_text_search(fields.get(3)?);
            properties.data_history = information_register_data_history(fields.get(4)?);
        }
        ("9", 8) => {
            properties.master = Some(information_register_bool(fields.get(2)?)?);
            properties.deny_incomplete_values = Some(information_register_bool(fields.get(3)?)?);
            properties.indexing = information_register_indexing(fields.get(4)?);
            properties.main_filter = Some(information_register_bool(fields.get(5)?)?);
            properties.full_text_search = information_register_full_text_search(fields.get(6)?);
            properties.data_history = information_register_data_history(fields.get(7)?);
            properties.type_reduction_mode = Some("TransformValues");
        }
        ("10", 9) => {
            properties.master = Some(information_register_bool(fields.get(2)?)?);
            properties.deny_incomplete_values = Some(information_register_bool(fields.get(3)?)?);
            properties.indexing = information_register_indexing(fields.get(4)?);
            properties.main_filter = Some(information_register_bool(fields.get(5)?)?);
            properties.full_text_search = information_register_full_text_search(fields.get(6)?);
            properties.data_history = information_register_data_history(fields.get(7)?);
            properties.type_reduction_mode = Some(match fields.get(8)?.trim() {
                "0" => "TransformValues",
                "1" => "DeleteData",
                _ => return None,
            });
        }
        _ => return None,
    }

    if properties.indexing.is_none()
        || properties.full_text_search.is_none()
        || properties.data_history.is_none()
    {
        return None;
    }
    Some((value_types, properties))
}

fn parse_information_register_child_value_types(
    text: &str,
    marker_start: usize,
    child_header: &MetadataHeader,
    tag: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    let mut parsed =
        metadata_object_field_candidates_around_header(text, marker_start, &child_header.uuid)
            .into_iter()
            .filter_map(|fields| {
                parse_information_register_child_value_types_from_fields(
                    &fields,
                    child_header,
                    tag,
                    type_index,
                )
            });
    let value = parsed.next()?;
    if parsed.next().is_some() {
        return None;
    }
    Some(value)
}

fn parse_information_register_child_value_types_from_fields(
    fields: &[&str],
    child_header: &MetadataHeader,
    tag: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    let (expected_tag, common_field) = match (fields.first()?.trim(), fields.len()) {
        ("7", 5) | ("8", 7) => ("Resource", fields.get(1)?),
        ("4", 5) | ("5", 7) => ("Attribute", fields.get(1)?),
        ("9", 8) | ("10", 9) => ("Dimension", fields.get(1)?),
        _ => return None,
    };
    if expected_tag != tag {
        return None;
    }

    let common_fields = split_1c_braced_fields(common_field, 0)?;
    if common_fields.len() != 23 || common_fields.first()?.trim() != "27" {
        return None;
    }
    let typed_header = split_1c_braced_fields(common_fields.get(1)?, 0)?;
    if typed_header.len() != 3 || typed_header.first()?.trim() != "2" {
        return None;
    }
    let header_fields = split_1c_braced_fields(typed_header.get(1)?, 0)?;
    // Same code27 short-wrapper omission as `register_common_child_header_
    // matches` just above and `parse_metadata_code27_payload_fields`
    // (`06249bd`) -- another hand reimplementation of the same
    // `{27,{2,header,{"Pattern",...}}}` shape, this time for
    // InformationRegister Resource/Attribute/Dimension value types.
    let header_has_trailing_default = match header_fields.len() {
        9 => true,
        8 => false,
        _ => return None,
    };
    if header_fields.first()?.trim()
        != (if header_has_trailing_default {
            "3"
        } else {
            "2"
        })
        || metadata_header_field_index(&header_fields, &child_header.uuid) != Some(1)
    {
        return None;
    }
    let parsed_header = parse_metadata_header_from_text(typed_header.get(1)?, &child_header.uuid)?;
    if parsed_header.uuid != child_header.uuid
        || parsed_header.name != child_header.name
        || parsed_header.synonyms != child_header.synonyms
        || parsed_header.comment != child_header.comment
    {
        return None;
    }

    Some(stable_partition_metadata_types(
        parse_information_register_type_pattern(typed_header.get(2)?, type_index)?,
    ))
}

fn parse_information_register_type_pattern(
    value: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.first()?.trim() != r#""Pattern""# {
        return None;
    }
    fields
        .iter()
        .skip(1)
        .map(|field| parse_information_register_type_pattern_element(field, type_index))
        .collect()
}

fn parse_information_register_type_pattern_element(
    value: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<ConstantValueType> {
    let fields = split_1c_braced_fields(value, 0)?;
    match (fields.first()?.trim(), fields.len()) {
        (r#""B""#, 1) => Some(ConstantValueType::Boolean),
        (r#""S""#, 1) => Some(ConstantValueType::String {
            length: None,
            // `format_metadata_types_xml` (mod.rs:~35717) already forces
            // "Variable" whenever `length` is `None`
            // (`length.map(|_| *allowed_length_flag).unwrap_or(1)`), so the
            // actual emitted XML for a length-less String pattern has
            // always been "Variable" — storing `0` here just desynced the
            // parsed struct from that proven output. Store `1` to match.
            allowed_length_flag: 1,
        }),
        (r#""S""#, 3) => {
            let allowed_length_flag = fields.get(2)?.trim().parse::<u8>().ok()?;
            if allowed_length_flag > 2 {
                return None;
            }
            Some(ConstantValueType::String {
                length: Some(fields.get(1)?.trim().parse().ok()?),
                allowed_length_flag,
            })
        }
        (r#""N""#, 1) => Some(ConstantValueType::Number {
            digits: 0,
            fraction_digits: 0,
            allowed_sign_flag: 0,
        }),
        (r#""N""#, 4) => {
            let allowed_sign_flag = fields.get(3)?.trim().parse::<u8>().ok()?;
            if allowed_sign_flag > 1 {
                return None;
            }
            Some(ConstantValueType::Number {
                digits: fields.get(1)?.trim().parse().ok()?,
                fraction_digits: fields.get(2)?.trim().parse().ok()?,
                allowed_sign_flag,
            })
        }
        (r#""D""#, 1) => Some(ConstantValueType::DateTime {
            date_fractions: "DateTime",
        }),
        (r#""D""#, 2) => Some(ConstantValueType::DateTime {
            date_fractions: match fields.get(1)?.trim() {
                r#""D""# => "Date",
                r#""T""# => "Time",
                _ => return None,
            },
        }),
        (r##""#""##, 2) => {
            let type_id = parse_uuid_field(fields.get(1)?.trim())?;
            let reference = type_index
                .get(&type_id)
                .cloned()
                .or_else(|| information_register_builtin_reference(&type_id).map(str::to_string))
                .or_else(|| builtin_type_reference(&type_id).map(str::to_string))?;
            if metadata_reference_is_type_set(&reference) {
                Some(ConstantValueType::ReferenceTypeSet { reference })
            } else {
                Some(ConstantValueType::Reference { reference })
            }
        }
        _ => None,
    }
}

fn information_register_builtin_reference(type_id: &str) -> Option<&'static str> {
    DCS_BUILTIN_REFERENCE_TYPE_SETS
        .iter()
        .find_map(|(candidate, reference)| (*candidate == type_id).then_some(*reference))
}

fn metadata_reference_is_type_set(reference: &str) -> bool {
    reference.starts_with("cfg:DefinedType.")
        || reference.starts_with("cfg:Characteristic.")
        || reference == "cfg:AnyIBRef"
        || (reference.starts_with("cfg:") && reference.ends_with("Ref") && !reference.contains('.'))
}

fn classify_metadata_reference_type_sets(
    value_types: Vec<ConstantValueType>,
) -> Vec<ConstantValueType> {
    value_types
        .into_iter()
        .map(|value_type| match value_type {
            ConstantValueType::Reference { reference }
                if metadata_reference_is_type_set(&reference) =>
            {
                ConstantValueType::ReferenceTypeSet { reference }
            }
            other => other,
        })
        .collect()
}

/// Moves every `TypeSet` leaf behind every ordinary `Type` leaf, keeping the
/// relative order inside each group.
///
/// This is the platform's own layout for a root metadata object's `<Type>`
/// block, not a form's. Forms have their own reader
/// (`form_body::normalize_form_type_pattern`); dropping this partition changes
/// exactly 15 of the 50 898 native files of 1C:Trade Management 11.5.27.75 -
/// six Catalogs, one ChartOfCharacteristicTypes and eight InformationRegisters
/// - and not one Form among them, so the two roles never shared this procedure.
fn stable_partition_metadata_types(value_types: Vec<ConstantValueType>) -> Vec<ConstantValueType> {
    let (mut ordinary, type_sets): (Vec<_>, Vec<_>) = value_types
        .into_iter()
        .partition(|value_type| !matches!(value_type, ConstantValueType::ReferenceTypeSet { .. }));
    ordinary.extend(type_sets);
    ordinary
}

fn parse_information_register_common_child_properties(
    fields: &[&str],
    owner_kind: &str,
    owner_name: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    preserve_raw_data_paths: bool,
) -> Option<MetadataChildProperties> {
    if fields.len() != 23 || fields.first()?.trim() != "27" {
        return None;
    }
    let min_value = parse_information_register_bound(fields.get(8)?)?;
    let max_value = parse_information_register_bound(fields.get(9)?)?;
    let link_by_type = parse_information_register_link_by_type(
        fields.get(15)?,
        owner_kind,
        owner_name,
        object_refs,
        preserve_raw_data_paths,
    )?;
    Some(MetadataChildProperties {
        password_mode: information_register_bool(fields.get(2)?)?,
        format: parse_information_register_localized_value(fields.get(3)?)?,
        edit_format: parse_information_register_localized_value(fields.get(18)?)?,
        tooltip: parse_information_register_localized_value(fields.get(4)?)?,
        mark_negatives: information_register_bool(fields.get(5)?)?,
        mask: parse_1c_quoted_string(fields.get(6)?.trim())?,
        multi_line: information_register_bool(fields.get(7)?)?,
        extended_edit: information_register_bool(fields.get(17)?)?,
        min_value,
        max_value,
        fill_from_filling_value: information_register_bool(fields.get(20)?)?,
        emit_fill_from_filling_value: true,
        fill_value: Some(parse_information_register_fill_value(
            fields.get(19)?,
            type_index,
            object_refs,
        )?),
        emit_fill_value: true,
        fill_checking: match fields.get(13)?.trim() {
            "0" => "DontCheck",
            "1" => "ShowError",
            _ => return None,
        },
        choice_folders_and_items: Some(match fields.get(10)?.trim() {
            "0" => "Items",
            "1" => "Folders",
            "2" => "FoldersAndItems",
            _ => return None,
        }),
        choice_parameter_links: Some(parse_information_register_choice_parameter_links(
            fields.get(14)?,
            owner_kind,
            owner_name,
            object_refs,
            preserve_raw_data_paths,
        )?),
        choice_parameters: Some(parse_information_register_choice_parameters(
            fields.get(16)?,
            type_index,
            object_refs,
        )?),
        // WMS5's `МодульWebОбмена_ERP25.cf` InformationRegister
        // `ШтрихкодыНоменклатуры`, resource `Номенклатура`: native emits
        // `<v8:Value xsi:type="xr:DesignTimeRef"/>` (self-closed) for each
        // empty entry of a `ChoiceParameters` `FixedArray`, matching
        // `parse_document_child_properties`'s already-proven `true` -- not
        // the open/close form. Neither retained native-evidence corpus
        // (БСП demo, УТ) has an InformationRegister with an empty
        // DesignTimeRef inside a FixedArray choice parameter at all (zero
        // matches either way), so this was never evidenced either way
        // before; it just inherited the open/close default.
        self_close_empty_choice_parameter_refs: true,
        quick_choice: Some(match fields.get(12)?.trim() {
            "0" => "DontUse",
            "1" => "Use",
            "2" => "Auto",
            _ => return None,
        }),
        create_on_input: Some(match fields.get(21)?.trim() {
            "0" => "Auto",
            "1" => "DontUse",
            "2" => "Use",
            _ => return None,
        }),
        choice_form: Some(parse_information_register_choice_form(
            fields.get(11)?,
            type_index,
            object_refs,
            form_refs,
        )?),
        link_by_type_empty: link_by_type.is_none(),
        link_by_type,
        choice_history_on_input: Some(match fields.get(22)?.trim() {
            "0" => "Auto",
            "1" => "DontUse",
            _ => return None,
        }),
        master: None,
        main_filter: None,
        balance: None,
        accounting_flag: None,
        ext_dimension_accounting_flag: None,
        deny_incomplete_values: None,
        use_mode: None,
        indexing: None,
        full_text_search: None,
        data_history: None,
        type_reduction_mode: None,
        update_data_history_immediately_after_write: None,
        execute_after_write_data_history_version_processing: None,
    })
}

fn information_register_bool(value: &str) -> Option<bool> {
    match value.trim() {
        "0" => Some(false),
        "1" => Some(true),
        _ => None,
    }
}

fn information_register_indexing(value: &str) -> Option<&'static str> {
    metadata_attribute_indexing_xml(value.trim())
}

fn information_register_full_text_search(value: &str) -> Option<&'static str> {
    register_child_full_text_search_xml(value.trim())
}

fn information_register_data_history(value: &str) -> Option<&'static str> {
    metadata_data_history_xml(value.trim())
}

fn information_register_new_child_tail_is_valid(value: &str) -> bool {
    let Some(fields) = split_1c_braced_fields(value, 0) else {
        return false;
    };
    fields.len() == 2
        && fields.first().map(|field| field.trim()) == Some("1")
        && fields
            .get(1)
            .and_then(|field| parse_uuid_field(field.trim()))
            .is_some_and(|uuid| information_register_uuid_is_zero(&uuid))
}

fn parse_information_register_localized_value(value: &str) -> Option<Vec<(String, String)>> {
    let fields = split_1c_braced_fields(value, 0)?;
    let count = fields.first()?.trim().parse::<usize>().ok()?;
    let expected_len = count.checked_mul(2)?.checked_add(1)?;
    if fields.len() != expected_len {
        return None;
    }
    let mut result = Vec::with_capacity(count);
    for pair in fields[1..].chunks_exact(2) {
        result.push((
            parse_1c_quoted_string(pair[0].trim())?,
            parse_1c_quoted_string(pair[1].trim())?,
        ));
    }
    Some(result)
}

fn parse_information_register_bound(value: &str) -> Option<Option<String>> {
    let fields = split_1c_braced_fields(value, 0)?;
    match fields.first()?.trim() {
        r#""U""# if fields.len() == 1 => Some(None),
        r#""S""# if fields.len() == 2 => Some(Some(parse_1c_quoted_string(fields.get(1)?.trim())?)),
        _ => None,
    }
}

fn parse_information_register_fill_value(
    value: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<MetadataChildFillValue> {
    let fields = split_1c_braced_fields(value, 0)?;
    match fields.first()?.trim() {
        r#""U""# if fields.len() == 1 => Some(MetadataChildFillValue::Nil),
        r#""S""# if fields.len() == 2 => Some(MetadataChildFillValue::String(
            parse_1c_quoted_string(fields.get(1)?.trim())?,
        )),
        r#""N""# if fields.len() == 2 => {
            let value = fields.get(1)?.trim();
            information_register_decimal_is_valid(value)
                .then(|| MetadataChildFillValue::Decimal(value.to_string()))
        }
        r#""D""# if fields.len() == 2 => {
            format_1c_date_time(fields.get(1)?.trim()).map(MetadataChildFillValue::DateTime)
        }
        r#""B""# if fields.len() == 2 => {
            information_register_bool(fields.get(1)?).map(MetadataChildFillValue::Boolean)
        }
        r##""#""## if fields.len() == 3 => {
            parse_information_register_design_time_ref(value, type_index, object_refs)
                .map(MetadataChildFillValue::DesignTimeRef)
        }
        _ => None,
    }
}

fn information_register_decimal_is_valid(value: &str) -> bool {
    let value = value.strip_prefix('-').unwrap_or(value);
    let mut parts = value.split('.');
    let Some(integer) = parts.next() else {
        return false;
    };
    if integer.is_empty() || !integer.chars().all(|ch| ch.is_ascii_digit()) {
        return false;
    }
    match (parts.next(), parts.next()) {
        (None, None) => true,
        (Some(fraction), None) => {
            !fraction.is_empty() && fraction.chars().all(|ch| ch.is_ascii_digit())
        }
        _ => false,
    }
}

fn parse_information_register_choice_form(
    value: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<MetadataChoiceForm> {
    if let Some(uuid) = parse_uuid_field(value.trim()) {
        if information_register_uuid_is_zero(&uuid) {
            return Some(MetadataChoiceForm::Empty);
        }
        return information_register_form_reference(&uuid, form_refs)
            .map(MetadataChoiceForm::Reference);
    }
    let (owner_uuid, form_uuid) = parse_information_register_design_time_ref_ids(value)?;
    let owner_is_zero = information_register_uuid_is_zero(&owner_uuid);
    let form_is_zero = information_register_uuid_is_zero(&form_uuid);
    match (owner_is_zero, form_is_zero) {
        (true, true) => Some(MetadataChoiceForm::Empty),
        (false, false) => {
            let owner = information_register_design_time_owner_reference(
                &owner_uuid,
                type_index,
                object_refs,
            )?;
            let reference = information_register_form_reference(&form_uuid, form_refs)?;
            let expected_prefix = format!("{owner}.Form.");
            reference
                .strip_prefix(&expected_prefix)
                .is_some_and(|name| !name.is_empty() && !name.contains('.'))
                .then_some(MetadataChoiceForm::Reference(reference))
        }
        _ => None,
    }
}

fn information_register_form_reference(
    uuid: &str,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<String> {
    let form = form_refs.get(uuid)?;
    if !matches!(form.kind, "Form" | "CommonForm") {
        return None;
    }
    let reference = form_source_reference_name(form)?;
    information_register_form_reference_is_valid(&reference).then_some(reference)
}

fn information_register_form_reference_is_valid(reference: &str) -> bool {
    if let Some(name) = reference.strip_prefix("CommonForm.") {
        return !name.is_empty() && !name.contains('.');
    }
    let Some((owner, form)) = reference.split_once(".Form.") else {
        return false;
    };
    let Some((kind, owner_name)) = owner.split_once('.') else {
        return false;
    };
    metadata_kind_can_own_forms(kind)
        && !owner_name.is_empty()
        && !owner_name.contains('.')
        && !form.is_empty()
        && !form.contains('.')
}

fn parse_information_register_design_time_ref(
    value: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let (owner_uuid, value_uuid) = parse_information_register_design_time_ref_ids(value)?;
    let owner_is_zero = information_register_uuid_is_zero(&owner_uuid);
    let value_is_zero = information_register_uuid_is_zero(&value_uuid);
    match (owner_is_zero, value_is_zero) {
        (true, true) => Some(String::new()),
        (false, true) => {
            let Some(owner) = information_register_design_time_owner_reference(
                &owner_uuid,
                type_index,
                object_refs,
            ) else {
                return information_register_dangling_design_time_ref(
                    &owner_uuid,
                    &value_uuid,
                    type_index,
                    object_refs,
                );
            };
            information_register_owner_reference_is_valid(&owner)
                .then(|| format!("{owner}.EmptyRef"))
        }
        (false, false) => {
            let Some(owner) = information_register_design_time_owner_reference(
                &owner_uuid,
                type_index,
                object_refs,
            ) else {
                return information_register_dangling_design_time_ref(
                    &owner_uuid,
                    &value_uuid,
                    type_index,
                    object_refs,
                );
            };
            let qualified_key = metadata_owner_value_reference_key(&owner, &value_uuid);
            let value = object_refs
                .get(&qualified_key)
                .or_else(|| object_refs.get(&value_uuid))?
                .clone();
            information_register_reference_belongs_to_owner(&owner, &value).then_some(value)
        }
        (true, false) => None,
    }
}

/// A design-time reference whose owner is unknown to every index of the
/// configuration is written by the platform as the raw `owner.value` pair,
/// the same way the form choice-list reader already reproduces it. The rule
/// is deliberately narrow: an owner that any index knows is never
/// downgraded to a raw pair, so an incomplete resolution still refuses.
fn information_register_dangling_design_time_ref(
    owner_uuid: &str,
    value_uuid: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let owner_known = object_refs.contains_key(owner_uuid) || type_index.contains_key(owner_uuid);
    (!owner_known).then(|| format!("{owner_uuid}.{value_uuid}"))
}

fn metadata_owner_value_reference_key(owner_reference: &str, value_uuid: &str) -> String {
    format!("owner-value:{owner_reference}:{value_uuid}")
}

fn metadata_owner_value_reference_key_parts(key: &str) -> Option<(&str, &str)> {
    let (owner_reference, value_uuid) = key.strip_prefix("owner-value:")?.rsplit_once(':')?;
    is_uuid_text(value_uuid).then_some((owner_reference, value_uuid))
}

fn metadata_owner_value_reference_key_is_valid(key: &str) -> bool {
    metadata_owner_value_reference_key_parts(key).is_some_and(|(owner_reference, _)| {
        information_register_owner_reference_is_valid(owner_reference)
    })
}

fn extend_metadata_owner_value_references(
    target: &mut BTreeMap<String, String>,
    source: &BTreeMap<String, String>,
) -> Result<()> {
    for (key, reference) in source
        .iter()
        .filter(|(key, _)| metadata_owner_value_reference_key_is_valid(key))
    {
        if let Some(previous) = target.get(key)
            && previous != reference
        {
            bail!(
                "owner-qualified metadata value {key} resolves to both {previous} and {reference}"
            );
        }
        target.insert(key.clone(), reference.clone());
    }
    Ok(())
}

fn information_register_owner_reference_is_valid(owner: &str) -> bool {
    let mut owner_parts = owner.split('.');
    let (Some(owner_kind), Some(owner_name), None) =
        (owner_parts.next(), owner_parts.next(), owner_parts.next())
    else {
        return false;
    };
    if owner_kind.is_empty() || owner_name.is_empty() {
        return false;
    }
    true
}

fn information_register_reference_belongs_to_owner(owner: &str, value: &str) -> bool {
    if !information_register_owner_reference_is_valid(owner) {
        return false;
    }
    let mut owner_parts = owner.split('.');
    let owner_kind = owner_parts.next().expect("validated owner kind");
    let owner_name = owner_parts.next().expect("validated owner name");
    let value_parts = value.split('.').collect::<Vec<_>>();
    match value_parts.as_slice() {
        [kind, name, item] => {
            owner_kind != "Enum" && *kind == owner_kind && *name == owner_name && !item.is_empty()
        }
        ["Enum", name, "EnumValue", item] => {
            owner_kind == "Enum" && *name == owner_name && !item.is_empty()
        }
        _ => false,
    }
}

fn parse_information_register_design_time_ref_ids(value: &str) -> Option<(String, String)> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.len() != 3
        || fields.first()?.trim() != r##""#""##
        || !fields
            .get(1)?
            .trim()
            .eq_ignore_ascii_case(DESIGN_TIME_REF_TYPE_UUID)
    {
        return None;
    }
    let reference = split_1c_braced_fields(fields.get(2)?, 0)?;
    if reference.len() != 3 || reference.first()?.trim() != "0" {
        return None;
    }
    let owner_uuid = parse_uuid_field(reference.get(1)?.trim())?;
    let value_uuid = parse_uuid_field(reference.get(2)?.trim())?;
    Some((owner_uuid, value_uuid))
}

fn information_register_design_time_owner_reference(
    owner_uuid: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    if let Some(reference) = object_refs.get(owner_uuid) {
        return Some(reference.clone());
    }
    parse_generated_metadata_reference_owner(type_index.get(owner_uuid)?)
        .map(|owner| owner.owner_reference())
}

fn information_register_uuid_is_zero(value: &str) -> bool {
    value == "00000000-0000-0000-0000-000000000000"
}

fn parse_information_register_choice_parameter_links(
    value: &str,
    owner_kind: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
    preserve_raw_data_paths: bool,
) -> Option<Vec<MetadataChoiceParameterLink>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.first()?.trim() != "5006" {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    let remaining = fields.len().checked_sub(2)?;
    if remaining < count.checked_mul(4)? {
        return None;
    }
    let mut index = 2usize;
    let mut result = Vec::with_capacity(count);
    for _ in 0..count {
        let name = parse_1c_quoted_string(fields.get(index)?.trim())?;
        let path_count = fields
            .get(index.checked_add(1)?)?
            .trim()
            .parse::<usize>()
            .ok()?;
        if path_count == 0 {
            return None;
        }
        index = index.checked_add(2)?;
        let path_end = index.checked_add(path_count)?;
        let path = parse_information_register_data_path(
            fields.get(index..path_end)?,
            owner_kind,
            owner_name,
            object_refs,
            preserve_raw_data_paths,
        )?;
        index = path_end;
        let value_change = match fields.get(index)?.trim() {
            "0" => "Clear",
            "1" => "DontChange",
            _ => return None,
        };
        index = index.checked_add(1)?;
        result.push(MetadataChoiceParameterLink {
            name,
            data_path: path,
            value_change,
        });
    }
    (index == fields.len()).then_some(result)
}

fn parse_information_register_link_by_type(
    value: &str,
    owner_kind: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
    preserve_raw_data_paths: bool,
) -> Option<Option<MetadataChildLinkByType>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.first()?.trim() != "3" {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    let expected_len = count.checked_add(3)?;
    if fields.len() != expected_len {
        return None;
    }
    let link_item = fields.last()?.trim().parse::<u32>().ok()?;
    if link_item > 3 {
        return None;
    }
    if count == 0 {
        return (link_item == 0).then_some(None);
    }
    let path_end = 2usize.checked_add(count)?;
    Some(Some(MetadataChildLinkByType {
        data_path: parse_information_register_data_path(
            fields.get(2..path_end)?,
            owner_kind,
            owner_name,
            object_refs,
            preserve_raw_data_paths,
        )?,
        link_item,
    }))
}

fn parse_information_register_data_path(
    fields: &[&str],
    owner_kind: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
    preserve_raw_data_paths: bool,
) -> Option<String> {
    fields
        .iter()
        .map(|field| {
            let segment = split_1c_braced_fields(field, 0)?;
            match (segment.first()?.trim(), segment.len()) {
                ("0", 1) => Some("0".to_string()),
                ("0", 2) => {
                    let uuid = parse_uuid_field(segment.get(1)?.trim())?;
                    if preserve_raw_data_paths {
                        Some(format!("0:{uuid}"))
                    } else {
                        Some(
                            object_refs
                                .get(&uuid)
                                .cloned()
                                .unwrap_or_else(|| format!("0:{uuid}")),
                        )
                    }
                }
                ("-2", 1) if owner_kind == "InformationRegister" => Some(format!(
                    "InformationRegister.{owner_name}.StandardAttribute.Period"
                )),
                ("-3", 1) if owner_kind == "InformationRegister" => Some(format!(
                    "InformationRegister.{owner_name}.StandardAttribute.Recorder"
                )),
                _ => None,
            }
        })
        .collect::<Option<Vec<_>>>()
        .map(|segments| segments.join("/"))
}

fn parse_information_register_choice_parameters(
    value: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<Vec<MetadataChoiceParameter>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.first()?.trim() != "0" {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    let expected_len = count.checked_mul(2)?.checked_add(2)?;
    if fields.len() != expected_len {
        return None;
    }
    let mut result = Vec::with_capacity(count);
    for pair in fields[2..].chunks_exact(2) {
        result.push(MetadataChoiceParameter {
            name: parse_1c_quoted_string(pair[0].trim())?,
            value: parse_information_register_choice_parameter_value(
                pair[1],
                type_index,
                object_refs,
            )?,
        });
    }
    Some(result)
}

fn parse_information_register_choice_parameter_value(
    value: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
) -> Option<MetadataChoiceParameterValue> {
    parse_metadata_choice_parameter_typed_value(value, type_index, object_refs, 0)
}

fn parse_metadata_choice_parameter_typed_value(
    value: &str,
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    depth: usize,
) -> Option<MetadataChoiceParameterValue> {
    if depth > MAX_METADATA_CHOICE_PARAMETER_VALUE_DEPTH {
        return None;
    }
    let fields = split_1c_braced_fields(value, 0)?;
    match fields.first()?.trim() {
        r#""U""# if fields.len() == 1 => Some(MetadataChoiceParameterValue::Nil),
        r#""S""# if fields.len() == 2 => Some(MetadataChoiceParameterValue::String(
            parse_1c_quoted_string(fields.get(1)?.trim())?,
        )),
        r#""B""# if fields.len() == 2 => {
            information_register_bool(fields.get(1)?).map(MetadataChoiceParameterValue::Boolean)
        }
        r#""N""# if fields.len() == 2 => {
            let value = fields.get(1)?.trim();
            information_register_decimal_is_valid(value)
                .then(|| MetadataChoiceParameterValue::Decimal(value.to_string()))
        }
        r#""D""# if fields.len() == 2 => {
            format_1c_date_time(fields.get(1)?.trim()).map(MetadataChoiceParameterValue::DateTime)
        }
        r##""#""## if fields.len() == 3 => {
            let type_id = fields.get(1)?.trim();
            if type_id.eq_ignore_ascii_case(DESIGN_TIME_REF_TYPE_UUID) {
                return parse_information_register_design_time_ref(value, type_index, object_refs)
                    .map(MetadataChoiceParameterValue::DesignTimeRef);
            }
            if !type_id.eq_ignore_ascii_case(FIXED_ARRAY_TYPE_UUID) {
                return None;
            }
            let nested = split_1c_braced_fields(fields.get(2)?, 0)?;
            let count = nested.first()?.trim().parse::<usize>().ok()?;
            let expected_len = count.checked_add(1)?;
            if nested.len() != expected_len {
                return None;
            }
            nested
                .iter()
                .skip(1)
                .map(|value| {
                    parse_metadata_choice_parameter_typed_value(
                        value,
                        type_index,
                        object_refs,
                        depth.checked_add(1)?,
                    )
                })
                .collect::<Option<Vec<_>>>()
                .map(MetadataChoiceParameterValue::FixedArray)
        }
        _ => None,
    }
}

fn parse_catalog_child_properties(
    owner_name: &str,
    text: &str,
    marker_start: usize,
    child_uuid: &str,
    expected_wrapper_code: u32,
    value_types: &[ConstantValueType],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<MetadataChildProperties> {
    let candidates = metadata_object_field_candidates_around_header(text, marker_start, child_uuid);
    let mut layouts = candidates
        .iter()
        .filter_map(|fields| parse_catalog_attribute_wrapper_fields(fields, Some(child_uuid)))
        .collect::<Vec<_>>();
    if layouts.len() != 1 {
        return None;
    }
    let (payload, wrapper, wrapper_code, _) = layouts.pop()?;
    let nested = wrapper_code == 8;
    if wrapper_code != expected_wrapper_code
        || candidates
            .iter()
            .filter(|fields| {
                catalog_attribute_collection_is_closed(fields, child_uuid, wrapper_code)
            })
            .count()
            != 1
    {
        return None;
    }

    let password_mode = information_register_bool(payload.get(2)?)?;
    let format = parse_metadata_child_localized_value(payload.get(3)?)?;
    let tooltip = parse_metadata_child_localized_value(payload.get(4)?)?;
    let mark_negatives = information_register_bool(payload.get(5)?)?;
    let mask = parse_1c_quoted_string(payload.get(6)?.trim())?;
    let multi_line = information_register_bool(payload.get(7)?)?;
    let min_value = parse_information_register_bound(payload.get(8)?)?;
    let max_value = parse_information_register_bound(payload.get(9)?)?;
    let choice_folders_and_items = catalog_choice_folders_and_items_xml(payload.get(10)?.trim())?;
    let choice_form = parse_catalog_child_choice_form(payload.get(11)?, value_types, form_refs)?;
    let quick_choice = catalog_quick_choice_xml(payload.get(12)?.trim())?;
    let fill_checking = match payload.get(13)?.trim() {
        "0" => "DontCheck",
        "1" => "ShowError",
        _ => return None,
    };
    let choice_parameter_links =
        parse_catalog_choice_parameter_links(payload.get(14)?, owner_name, nested, object_refs)?;
    let (link_by_type_empty, link_by_type) =
        parse_catalog_link_by_type(payload.get(15)?, owner_name, object_refs)?;
    let choice_parameters = parse_information_register_choice_parameters(
        payload.get(16)?,
        type_index,
        metadata_object_refs,
    )?;
    let extended_edit = information_register_bool(payload.get(17)?)?;
    let edit_format = parse_metadata_child_localized_value(payload.get(18)?)?;
    let fill_value =
        parse_information_register_fill_value(payload.get(19)?, type_index, metadata_object_refs)?;
    let fill_from_filling_value = information_register_bool(payload.get(20)?)?;
    if nested
        && (fill_from_filling_value
            || !matches!(&fill_value, MetadataChildFillValue::String(value) if value.is_empty()))
    {
        return None;
    }
    let create_on_input = catalog_create_on_input_xml(payload.get(21)?.trim())?;
    let choice_history_on_input = catalog_choice_history_on_input_xml(payload.get(22)?.trim())?;

    let indexing = metadata_attribute_indexing_xml(wrapper.get(2)?.trim())?;
    let (use_mode, full_text_search_index, data_history_index) = match wrapper_code {
        5 | 6 => (
            Some(catalog_attribute_use_mode_xml(wrapper.get(3)?.trim())?),
            4,
            5,
        ),
        8 => (None, 3, 4),
        _ => return None,
    };
    let full_text_search =
        catalog_attribute_full_text_search_xml(wrapper.get(full_text_search_index)?.trim())?;
    let data_history = metadata_data_history_xml(wrapper.get(data_history_index)?.trim())?;

    Some(MetadataChildProperties {
        password_mode,
        format,
        edit_format,
        tooltip,
        mark_negatives,
        mask,
        multi_line,
        extended_edit,
        min_value,
        max_value,
        fill_from_filling_value,
        emit_fill_from_filling_value: !nested,
        fill_value: Some(fill_value),
        emit_fill_value: !nested,
        fill_checking,
        choice_folders_and_items: Some(choice_folders_and_items),
        choice_parameter_links: Some(choice_parameter_links),
        choice_parameters: Some(choice_parameters),
        self_close_empty_choice_parameter_refs: false,
        quick_choice: Some(quick_choice),
        create_on_input: Some(create_on_input),
        choice_form: Some(choice_form),
        link_by_type_empty,
        link_by_type,
        choice_history_on_input: Some(choice_history_on_input),
        master: None,
        main_filter: None,
        balance: None,
        accounting_flag: None,
        ext_dimension_accounting_flag: None,
        deny_incomplete_values: None,
        use_mode,
        indexing: Some(indexing),
        full_text_search: Some(full_text_search),
        data_history: Some(data_history),
        type_reduction_mode: None,
        update_data_history_immediately_after_write: None,
        execute_after_write_data_history_version_processing: None,
    })
}

fn parse_catalog_attribute_wrapper_fields<'a>(
    fields: &[&'a str],
    expected_child_uuid: Option<&str>,
) -> Option<(Vec<&'a str>, Vec<&'a str>, u32, String)> {
    let wrapper_code = fields.first()?.trim().parse::<u32>().ok()?;
    let expected_len = match wrapper_code {
        5 => 6,
        6 => 8,
        8 => 5,
        _ => return None,
    };
    if fields.len() != expected_len {
        return None;
    }
    let (payload, child_uuid) = parse_metadata_code27_payload(fields.get(1)?.trim())?;
    if expected_child_uuid.is_some_and(|expected| expected != child_uuid) {
        return None;
    }
    // `parse_metadata_code27_payload` only checks the `"Pattern"` marker
    // itself; a real Catalog attribute always declares at least one value
    // type, so an empty pattern (`{"Pattern"}`) is a malformed wrapper, not
    // an attribute with no type.
    let detail = split_1c_braced_fields(payload.get(1)?.trim(), 0)?;
    let pattern = split_1c_braced_fields(detail.get(2)?.trim(), 0)?;
    if pattern.len() < 2 {
        return None;
    }
    metadata_attribute_indexing_xml(fields.get(2)?.trim())?;
    match wrapper_code {
        5 => {
            catalog_attribute_use_mode_xml(fields.get(3)?.trim())?;
            catalog_attribute_full_text_search_xml(fields.get(4)?.trim())?;
            metadata_data_history_xml(fields.get(5)?.trim())?;
        }
        6 => {
            catalog_attribute_use_mode_xml(fields.get(3)?.trim())?;
            catalog_attribute_full_text_search_xml(fields.get(4)?.trim())?;
            metadata_data_history_xml(fields.get(5)?.trim())?;
            if fields.get(6)?.trim() != "0" || !metadata_reserved_wrapper_tail(fields.get(7)?) {
                return None;
            }
        }
        8 => {
            catalog_attribute_full_text_search_xml(fields.get(3)?.trim())?;
            metadata_data_history_xml(fields.get(4)?.trim())?;
        }
        _ => return None,
    }
    Some((payload, fields.to_vec(), wrapper_code, child_uuid))
}

fn parse_metadata_code27_payload(field: &str) -> Option<(Vec<&str>, String)> {
    let payload = split_1c_braced_fields(field, 0)?;
    parse_metadata_code27_payload_fields(payload)
}

fn parse_metadata_code27_payload_fields(payload: Vec<&str>) -> Option<(Vec<&str>, String)> {
    if payload.len() != 23 || payload.first()?.trim() != "27" {
        return None;
    }
    let detail = split_1c_braced_fields(payload.get(1)?.trim(), 0)?;
    if detail.len() != 3 || detail.first()?.trim() != "2" {
        return None;
    }
    let header = split_1c_braced_fields(detail.get(1)?.trim(), 0)?;
    // Same short-wrapper omission `parse_information_register_owner_header`
    // documents (`0575505`): the platform drops the trailing default `0` (and
    // the wrapper's own leading count from `3` to `2`) whenever this
    // attribute leaves Synonym/Comment at default. Confirmed on real ERP УХ
    // 3.2.12.6 data (`Catalogs/ВариантыЗаполненияШаблонов`, uuid
    // `996f1881-4ee2-4c39-bc39-e61dd7f42502`: a direct attribute with an
    // 8-member, `"2"`-discriminator header here, no counterpart to the
    // hardcoded `header.len() != 9` check this replaces). This wrapper shape
    // is shared by every `code27` attribute-type-declaration payload
    // (`Catalog`/`Document`/`DataProcessor`/`Report`/tabular-section
    // attributes and more, via this function's several call sites), not
    // Catalog direct attributes alone.
    let header_has_trailing_default = match header.len() {
        9 => true,
        8 => false,
        _ => return None,
    };
    if header.first()?.trim()
        != (if header_has_trailing_default {
            "3"
        } else {
            "2"
        })
    {
        return None;
    }
    let identity = split_1c_braced_fields(header.get(1)?.trim(), 0)?;
    if identity.len() != 3 || identity[0].trim() != "1" || identity[1].trim() != "0" {
        return None;
    }
    let child_uuid = parse_uuid_field(identity[2].trim())?;
    let parsed_header = parse_metadata_header_from_text(detail.get(1)?, &child_uuid)?;
    if parsed_header.uuid != child_uuid {
        return None;
    }
    let pattern = split_1c_braced_fields(detail.get(2)?.trim(), 0)?;
    if pattern.first()?.trim() != r#""Pattern""# {
        return None;
    }
    Some((payload, child_uuid))
}

fn metadata_reserved_wrapper_tail(field: &str) -> bool {
    let Some(fields) = split_1c_braced_fields(field.trim(), 0) else {
        return false;
    };
    fields.len() == 2
        && fields[0].trim() == "1"
        && fields[1].trim() == "00000000-0000-0000-0000-000000000000"
}

fn catalog_attribute_collection_is_closed(
    fields: &[&str],
    child_uuid: &str,
    expected_wrapper_code: u32,
) -> bool {
    let expected_marker = if expected_wrapper_code == 8 {
        CATALOG_TABULAR_ATTRIBUTE_GROUP_UUID
    } else {
        CATALOG_ATTRIBUTE_GROUP_UUID
    };
    if fields.len() < 3
        || !parse_uuid_field(fields[0].trim())
            .is_some_and(|marker| marker.eq_ignore_ascii_case(expected_marker))
    {
        return false;
    }
    let Some(count) = fields[1].trim().parse::<usize>().ok() else {
        return false;
    };
    if count == 0 || count.checked_add(2) != Some(fields.len()) {
        return false;
    }
    let mut child_occurrences = 0usize;
    for item_field in fields.iter().skip(2) {
        let Some(item) = split_1c_braced_fields(item_field.trim(), 0) else {
            return false;
        };
        if item.len() != 2 || item[1].trim() != "0" {
            return false;
        }
        let Some(wrapper) = split_1c_braced_fields(item[0].trim(), 0) else {
            return false;
        };
        let Some((_, _, wrapper_code, item_child_uuid)) =
            parse_catalog_attribute_wrapper_fields(&wrapper, None)
        else {
            return false;
        };
        if wrapper_code != expected_wrapper_code {
            return false;
        }
        if item_child_uuid == child_uuid {
            child_occurrences += 1;
        }
    }
    child_occurrences == 1
}

struct DocumentDataPathOwnerProof {
    entries: BTreeMap<String, DocumentDataPathOwnerEntry>,
    ambiguous: BTreeSet<String>,
}

struct DocumentDataPathOwnerEntry {
    reference: String,
    role: DocumentDataPathOwnerRole,
}

#[derive(Eq, PartialEq)]
enum DocumentDataPathOwnerRole {
    DirectAttribute,
    TabularSection,
    TabularAttribute { parent_uuid: String },
}

fn build_document_data_path_owner_proof(
    owner_name: &str,
    text: &str,
    owner_uuid: &str,
) -> DocumentDataPathOwnerProof {
    let mut entries = BTreeMap::<String, DocumentDataPathOwnerEntry>::new();
    let mut ambiguous = BTreeSet::<String>::new();
    for (child, marker_start) in nested_headers_with_offsets_from_text(text, owner_uuid, |_| true) {
        let Some((tag, parent)) = attribute_tabular_section_child_object_tag(
            "Document",
            owner_name,
            owner_uuid,
            text,
            marker_start,
            &child,
        ) else {
            continue;
        };
        let (reference, role) = match (tag, parent) {
            ("Attribute", None) => (
                format!("Document.{owner_name}.Attribute.{}", child.name),
                DocumentDataPathOwnerRole::DirectAttribute,
            ),
            ("Attribute", Some(parent)) => (
                format!(
                    "Document.{owner_name}.TabularSection.{}.Attribute.{}",
                    parent.name, child.name
                ),
                DocumentDataPathOwnerRole::TabularAttribute {
                    parent_uuid: parent.uuid,
                },
            ),
            ("TabularSection", None) => (
                format!("Document.{owner_name}.TabularSection.{}", child.name),
                DocumentDataPathOwnerRole::TabularSection,
            ),
            _ => continue,
        };
        if ambiguous.contains(&child.uuid) || entries.contains_key(&child.uuid) {
            entries.remove(&child.uuid);
            ambiguous.insert(child.uuid);
            continue;
        }
        entries.insert(child.uuid, DocumentDataPathOwnerEntry { reference, role });
    }
    DocumentDataPathOwnerProof { entries, ambiguous }
}

fn parse_document_child_properties(
    owner_name: &str,
    text: &str,
    marker_start: usize,
    child_uuid: &str,
    expected_nested: bool,
    value_types: &[ConstantValueType],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    metadata_object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
    data_path_owner_proof: &DocumentDataPathOwnerProof,
) -> Option<MetadataChildProperties> {
    let candidates = metadata_object_field_candidates_around_header(text, marker_start, child_uuid);
    let mut layouts = candidates
        .iter()
        .filter_map(|fields| parse_document_attribute_wrapper_fields(fields, Some(child_uuid)))
        .collect::<Vec<_>>();
    if layouts.len() != 1 {
        return None;
    }
    let (payload, wrapper, wrapper_code, _) = layouts.pop()?;
    let nested = wrapper_code == 8;
    if nested != expected_nested
        || candidates
            .iter()
            .filter(|fields| {
                document_attribute_collection_is_closed(fields, child_uuid, wrapper_code)
            })
            .count()
            != 1
    {
        return None;
    }

    let password_mode = information_register_bool(payload.get(2)?)?;
    let format = parse_metadata_child_localized_value(payload.get(3)?)?;
    let tooltip = parse_metadata_child_localized_value(payload.get(4)?)?;
    let mark_negatives = information_register_bool(payload.get(5)?)?;
    let mask = parse_1c_quoted_string(payload.get(6)?.trim())?;
    let multi_line = information_register_bool(payload.get(7)?)?;
    let min_value = parse_information_register_bound(payload.get(8)?)?;
    let max_value = parse_information_register_bound(payload.get(9)?)?;
    let choice_folders_and_items = catalog_choice_folders_and_items_xml(payload.get(10)?.trim())?;
    let choice_form = parse_document_child_choice_form(payload.get(11)?, value_types, form_refs)?;
    let quick_choice = catalog_quick_choice_xml(payload.get(12)?.trim())?;
    let fill_checking = match payload.get(13)?.trim() {
        "0" => "DontCheck",
        "1" => "ShowError",
        _ => return None,
    };
    let choice_parameter_links = parse_document_choice_parameter_links(
        payload.get(14)?,
        owner_name,
        nested,
        object_refs,
        data_path_owner_proof,
    )?;
    let (link_by_type_empty, link_by_type) = parse_document_link_by_type(
        payload.get(15)?,
        owner_name,
        object_refs,
        data_path_owner_proof,
    )?;
    let choice_parameters = parse_information_register_choice_parameters(
        payload.get(16)?,
        type_index,
        metadata_object_refs,
    )?;
    let extended_edit = information_register_bool(payload.get(17)?)?;
    let edit_format = parse_metadata_child_localized_value(payload.get(18)?)?;
    let fill_value = parse_document_fill_value(
        payload.get(19)?,
        value_types,
        type_index,
        metadata_object_refs,
        form_refs,
    )?;
    let fill_from_filling_value = information_register_bool(payload.get(20)?)?;
    if nested
        && (fill_from_filling_value
            || !matches!(&fill_value, MetadataChildFillValue::String(value) if value.is_empty()))
    {
        return None;
    }
    let create_on_input = catalog_create_on_input_xml(payload.get(21)?.trim())?;
    let choice_history_on_input = catalog_choice_history_on_input_xml(payload.get(22)?.trim())?;

    let indexing = metadata_attribute_indexing_xml(wrapper.get(2)?.trim())?;
    let full_text_search = register_child_full_text_search_xml(wrapper.get(3)?.trim())?;
    let data_history = metadata_data_history_xml(wrapper.get(4)?.trim())?;

    Some(MetadataChildProperties {
        password_mode,
        format,
        edit_format,
        tooltip,
        mark_negatives,
        mask,
        multi_line,
        extended_edit,
        min_value,
        max_value,
        fill_from_filling_value,
        emit_fill_from_filling_value: !nested,
        fill_value: Some(fill_value),
        emit_fill_value: !nested,
        fill_checking,
        choice_folders_and_items: Some(choice_folders_and_items),
        choice_parameter_links: Some(choice_parameter_links),
        choice_parameters: Some(choice_parameters),
        self_close_empty_choice_parameter_refs: true,
        quick_choice: Some(quick_choice),
        create_on_input: Some(create_on_input),
        choice_form: Some(choice_form),
        link_by_type_empty,
        link_by_type,
        choice_history_on_input: Some(choice_history_on_input),
        master: None,
        main_filter: None,
        balance: None,
        accounting_flag: None,
        ext_dimension_accounting_flag: None,
        deny_incomplete_values: None,
        use_mode: None,
        indexing: Some(indexing),
        full_text_search: Some(full_text_search),
        data_history: Some(data_history),
        type_reduction_mode: None,
        update_data_history_immediately_after_write: None,
        execute_after_write_data_history_version_processing: None,
    })
}

fn parse_document_fill_value(
    value: &str,
    value_types: &[ConstantValueType],
    type_index: &BTreeMap<String, String>,
    object_refs: &BTreeMap<String, String>,
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<MetadataChildFillValue> {
    if let Some(value) = parse_information_register_fill_value(value, type_index, object_refs) {
        return Some(value);
    }
    let (owner_uuid, value_uuid) = parse_information_register_design_time_ref_ids(value)?;
    if information_register_uuid_is_zero(&owner_uuid)
        || information_register_uuid_is_zero(&value_uuid)
    {
        return None;
    }
    let owner_type = type_index.get(&owner_uuid)?;
    let owner = parse_generated_metadata_reference_owner(owner_type)?;
    if owner.kind() != GeneratedMetadataReferenceOwnerKind::Enum {
        return None;
    }
    if !matches!(
        value_types,
        [ConstantValueType::Reference { reference }] if reference == owner_type
    ) {
        return None;
    }
    if object_refs.contains_key(&owner_uuid)
        || object_refs.contains_key(&value_uuid)
        || object_refs.keys().any(|key| {
            metadata_owner_value_reference_key_parts(key)
                .is_some_and(|(_, candidate)| candidate == value_uuid)
        })
        || type_index.contains_key(&value_uuid)
        || form_refs.contains_key(&value_uuid)
    {
        return None;
    }
    Some(MetadataChildFillValue::DesignTimeRef(format!(
        "{owner_uuid}.{value_uuid}"
    )))
}

fn parse_document_attribute_wrapper_fields<'a>(
    fields: &[&'a str],
    expected_child_uuid: Option<&str>,
) -> Option<(Vec<&'a str>, Vec<&'a str>, u32, String)> {
    let wrapper_code = fields.first()?.trim().parse::<u32>().ok()?;
    // 3 and 6 are the successor codes of 2 and 5: they carry the same slots and
    // append the reserved `0` plus the reserved pair. 6 is what a Document
    // writes for a direct attribute, and 3 is what a BusinessProcess writes -
    // all 81 direct attributes of all seven business processes of UT
    // 11.5.27.75 use it, while the collection reader demanded 2, so no
    // BusinessProcess had ever been decoded. `standalone_child_reference`
    // already reads the same code 3 wrapper for its attribute references.
    let expected_len = match wrapper_code {
        2 | 5 | 8 => 5,
        3 | 6 => 7,
        _ => return None,
    };
    if fields.len() != expected_len {
        return None;
    }
    let (payload, child_uuid) = parse_metadata_code27_payload(fields.get(1)?.trim())?;
    if expected_child_uuid.is_some_and(|expected| !child_uuid.eq_ignore_ascii_case(expected)) {
        return None;
    }
    metadata_attribute_indexing_xml(fields.get(2)?.trim())?;
    register_child_full_text_search_xml(fields.get(3)?.trim())?;
    metadata_data_history_xml(fields.get(4)?.trim())?;
    if matches!(wrapper_code, 3 | 6)
        && (fields.get(5)?.trim() != "0" || !metadata_reserved_wrapper_tail(fields.get(6)?))
    {
        return None;
    }
    Some((payload, fields.to_vec(), wrapper_code, child_uuid))
}

fn document_attribute_collection_is_closed(
    fields: &[&str],
    child_uuid: &str,
    expected_wrapper_code: u32,
) -> bool {
    let expected_marker = if expected_wrapper_code == 8 {
        DOCUMENT_TABULAR_ATTRIBUTE_GROUP_UUID
    } else if matches!(expected_wrapper_code, 5 | 6) {
        DOCUMENT_ATTRIBUTE_GROUP_UUID
    } else {
        return false;
    };
    if fields.len() < 3
        || !parse_uuid_field(fields[0].trim())
            .is_some_and(|marker| marker.eq_ignore_ascii_case(expected_marker))
    {
        return false;
    }
    let Some(count) = fields[1].trim().parse::<usize>().ok() else {
        return false;
    };
    if count == 0 || count.checked_add(2) != Some(fields.len()) {
        return false;
    }
    let mut child_occurrences = 0usize;
    for item_field in fields.iter().skip(2) {
        let Some(item) = split_1c_braced_fields(item_field.trim(), 0) else {
            return false;
        };
        if item.len() != 2 || item[1].trim() != "0" {
            return false;
        }
        let Some(wrapper) = split_1c_braced_fields(item[0].trim(), 0) else {
            return false;
        };
        let Some((_, _, wrapper_code, item_child_uuid)) =
            parse_document_attribute_wrapper_fields(&wrapper, None)
        else {
            return false;
        };
        if wrapper_code != expected_wrapper_code {
            return false;
        }
        if item_child_uuid.eq_ignore_ascii_case(child_uuid) {
            child_occurrences += 1;
        }
    }
    child_occurrences == 1
}

fn parse_document_child_choice_form(
    value: &str,
    value_types: &[ConstantValueType],
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<MetadataChoiceForm> {
    let uuid = parse_uuid_field(value.trim())?;
    if information_register_uuid_is_zero(&uuid) {
        return Some(MetadataChoiceForm::Empty);
    }
    let reference = information_register_form_reference(&uuid, form_refs)?;
    let (form_owner_reference, form_name) = reference.split_once(".Form.")?;
    if form_name.is_empty() || form_name.contains('.') {
        return None;
    }
    (value_types
        .iter()
        .filter(|value_type| {
            matches!(
                value_type,
                ConstantValueType::Reference { reference }
                    if parse_generated_metadata_reference_owner(reference).is_some_and(|owner| {
                        matches!(
                            owner.kind(),
                            GeneratedMetadataReferenceOwnerKind::Catalog
                                | GeneratedMetadataReferenceOwnerKind::Document
                        ) && owner.owner_reference() == form_owner_reference
                    })
            )
        })
        .count()
        == 1)
        .then_some(MetadataChoiceForm::Reference(reference))
}

fn parse_document_choice_parameter_links(
    value: &str,
    owner_name: &str,
    nested: bool,
    object_refs: &BTreeMap<String, String>,
    data_path_owner_proof: &DocumentDataPathOwnerProof,
) -> Option<Vec<MetadataChoiceParameterLink>> {
    let fields = split_1c_braced_fields(value.trim(), 0)?;
    if fields.len() < 2 || fields.first()?.trim() != "5006" {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    let minimum_len = count.checked_mul(4)?.checked_add(2)?;
    if fields.len() < minimum_len {
        return None;
    }
    let mut links = Vec::with_capacity(count);
    let mut index = 2usize;
    for _ in 0..count {
        let name = parse_1c_quoted_string(fields.get(index)?.trim())?;
        index = index.checked_add(1)?;
        let path_count = fields.get(index)?.trim().parse::<usize>().ok()?;
        index = index.checked_add(1)?;
        if if nested {
            !matches!(path_count, 1 | 2)
        } else {
            path_count != 1
        } {
            return None;
        }
        let path_end = index.checked_add(path_count)?;
        if path_end >= fields.len() {
            return None;
        }
        let data_path = resolve_document_data_path(
            fields.get(index..path_end)?,
            owner_name,
            object_refs,
            data_path_owner_proof,
            true,
        )?;
        index = path_end;
        let value_change = match fields.get(index)?.trim() {
            "0" => "Clear",
            "1" => "DontChange",
            _ => return None,
        };
        index = index.checked_add(1)?;
        links.push(MetadataChoiceParameterLink {
            name,
            data_path,
            value_change,
        });
    }
    (index == fields.len()).then_some(links)
}

fn parse_document_link_by_type(
    value: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
    data_path_owner_proof: &DocumentDataPathOwnerProof,
) -> Option<(bool, Option<MetadataChildLinkByType>)> {
    let fields = split_1c_braced_fields(value.trim(), 0)?;
    if fields.len() < 3 || fields.first()?.trim() != "3" {
        return None;
    }
    let path_count = fields.get(1)?.trim().parse::<usize>().ok()?;
    if path_count.checked_add(3) != Some(fields.len()) {
        return None;
    }
    let link_item = fields.last()?.trim().parse::<u32>().ok()?;
    if link_item > 3 {
        return None;
    }
    if path_count == 0 {
        return (link_item == 0).then_some((true, None));
    }
    if !matches!(path_count, 1 | 2) {
        return None;
    }
    let path_end = 2usize.checked_add(path_count)?;
    let data_path = resolve_document_data_path(
        fields.get(2..path_end)?,
        owner_name,
        object_refs,
        data_path_owner_proof,
        false,
    )?;
    Some((
        false,
        Some(MetadataChildLinkByType {
            data_path,
            link_item,
        }),
    ))
}

fn resolve_document_data_path(
    fields: &[&str],
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
    data_path_owner_proof: &DocumentDataPathOwnerProof,
    allow_raw_fallback: bool,
) -> Option<String> {
    match fields {
        [field] => {
            let segment = split_1c_braced_fields(field.trim(), 0)?;
            match segment.as_slice() {
                [code] if code.trim() == "-3" => {
                    Some(format!("Document.{owner_name}.StandardAttribute.Date"))
                }
                [code] if code.trim() == "-5" => {
                    Some(format!("Document.{owner_name}.StandardAttribute.Ref"))
                }
                [code] if allow_raw_fallback && matches!(code.trim(), "-8" | "0") => {
                    Some(code.trim().to_string())
                }
                [kind, uuid] if kind.trim() == "0" => {
                    let uuid = parse_uuid_field(uuid.trim())?;
                    match (
                        data_path_owner_proof.entries.get(&uuid),
                        object_refs.get(&uuid),
                    ) {
                        (Some(entry), Some(reference))
                            if entry.role == DocumentDataPathOwnerRole::DirectAttribute
                                && reference == &entry.reference =>
                        {
                            Some(entry.reference.clone())
                        }
                        (None, reference)
                            if allow_raw_fallback
                                && !data_path_owner_proof.ambiguous.contains(&uuid)
                                && reference.is_none_or(|reference| {
                                    !document_data_path_reference_belongs_to_owner(
                                        reference, owner_name,
                                    )
                                }) =>
                        {
                            Some(format!("0:{uuid}"))
                        }
                        _ => None,
                    }
                }
                _ => None,
            }
        }
        [parent, child] => {
            let parent = split_1c_braced_fields(parent.trim(), 0)?;
            let child = split_1c_braced_fields(child.trim(), 0)?;
            if allow_raw_fallback
                && matches!(parent.as_slice(), [code] if code.trim() == "0")
                && matches!(child.as_slice(), [code] if code.trim() == "0")
            {
                return Some("0/0".to_string());
            }
            let (parent_uuid, child_uuid) = match (parent.as_slice(), child.as_slice()) {
                ([parent_kind, parent_uuid], [child_kind, child_uuid])
                    if parent_kind.trim() == "0" && child_kind.trim() == "0" =>
                {
                    (
                        parse_uuid_field(parent_uuid.trim())?,
                        parse_uuid_field(child_uuid.trim())?,
                    )
                }
                _ => return None,
            };
            match (
                data_path_owner_proof.entries.get(&parent_uuid),
                object_refs.get(&parent_uuid),
                data_path_owner_proof.entries.get(&child_uuid),
                object_refs.get(&child_uuid),
            ) {
                (
                    Some(parent_entry),
                    Some(parent_reference),
                    Some(child_entry),
                    Some(child_reference),
                ) if parent_entry.role == DocumentDataPathOwnerRole::TabularSection
                    && child_entry.role
                        == (DocumentDataPathOwnerRole::TabularAttribute {
                            parent_uuid: parent_uuid.clone(),
                        })
                    && parent_reference == &parent_entry.reference
                    && child_reference == &child_entry.reference =>
                {
                    Some(child_entry.reference.clone())
                }
                (None, parent_reference, None, child_reference)
                    if allow_raw_fallback
                        && !data_path_owner_proof.ambiguous.contains(&parent_uuid)
                        && !data_path_owner_proof.ambiguous.contains(&child_uuid)
                        && [parent_reference, child_reference]
                            .into_iter()
                            .all(|reference| {
                                reference.is_none_or(|reference| {
                                    !document_data_path_reference_belongs_to_owner(
                                        reference, owner_name,
                                    )
                                })
                            }) =>
                {
                    Some(format!("0:{parent_uuid}/0:{child_uuid}"))
                }
                _ => None,
            }
        }
        _ => None,
    }
}

fn document_data_path_reference_belongs_to_owner(reference: &str, owner_name: &str) -> bool {
    let owner_reference = format!("Document.{owner_name}");
    reference == owner_reference || reference.starts_with(&format!("{owner_reference}."))
}

fn parse_metadata_child_localized_value(value: &str) -> Option<Vec<(String, String)>> {
    let values = parse_information_register_localized_value(value)?;
    let mut languages = BTreeSet::new();
    values
        .iter()
        .all(|(language, _)| languages.insert(language))
        .then_some(values)
}

fn parse_catalog_child_choice_form(
    value: &str,
    value_types: &[ConstantValueType],
    form_refs: &BTreeMap<String, FormSourceReference>,
) -> Option<MetadataChoiceForm> {
    let uuid = parse_uuid_field(value.trim())?;
    let choice_form = if information_register_uuid_is_zero(&uuid) {
        MetadataChoiceForm::Empty
    } else {
        MetadataChoiceForm::Reference(information_register_form_reference(&uuid, form_refs)?)
    };
    let MetadataChoiceForm::Reference(reference) = &choice_form else {
        return Some(choice_form);
    };
    let owner_name = catalog_choice_form_owner_name(reference)?;
    (value_types
        .iter()
        .filter(|value_type| {
            matches!(
                value_type,
                ConstantValueType::Reference { reference }
                    if parse_generated_metadata_reference_owner(reference).is_some_and(|owner| {
                        owner.kind() == GeneratedMetadataReferenceOwnerKind::Catalog
                            && owner.name() == owner_name
                    })
            )
        })
        .count()
        == 1)
        .then_some(choice_form)
}

fn catalog_choice_form_owner_name(reference: &str) -> Option<&str> {
    let (owner_name, form_name) = reference.strip_prefix("Catalog.")?.split_once(".Form.")?;
    (!owner_name.is_empty()
        && !owner_name.contains('.')
        && !form_name.is_empty()
        && !form_name.contains('.'))
    .then_some(owner_name)
}

fn parse_catalog_choice_parameter_links(
    value: &str,
    owner_name: &str,
    nested: bool,
    object_refs: &BTreeMap<String, String>,
) -> Option<Vec<MetadataChoiceParameterLink>> {
    parse_owner_choice_parameter_links(value, "Catalog", owner_name, nested, object_refs)
}

/// One reader for the `5006` choice-parameter-link record. The owner kind only
/// selects which reference prefix the resolved data paths must sit under and
/// which negative standard-attribute codes are admitted.
fn parse_owner_choice_parameter_links(
    value: &str,
    owner_kind: &str,
    owner_name: &str,
    nested: bool,
    object_refs: &BTreeMap<String, String>,
) -> Option<Vec<MetadataChoiceParameterLink>> {
    let fields = split_1c_braced_fields(value.trim(), 0)?;
    if fields.len() < 2 || fields.first()?.trim() != "5006" {
        return None;
    }
    let count = fields.get(1)?.trim().parse::<usize>().ok()?;
    let minimum_len = count.checked_mul(4)?.checked_add(2)?;
    if fields.len() < minimum_len {
        return None;
    }
    let mut links = Vec::with_capacity(count);
    let mut index = 2usize;
    for _ in 0..count {
        let name = parse_1c_quoted_string(fields.get(index)?.trim())?;
        index = index.checked_add(1)?;
        let path_count = fields.get(index)?.trim().parse::<usize>().ok()?;
        index = index.checked_add(1)?;
        if if nested {
            !matches!(path_count, 1 | 2)
        } else {
            path_count != 1
        } {
            return None;
        }
        let path_end = index.checked_add(path_count)?;
        if path_end >= fields.len() {
            return None;
        }
        let data_path = resolve_owner_data_path(
            &fields[index..path_end],
            owner_kind,
            owner_name,
            object_refs,
        )?;
        index = path_end;
        let value_change = match fields.get(index)?.trim() {
            "0" => "Clear",
            "1" => "DontChange",
            _ => return None,
        };
        index = index.checked_add(1)?;
        links.push(MetadataChoiceParameterLink {
            name,
            data_path,
            value_change,
        });
    }
    (index == fields.len()).then_some(links)
}

fn parse_catalog_standard_attribute_choice_parameter_links(
    value: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<Vec<MetadataChoiceParameterLink>> {
    let fields = split_information_register_braced_fields(value)?;
    if fields.len() != 3
        || fields.first()?.trim() != r##""#""##
        || !information_register_uuid_matches(
            fields.get(1)?,
            INFORMATION_REGISTER_STANDARD_ATTRIBUTE_CHOICE_PARAMETER_LINKS_UUID,
        )
    {
        return None;
    }
    let links =
        parse_catalog_choice_parameter_links(fields.get(2)?, owner_name, false, object_refs)?;
    links
        .iter()
        .all(|link| link.value_change == "Clear")
        .then_some(links)
}

fn parse_catalog_link_by_type(
    value: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<(bool, Option<MetadataChildLinkByType>)> {
    let fields = split_1c_braced_fields(value.trim(), 0)?;
    if fields.len() < 3 || fields.first()?.trim() != "3" {
        return None;
    }
    let path_count = fields.get(1)?.trim().parse::<usize>().ok()?;
    if path_count.checked_add(3) != Some(fields.len()) {
        return None;
    }
    let link_item = fields.last()?.trim().parse::<u32>().ok()?;
    if link_item > 3 {
        return None;
    }
    if path_count == 0 {
        return (link_item == 0).then_some((true, None));
    }
    let path_end = 2usize.checked_add(path_count)?;
    let data_path = resolve_catalog_data_path(&fields[2..path_end], owner_name, object_refs)?;
    Some((
        false,
        Some(MetadataChildLinkByType {
            data_path,
            link_item,
        }),
    ))
}

fn resolve_catalog_data_path(
    fields: &[&str],
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    resolve_owner_data_path(fields, "Catalog", owner_name, object_refs)
}

fn resolve_owner_data_path(
    fields: &[&str],
    owner_kind: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let owner_prefix = format!("{owner_kind}.{owner_name}.");
    let mut resolved = Vec::with_capacity(fields.len());
    for field in fields {
        let path = resolve_owner_data_path_segment(field, owner_kind, owner_name, object_refs)?;
        if !path.starts_with(&owner_prefix) {
            return None;
        }
        if let Some(parent) = resolved.last()
            && !path.starts_with(&format!("{parent}."))
        {
            return None;
        }
        resolved.push(path);
    }
    resolved.pop()
}

/// The negative codes name standard attributes, and the table that maps them is
/// a property of the owner family. Only the catalog table is evidenced, so any
/// other family refuses a bare code and admits only resolved child references.
fn owner_data_path_standard_attribute(owner_kind: &str, code: &str) -> Option<&'static str> {
    if owner_kind != "Catalog" {
        return None;
    }
    match code {
        "-3" => Some("Description"),
        "-4" => Some("Parent"),
        "-5" => Some("Owner"),
        "-8" => Some("Ref"),
        _ => None,
    }
}

fn resolve_owner_data_path_segment(
    value: &str,
    owner_kind: &str,
    owner_name: &str,
    object_refs: &BTreeMap<String, String>,
) -> Option<String> {
    let fields = split_1c_braced_fields(value.trim(), 0)?;
    match fields.as_slice() {
        [code] => {
            let standard_attribute = owner_data_path_standard_attribute(owner_kind, code.trim())?;
            Some(format!(
                "{owner_kind}.{owner_name}.StandardAttribute.{standard_attribute}"
            ))
        }
        [kind, uuid] if kind.trim() == "0" => {
            let uuid = parse_uuid_field(uuid.trim())?;
            object_refs.get(&uuid).cloned()
        }
        _ => None,
    }
}

fn catalog_choice_folders_and_items_xml(value: &str) -> Option<&'static str> {
    match value {
        "0" => Some("Items"),
        "1" => Some("Folders"),
        "2" => Some("FoldersAndItems"),
        _ => None,
    }
}

