/// Member-presence bits of a referenced-font style descriptor.
///
/// A `kind != 0` style font is serialized as
/// `{7, <kind>, <member mask>, <ref>, <members...>, <reserved>, <scale>}`:
/// only the members the mask declares are present, in ascending bit order,
/// and the platform's own export writes exactly those attributes, no others.
///
/// Confirmed by decoding all 406 StyleItems of 1C:Trade Management 11.5.27.75
/// against their native export: 129 are fonts, 87 of them referenced, and
/// those carry the masks 0, 2, 6, 8, 16, 20, 32, 60, 62 and 574. Every one
/// reproduces its native `<Value xsi:type="v8ui:Font" .../>` attribute set
/// exactly under this rule.
/// Bit 1 (the face name, which the `Absolute` layout keeps in its own fixed
/// slot) is never set on a referenced font there, and bit 512 - observed only
/// alongside the dense masks - consumes no member slot.
///
/// The previous decoder inferred the member set from the tuple's arity. That
/// only happens to agree for the dense masks; it silently mislabeled sparse
/// ones, reading a strikeout member as `underline` (mask 32), an italic
/// member as `underline` (mask 8), and dropping height and weight outright
/// (mask 6).
const STYLE_FONT_MEMBER_HEIGHT: u32 = 2;
const STYLE_FONT_MEMBER_WEIGHT: u32 = 4;
const STYLE_FONT_MEMBER_ITALIC: u32 = 8;
const STYLE_FONT_MEMBER_UNDERLINE: u32 = 16;
const STYLE_FONT_MEMBER_STRIKEOUT: u32 = 32;
const STYLE_FONT_DEFAULT_WEIGHT: i32 = 400;
const STYLE_FONT_BOLD_WEIGHT: i32 = 700;
const STYLE_FONT_DEFAULT_SCALE: &str = "100";

/// Reads the member the mask declares at `cursor`, advancing it only when
/// that member is actually present.
fn style_font_member<'a>(
    font_fields: &[&'a str],
    mask: u32,
    bit: u32,
    cursor: &mut usize,
) -> Option<&'a str> {
    if mask & bit == 0 {
        return None;
    }
    let value = font_fields.get(*cursor).map(|field| field.trim());
    *cursor = cursor.saturating_add(1);
    value
}

fn parse_style_font_value_xml(value: &str) -> String {
    let fields = split_1c_braced_fields(value, 0).unwrap_or_default();
    let font_fields = fields
        .get(3)
        .and_then(|field| split_1c_braced_fields(field, 0))
        .unwrap_or_default();
    let kind = font_fields.get(1).map(|field| field.trim()).unwrap_or("0");
    let mut attrs = Vec::<(&str, String)>::new();
    let kind_xml;
    let scale;
    if kind == "0" {
        // The absolute layout is a complete fixed record rather than a packed
        // member list: the platform writes all of its slots (mask 575 on all
        // 42 absolute StyleItems of the reference configuration) and the
        // native export writes all four flags.
        kind_xml = "Absolute";
        attrs.push((
            "faceName",
            font_fields
                .get(16)
                .and_then(|field| parse_1c_quoted_string(field.trim()))
                .unwrap_or_else(|| "Arial".to_string()),
        ));
        if let Some(height) = font_height_xml(font_fields.get(3).map(|field| field.trim())) {
            attrs.push(("height", height));
        }
        let weight = font_fields
            .get(7)
            .and_then(|field| field.trim().parse::<i32>().ok())
            .unwrap_or(STYLE_FONT_DEFAULT_WEIGHT);
        attrs.push((
            "bold",
            xml_bool(weight >= STYLE_FONT_BOLD_WEIGHT).to_string(),
        ));
        for (index, name) in [(8usize, "italic"), (9, "underline"), (10, "strikeout")] {
            let flag = font_fields
                .get(index)
                .and_then(|field| parse_1c_bool_flag(field.trim()))
                .unwrap_or(false);
            attrs.push((name, xml_bool(flag).to_string()));
        }
        scale = font_fields
            .get(18)
            .map(|field| field.trim())
            .unwrap_or(STYLE_FONT_DEFAULT_SCALE)
            .to_string();
    } else {
        if kind == "1" {
            kind_xml = "WindowsFont";
            attrs.push(("ref", "sys:DefaultGUIFont".to_string()));
        } else {
            kind_xml = "StyleItem";
            let raw = font_fields.get(3).copied().unwrap_or("{0}");
            let raw_fields = split_1c_braced_fields(raw, 0).unwrap_or_default();
            if let Some(code) = raw_fields
                .first()
                .and_then(|field| field.trim().parse::<i32>().ok())
                && let Some((_, name)) = standard_style_item_for_code(code)
            {
                attrs.push(("ref", format!("style:{name}")));
            }
        }
        let mask = font_fields
            .get(2)
            .and_then(|field| field.trim().parse::<u32>().ok())
            .unwrap_or(0);
        let mut cursor = 4usize;
        if let Some(height) =
            style_font_member(&font_fields, mask, STYLE_FONT_MEMBER_HEIGHT, &mut cursor)
            && let Some(height) = font_height_xml(Some(height))
        {
            attrs.push(("height", height));
        }
        if let Some(weight) =
            style_font_member(&font_fields, mask, STYLE_FONT_MEMBER_WEIGHT, &mut cursor)
        {
            let weight = weight.parse::<i32>().unwrap_or(STYLE_FONT_DEFAULT_WEIGHT);
            attrs.push((
                "bold",
                xml_bool(weight >= STYLE_FONT_BOLD_WEIGHT).to_string(),
            ));
        }
        for (bit, name) in [
            (STYLE_FONT_MEMBER_ITALIC, "italic"),
            (STYLE_FONT_MEMBER_UNDERLINE, "underline"),
            (STYLE_FONT_MEMBER_STRIKEOUT, "strikeout"),
        ] {
            if let Some(raw) = style_font_member(&font_fields, mask, bit, &mut cursor) {
                let flag = parse_1c_bool_flag(raw).unwrap_or(false);
                attrs.push((name, xml_bool(flag).to_string()));
            }
        }
        scale = font_fields
            .get(cursor.saturating_add(1))
            .map(|field| field.trim())
            .unwrap_or(STYLE_FONT_DEFAULT_SCALE)
            .to_string();
    }
    attrs.push(("kind", kind_xml.to_string()));
    if scale != STYLE_FONT_DEFAULT_SCALE || kind == "0" {
        attrs.push(("scale", scale));
    }

    let mut xml = String::from("<Value xsi:type=\"v8ui:Font\"");
    for (name, value) in attrs {
        xml.push_str(&format!(" {name}=\"{}\"", escape_xml_text(&value)));
    }
    xml.push_str("/>");
    xml
}

fn font_height_xml(raw: Option<&str>) -> Option<String> {
    let value = raw?.parse::<i32>().ok()?;
    let height = value / 10;
    if height == 0 {
        return None;
    }
    Some(height.to_string())
}

fn parse_metadata_type_pattern(
    value: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    parse_metadata_type_pattern_with_builtin(value, type_index, builtin_type_reference)
}

fn parse_form_metadata_type_pattern(
    value: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<Vec<ConstantValueType>> {
    parse_metadata_type_pattern_with_builtin(value, type_index, form_builtin_type_reference)
}

fn parse_metadata_type_pattern_with_builtin(
    value: &str,
    type_index: &BTreeMap<String, String>,
    builtin_reference: fn(&str) -> Option<&'static str>,
) -> Option<Vec<ConstantValueType>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.first()?.trim() != r#""Pattern""# {
        return None;
    }
    fields
        .iter()
        .skip(1)
        .map(|field| {
            parse_metadata_type_pattern_element_with_builtin(field, type_index, builtin_reference)
        })
        .collect()
}

fn parse_event_subscription_type_pattern(
    value: &str,
    type_index: &BTreeMap<String, String>,
    event: &str,
) -> Option<Vec<ConstantValueType>> {
    let fields = split_1c_braced_fields(value, 0)?;
    if fields.first()?.trim() != r#""Pattern""# {
        return None;
    }
    let type_ids = fields
        .iter()
        .skip(1)
        .map(|field| metadata_type_pattern_field_type_id(field))
        .collect::<Option<Vec<_>>>()?;
    fields
        .iter()
        .skip(1)
        .map(|field| {
            parse_event_subscription_type_pattern_element(field, type_index, event, &type_ids)
        })
        .collect()
}

fn parse_event_subscription_type_pattern_element(
    value: &str,
    type_index: &BTreeMap<String, String>,
    event: &str,
    pattern_type_ids: &[String],
) -> Option<ConstantValueType> {
    let element = split_1c_braced_fields(value, 0)?;
    if element.first()?.trim() == r##""#""## && element.len() >= 2 {
        let type_id = parse_uuid_field(element.get(1)?.trim())?;
        let reference = type_index
            .get(&type_id)
            .cloned()
            .or_else(|| {
                event_subscription_builtin_type_reference(event, pattern_type_ids, &type_id)
                    .map(ToOwned::to_owned)
            })
            .or_else(|| builtin_type_reference(&type_id).map(ToOwned::to_owned))?;
        return Some(ConstantValueType::Reference { reference });
    }
    parse_metadata_type_pattern_element(value, type_index)
}

fn parse_metadata_type_pattern_element(
    value: &str,
    type_index: &BTreeMap<String, String>,
) -> Option<ConstantValueType> {
    parse_metadata_type_pattern_element_with_builtin(value, type_index, builtin_type_reference)
}

fn parse_metadata_type_pattern_element_with_builtin(
    value: &str,
    type_index: &BTreeMap<String, String>,
    builtin_reference: fn(&str) -> Option<&'static str>,
) -> Option<ConstantValueType> {
    let element = split_1c_braced_fields(value, 0)?;
    match element.first()?.trim() {
        r#""B""# => Some(ConstantValueType::Boolean),
        r#""S""# if element.len() == 1 => Some(ConstantValueType::String {
            length: None,
            // Same reasoning as `parse_information_register_type_pattern_element`
            // (mod.rs:~16260): the serializer already forces "Variable" when
            // `length` is `None`, so `1` is the value that matches actual
            // emitted output.
            allowed_length_flag: 1,
        }),
        r#""S""# if element.len() == 3 => Some(ConstantValueType::String {
            length: Some(element.get(1)?.trim().parse().ok()?),
            allowed_length_flag: element.get(2)?.trim().parse().ok()?,
        }),
        r#""N""# if element.len() == 1 => Some(ConstantValueType::Number {
            digits: 0,
            fraction_digits: 0,
            allowed_sign_flag: 0,
        }),
        r#""N""# if element.len() == 4 => Some(ConstantValueType::Number {
            digits: element.get(1)?.trim().parse().ok()?,
            fraction_digits: element.get(2)?.trim().parse().ok()?,
            allowed_sign_flag: element.get(3)?.trim().parse().ok()?,
        }),
        r#""D""# => Some(ConstantValueType::DateTime {
            date_fractions: match element.get(1).map(|field| field.trim()) {
                Some(r#""D""#) => "Date",
                Some(r#""T""#) => "Time",
                _ => "DateTime",
            },
        }),
        // `{"L"}` is the serialized form of the platform `Null` type. Every one
        // of the 15 `v8:Null` type entries the platform writes across the 12
        // carrying files of 1C:Trade Management 11.5.27.75 is a bare
        // `<v8:Type>v8:Null</v8:Type>` with no qualifier of its own and with
        // its pattern position preserved, so it parses as an ordinary
        // reference-shaped leaf.
        r#""L""# if element.len() == 1 => Some(ConstantValueType::Reference {
            reference: NULL_TYPE_REFERENCE.to_string(),
        }),
        r##""#""## if element.len() >= 2 => {
            let type_id = parse_uuid_field(element.get(1)?.trim())?;
            let reference = type_index
                .get(&type_id)
                .cloned()
                .or_else(|| builtin_reference(&type_id).map(ToOwned::to_owned))?;
            Some(ConstantValueType::Reference { reference })
        }
        _ => None,
    }
}

fn metadata_type_pattern_field_type_id(value: &str) -> Option<String> {
    let element = split_1c_braced_fields(value, 0)?;
    if element.first()?.trim() == r##""#""## && element.len() >= 2 {
        parse_uuid_field(element.get(1)?.trim())
    } else {
        Some(String::new())
    }
}

fn event_subscription_builtin_type_reference(
    event: &str,
    pattern_type_ids: &[String],
    type_id: &str,
) -> Option<&'static str> {
    if event == "FillCheckProcessing" {
        return match type_id {
            "3e63355c-1378-4953-be9b-1deb5fb6bec5" => Some("cfg:BusinessProcessObject"),
            _ => None,
        };
    }
    if pattern_type_ids.len() == 4
        && pattern_type_ids
            == [
                "238e7e88-3c5f-48b2-8a3b-81ebbecb20ed",
                "30b100d6-b29f-47ac-aec7-cb8ca8a54767",
                "82a1b659-b220-4d94-a9bd-14d757b95a48",
                "cf4abea6-37b2-11d4-940f-008048da11f9",
            ]
    {
        return match type_id {
            "238e7e88-3c5f-48b2-8a3b-81ebbecb20ed" => Some("cfg:ChartOfAccountsObject"),
            _ => None,
        };
    }
    if pattern_type_ids.len() == 1
        && pattern_type_ids.first().map(String::as_str)
            == Some("fcd3404e-1523-48ce-9bc0-ecdb822684a1")
        && matches!(event, "BeforeWrite" | "OnSetNewNumber")
    {
        return Some("cfg:BusinessProcessObject");
    }
    None
}

