fn parse_filter_criterion_properties_from_text(
    text: &str,
    expected_header: &MetadataHeader,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
    object_ref_resolutions: &BTreeMap<String, MetadataObjectReferenceResolution>,
    source_version: InfobaseConfigSourceVersion,
) -> std::result::Result<Option<FilterCriterionProperties>, FilterCriterionDecodeError> {
    let root_fields = split_information_register_braced_fields(text).ok_or_else(|| {
        FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Root,
            FilterCriterionDecodeReason::Shape,
        )
    })?;
    if !root_fields
        .first()
        .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::root(value.trim()))
    {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Root,
            FilterCriterionDecodeReason::Shape,
        ));
    }
    let Some(owner_fields) = root_fields
        .get(1)
        .and_then(|value| split_information_register_braced_fields(value))
    else {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Owner,
            FilterCriterionDecodeReason::Shape,
        ));
    };

    if root_fields.len() == 3
        && root_fields
            .get(2)
            .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::zero(value.trim()))
    {
        if filter_criterion_legacy_direct_header_is_valid(&owner_fields, expected_header)
            || filter_criterion_legacy_wrapped_header_is_valid(&owner_fields, expected_header)
        {
            return Ok(Some(FilterCriterionProperties::LegacyMinimal));
        }
        return Ok(None);
    }

    if source_version != InfobaseConfigSourceVersion::V2_20 {
        return Ok(None);
    }
    if root_fields.len() != 5
        || !root_fields
            .get(2)
            .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::two(value.trim()))
        || owner_fields.len() != 13
        || !owner_fields
            .first()
            .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::owner(value.trim()))
    {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Root,
            FilterCriterionDecodeReason::Shape,
        ));
    }

    let generated_ids = owner_fields[1..5]
        .iter()
        .map(|value| {
            parse_filter_criterion_uuid(value, FilterCriterionDecodeStage::Owner, None, None, true)
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let mut unique_generated_ids = BTreeSet::new();
    if !generated_ids
        .iter()
        .all(|uuid| unique_generated_ids.insert(uuid.to_ascii_lowercase()))
    {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Owner,
            FilterCriterionDecodeReason::DuplicateUuid,
        ));
    }

    let header_wrapper = owner_fields
        .get(5)
        .and_then(|value| split_information_register_braced_fields(value))
        .ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Owner,
                FilterCriterionDecodeReason::Shape,
            )
        })?;
    if header_wrapper.len() != 3
        || !header_wrapper
            .first()
            .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::two(value.trim()))
    {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Owner,
            FilterCriterionDecodeReason::Shape,
        ));
    }
    let parsed_header = header_wrapper
        .get(1)
        .and_then(|value| parse_information_register_owner_header(value))
        .ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Owner,
                FilterCriterionDecodeReason::Shape,
            )
        })?;
    if !filter_criterion_headers_match(&parsed_header, expected_header) {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Owner,
            FilterCriterionDecodeReason::HeaderMismatch,
        ));
    }
    let value_types = parse_filter_criterion_type_pattern(
        header_wrapper.get(2).ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Pattern,
                FilterCriterionDecodeReason::Shape,
            )
        })?,
        type_index,
        type_index_collisions,
    )?;
    let content = parse_filter_criterion_content(
        owner_fields.get(6).ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Content,
                FilterCriterionDecodeReason::Shape,
            )
        })?,
        object_ref_resolutions,
    )?;
    let use_standard_commands = owner_fields
        .get(7)
        .and_then(|value| parse_1c_bool_flag(value.trim()))
        .ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Owner,
                FilterCriterionDecodeReason::Shape,
            )
        })?;

    for index in [8usize, 9] {
        let uuid = parse_filter_criterion_uuid(
            owner_fields.get(index).ok_or_else(|| {
                FilterCriterionDecodeError::new(
                    FilterCriterionDecodeStage::Owner,
                    FilterCriterionDecodeReason::Shape,
                )
            })?,
            FilterCriterionDecodeStage::Owner,
            None,
            None,
            false,
        )?;
        if !information_register_uuid_is_zero(&uuid) {
            return Err(FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Owner,
                FilterCriterionDecodeReason::Shape,
            ));
        }
    }
    for index in [10usize, 11, 12] {
        let fields = owner_fields
            .get(index)
            .and_then(|value| split_information_register_braced_fields(value))
            .ok_or_else(|| {
                FilterCriterionDecodeError::new(
                    FilterCriterionDecodeStage::Owner,
                    FilterCriterionDecodeReason::Shape,
                )
            })?;
        if fields.len() != 1
            || !fields
                .first()
                .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::zero(value.trim()))
        {
            return Err(FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Owner,
                FilterCriterionDecodeReason::Shape,
            ));
        }
    }

    let first_collection =
        parse_filter_criterion_empty_collection(root_fields.get(3).ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Tail,
                FilterCriterionDecodeReason::Shape,
            )
        })?)?;
    let second_collection =
        parse_filter_criterion_empty_collection(root_fields.get(4).ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Tail,
                FilterCriterionDecodeReason::Shape,
            )
        })?)?;
    if first_collection.eq_ignore_ascii_case(&second_collection) {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Tail,
            FilterCriterionDecodeReason::DuplicateUuid,
        ));
    }

    Ok(Some(FilterCriterionProperties::StrictFull(
        FilterCriterionFullProperties {
            generated_types: vec![
                GeneratedTypeEntry {
                    name: format!("FilterCriterionManager.{}", expected_header.name),
                    category: "Manager",
                    type_id: generated_ids[0].clone(),
                    value_id: generated_ids[1].clone(),
                },
                GeneratedTypeEntry {
                    name: format!("FilterCriterionList.{}", expected_header.name),
                    category: "List",
                    type_id: generated_ids[2].clone(),
                    value_id: generated_ids[3].clone(),
                },
            ],
            value_types,
            use_standard_commands,
            content,
        },
    )))
}

fn filter_criterion_legacy_direct_header_is_valid(
    owner_fields: &[&str],
    expected_header: &MetadataHeader,
) -> bool {
    owner_fields.len() == 3
        && owner_fields
            .first()
            .is_some_and(|value| value.trim() == "14")
        && owner_fields.get(2).is_some_and(|value| value.trim() == "0")
        && owner_fields
            .get(1)
            .and_then(|value| parse_information_register_owner_header(value))
            .is_some_and(|header| filter_criterion_headers_match(&header, expected_header))
}

fn filter_criterion_legacy_wrapped_header_is_valid(
    owner_fields: &[&str],
    expected_header: &MetadataHeader,
) -> bool {
    if owner_fields.len() != 3
        || owner_fields
            .first()
            .is_none_or(|value| value.trim() != "14")
        || owner_fields
            .get(1)
            .and_then(|value| parse_information_register_non_zero_uuid(value))
            .is_none()
    {
        return false;
    }
    let Some(wrapper) = owner_fields
        .get(2)
        .and_then(|value| split_information_register_braced_fields(value))
    else {
        return false;
    };
    if wrapper.len() != 3 || wrapper.first().is_none_or(|value| value.trim() != "2") {
        return false;
    }
    let Some(header) = wrapper
        .get(1)
        .and_then(|value| parse_information_register_owner_header(value))
    else {
        return false;
    };
    let Some(pattern) = wrapper
        .get(2)
        .and_then(|value| split_information_register_braced_fields(value))
    else {
        return false;
    };
    filter_criterion_headers_match(&header, expected_header)
        && pattern.len() == 1
        && pattern
            .first()
            .is_some_and(|value| value.trim() == r#""Pattern""#)
}

fn filter_criterion_headers_match(left: &MetadataHeader, right: &MetadataHeader) -> bool {
    left.uuid.eq_ignore_ascii_case(&right.uuid)
        && left.name == right.name
        && left.synonyms == right.synonyms
        && left.comment == right.comment
}

fn parse_filter_criterion_type_pattern(
    value: &str,
    type_index: &BTreeMap<String, String>,
    type_index_collisions: &BTreeSet<String>,
) -> std::result::Result<Vec<ConstantValueType>, FilterCriterionDecodeError> {
    let fields = split_information_register_braced_fields(value).ok_or_else(|| {
        FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Pattern,
            FilterCriterionDecodeReason::Shape,
        )
    })?;
    if fields.len() < 2
        || !fields
            .first()
            .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::pattern(value.trim()))
    {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Pattern,
            FilterCriterionDecodeReason::Shape,
        ));
    }
    let mut ids = BTreeSet::new();
    let mut references = BTreeSet::new();
    let mut value_types = Vec::with_capacity(fields.len().saturating_sub(1));
    for (item_index, value) in fields.iter().skip(1).enumerate() {
        let member = split_information_register_braced_fields(value).ok_or_else(|| {
            FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Pattern,
                FilterCriterionDecodeReason::Shape,
                FilterCriterionCollectionRole::Pattern,
                item_index,
                None,
            )
        })?;
        if !member.first().is_some_and(|value| {
            owner_graph::FilterCriterionPhysicalSchema::reference_member(value.trim())
        }) {
            // A member that is not a design-time reference is a primitive type
            // written in the pattern dialect every other family already reads;
            // `СвязанныеДокументы` carries one (`{"S",10,1}`) among 218
            // reference members. Its qualifiers are printed by the shared type
            // writer, so only the reference bookkeeping is skipped here.
            let primitive =
                parse_metadata_type_pattern_element(value, type_index).filter(|value_type| {
                    !matches!(
                        value_type,
                        ConstantValueType::Reference { .. }
                            | ConstantValueType::ReferenceTypeSet { .. }
                    )
                });
            let Some(primitive) = primitive else {
                return Err(FilterCriterionDecodeError::item(
                    FilterCriterionDecodeStage::Pattern,
                    FilterCriterionDecodeReason::Shape,
                    FilterCriterionCollectionRole::Pattern,
                    item_index,
                    None,
                ));
            };
            if !references.insert(metadata_type_xml_name(&primitive).to_lowercase()) {
                return Err(FilterCriterionDecodeError::item(
                    FilterCriterionDecodeStage::Pattern,
                    FilterCriterionDecodeReason::DuplicateReference,
                    FilterCriterionCollectionRole::Pattern,
                    item_index,
                    None,
                ));
            }
            value_types.push(primitive);
            continue;
        }
        if member.len() != 2 {
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Pattern,
                FilterCriterionDecodeReason::Shape,
                FilterCriterionCollectionRole::Pattern,
                item_index,
                None,
            ));
        }
        let uuid = parse_filter_criterion_uuid(
            member.get(1).ok_or_else(|| {
                FilterCriterionDecodeError::item(
                    FilterCriterionDecodeStage::Pattern,
                    FilterCriterionDecodeReason::Shape,
                    FilterCriterionCollectionRole::Pattern,
                    item_index,
                    None,
                )
            })?,
            FilterCriterionDecodeStage::Pattern,
            Some(FilterCriterionCollectionRole::Pattern),
            Some(item_index),
            true,
        )?;
        if !ids.insert(uuid.to_ascii_lowercase()) {
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Pattern,
                FilterCriterionDecodeReason::DuplicateUuid,
                FilterCriterionCollectionRole::Pattern,
                item_index,
                Some(uuid),
            ));
        }
        let reference = resolve_filter_criterion_type_reference(
            type_index,
            type_index_collisions,
            &uuid,
            item_index,
        )?;
        if !filter_criterion_type_reference_is_valid(&reference)
            || !references.insert(reference.to_lowercase())
        {
            let reason = if filter_criterion_type_reference_is_valid(&reference) {
                FilterCriterionDecodeReason::DuplicateReference
            } else {
                FilterCriterionDecodeReason::InvalidReference
            };
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Resolver,
                reason,
                FilterCriterionCollectionRole::Pattern,
                item_index,
                Some(uuid),
            ));
        }
        value_types.push(ConstantValueType::Reference { reference });
    }
    Ok(value_types)
}

fn parse_filter_criterion_content(
    value: &str,
    object_ref_resolutions: &BTreeMap<String, MetadataObjectReferenceResolution>,
) -> std::result::Result<Vec<String>, FilterCriterionDecodeError> {
    let fields = split_information_register_braced_fields(value).ok_or_else(|| {
        FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Content,
            FilterCriterionDecodeReason::Shape,
        )
    })?;
    if fields.len() < 3
        || !fields
            .first()
            .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::zero(value.trim()))
    {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Content,
            FilterCriterionDecodeReason::Shape,
        ));
    }
    let count = fields
        .get(1)
        .and_then(|value| parse_information_register_usize(value))
        .ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Content,
                FilterCriterionDecodeReason::Count,
            )
        })?;
    if count.checked_add(2) != Some(fields.len()) {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Content,
            FilterCriterionDecodeReason::Count,
        ));
    }

    let mut ids = BTreeSet::new();
    let mut references = BTreeSet::new();
    let mut content = Vec::with_capacity(count);
    for (item_index, value) in fields.iter().skip(2).enumerate() {
        let member = split_information_register_braced_fields(value).ok_or_else(|| {
            FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Content,
                FilterCriterionDecodeReason::Shape,
                FilterCriterionCollectionRole::Content,
                item_index,
                None,
            )
        })?;
        let marker_is_valid = member
            .get(1)
            .and_then(|value| parse_information_register_uuid(value))
            .is_some_and(|uuid| uuid.eq_ignore_ascii_case(METADATA_OBJECT_REF_TYPE_UUID));
        if member.len() != 3
            || !member.first().is_some_and(|value| {
                owner_graph::FilterCriterionPhysicalSchema::reference_member(value.trim())
            })
            || !marker_is_valid
        {
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Content,
                FilterCriterionDecodeReason::Shape,
                FilterCriterionCollectionRole::Content,
                item_index,
                None,
            ));
        }
        let payload = member
            .get(2)
            .and_then(|value| split_information_register_braced_fields(value))
            .ok_or_else(|| {
                FilterCriterionDecodeError::item(
                    FilterCriterionDecodeStage::Content,
                    FilterCriterionDecodeReason::Shape,
                    FilterCriterionCollectionRole::Content,
                    item_index,
                    None,
                )
            })?;
        if payload.len() != 2
            || !payload
                .first()
                .is_some_and(|value| owner_graph::FilterCriterionPhysicalSchema::root(value.trim()))
        {
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Content,
                FilterCriterionDecodeReason::Shape,
                FilterCriterionCollectionRole::Content,
                item_index,
                None,
            ));
        }
        let uuid = parse_filter_criterion_uuid(
            payload.get(1).ok_or_else(|| {
                FilterCriterionDecodeError::item(
                    FilterCriterionDecodeStage::Content,
                    FilterCriterionDecodeReason::Shape,
                    FilterCriterionCollectionRole::Content,
                    item_index,
                    None,
                )
            })?,
            FilterCriterionDecodeStage::Content,
            Some(FilterCriterionCollectionRole::Content),
            Some(item_index),
            true,
        )?;
        if !ids.insert(uuid.to_ascii_lowercase()) {
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Content,
                FilterCriterionDecodeReason::DuplicateUuid,
                FilterCriterionCollectionRole::Content,
                item_index,
                Some(uuid),
            ));
        }
        let reference =
            resolve_filter_criterion_object_reference(object_ref_resolutions, &uuid, item_index)?;
        if !filter_criterion_content_reference_is_valid(&reference)
            || !references.insert(reference.to_lowercase())
        {
            let reason = if filter_criterion_content_reference_is_valid(&reference) {
                FilterCriterionDecodeReason::DuplicateReference
            } else {
                FilterCriterionDecodeReason::InvalidReference
            };
            return Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Resolver,
                reason,
                FilterCriterionCollectionRole::Content,
                item_index,
                Some(uuid),
            ));
        }
        content.push(reference);
    }
    Ok(content)
}

fn parse_filter_criterion_uuid(
    value: &str,
    stage: FilterCriterionDecodeStage,
    role: Option<FilterCriterionCollectionRole>,
    item_index: Option<usize>,
    non_zero: bool,
) -> std::result::Result<String, FilterCriterionDecodeError> {
    let uuid =
        parse_information_register_uuid(value).ok_or_else(|| FilterCriterionDecodeError {
            stage,
            reason: FilterCriterionDecodeReason::UuidSyntax,
            role,
            item_index,
            reference_uuid: None,
        })?;
    let uuid = uuid.to_ascii_lowercase();
    if non_zero && information_register_uuid_is_zero(&uuid) {
        return Err(FilterCriterionDecodeError {
            stage,
            reason: FilterCriterionDecodeReason::ZeroUuid,
            role,
            item_index,
            reference_uuid: Some(uuid),
        });
    }
    Ok(uuid)
}

fn resolve_filter_criterion_type_reference(
    index: &BTreeMap<String, String>,
    collisions: &BTreeSet<String>,
    uuid: &str,
    item_index: usize,
) -> std::result::Result<String, FilterCriterionDecodeError> {
    if collisions.contains(&uuid.to_ascii_lowercase()) {
        return Err(FilterCriterionDecodeError::item(
            FilterCriterionDecodeStage::Resolver,
            FilterCriterionDecodeReason::AmbiguousReference,
            FilterCriterionCollectionRole::Pattern,
            item_index,
            Some(uuid.to_string()),
        ));
    }
    let mut matches = index
        .iter()
        .filter(|(candidate, _)| candidate.eq_ignore_ascii_case(uuid));
    let Some((_, reference)) = matches.next() else {
        return Err(FilterCriterionDecodeError::item(
            FilterCriterionDecodeStage::Resolver,
            FilterCriterionDecodeReason::MissingReference,
            FilterCriterionCollectionRole::Pattern,
            item_index,
            Some(uuid.to_string()),
        ));
    };
    if matches.next().is_some() {
        return Err(FilterCriterionDecodeError::item(
            FilterCriterionDecodeStage::Resolver,
            FilterCriterionDecodeReason::AmbiguousReference,
            FilterCriterionCollectionRole::Pattern,
            item_index,
            Some(uuid.to_string()),
        ));
    }
    if reference.is_empty() {
        return Err(FilterCriterionDecodeError::item(
            FilterCriterionDecodeStage::Resolver,
            FilterCriterionDecodeReason::InvalidReference,
            FilterCriterionCollectionRole::Pattern,
            item_index,
            Some(uuid.to_string()),
        ));
    }
    Ok(reference.clone())
}

fn resolve_filter_criterion_object_reference(
    resolutions: &BTreeMap<String, MetadataObjectReferenceResolution>,
    uuid: &str,
    item_index: usize,
) -> std::result::Result<String, FilterCriterionDecodeError> {
    match resolutions.get(&uuid.to_ascii_lowercase()) {
        Some(MetadataObjectReferenceResolution::Unique(reference)) if !reference.is_empty() => {
            Ok(reference.clone())
        }
        Some(MetadataObjectReferenceResolution::Unique(_)) => {
            Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Resolver,
                FilterCriterionDecodeReason::InvalidReference,
                FilterCriterionCollectionRole::Content,
                item_index,
                Some(uuid.to_string()),
            ))
        }
        Some(MetadataObjectReferenceResolution::Ambiguous) => {
            Err(FilterCriterionDecodeError::item(
                FilterCriterionDecodeStage::Resolver,
                FilterCriterionDecodeReason::AmbiguousReference,
                FilterCriterionCollectionRole::Content,
                item_index,
                Some(uuid.to_string()),
            ))
        }
        None => Err(FilterCriterionDecodeError::item(
            FilterCriterionDecodeStage::Resolver,
            FilterCriterionDecodeReason::MissingReference,
            FilterCriterionCollectionRole::Content,
            item_index,
            Some(uuid.to_string()),
        )),
    }
}

fn filter_criterion_type_reference_is_valid(reference: &str) -> bool {
    parse_generated_metadata_reference_owner(reference).is_some()
}

fn filter_criterion_content_reference_is_valid(reference: &str) -> bool {
    let parts = reference.split('.').collect::<Vec<_>>();
    if parts.iter().any(|part| part.is_empty()) {
        return false;
    }
    matches!(parts.as_slice(), [_, _, "Attribute", _])
        || matches!(
            parts.as_slice(),
            [_, _, "TabularSection", _, "Attribute", _]
        )
}

fn parse_filter_criterion_empty_collection(
    value: &str,
) -> std::result::Result<String, FilterCriterionDecodeError> {
    let fields = split_information_register_braced_fields(value).ok_or_else(|| {
        FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Tail,
            FilterCriterionDecodeReason::Shape,
        )
    })?;
    let count = fields
        .get(1)
        .and_then(|value| parse_information_register_usize(value));
    if fields.len() != 2 || count != Some(0) {
        return Err(FilterCriterionDecodeError::new(
            FilterCriterionDecodeStage::Tail,
            FilterCriterionDecodeReason::Shape,
        ));
    }
    parse_filter_criterion_uuid(
        fields.first().ok_or_else(|| {
            FilterCriterionDecodeError::new(
                FilterCriterionDecodeStage::Tail,
                FilterCriterionDecodeReason::Shape,
            )
        })?,
        FilterCriterionDecodeStage::Tail,
        None,
        None,
        true,
    )
}

fn filter_criterion_extraction_diagnostic(
    error: FilterCriterionDecodeError,
) -> MetadataSourceExtractionDiagnostic {
    let mut diagnostic = MetadataSourceExtractionDiagnostic::new(
        error.reason.class(),
        "FilterCriterion",
        error.stage.token(),
        error.reason.token(),
    );
    diagnostic.item_index = error.item_index;
    diagnostic.collection_role = error.role.map(|role| role.token().to_string());
    diagnostic.reference_uuid = error.reference_uuid;
    diagnostic
}

fn format_filter_criterion_source_xml(
    header: &MetadataHeader,
    properties: &FilterCriterionProperties,
    source_version: InfobaseConfigSourceVersion,
) -> String {
    let mut xml = format_full_metadata_source_xml("FilterCriterion", header, source_version);
    let FilterCriterionProperties::StrictFull(properties) = properties else {
        insert_metadata_properties_xml(
            &mut xml,
            "\t\t\t<UseStandardCommands>true</UseStandardCommands>\r\n",
        );
        return xml;
    };

    let internal_info = format_generated_types_internal_info_xml(&properties.generated_types);
    if let Some(index) = xml.find("\t\t<Properties>\r\n") {
        xml.insert_str(index, &internal_info);
    }

    let mut insert = format_metadata_types_xml(&properties.value_types);
    insert.push_str(&format!(
        "\t\t\t<UseStandardCommands>{}</UseStandardCommands>\r\n",
        xml_bool(properties.use_standard_commands)
    ));
    insert.push_str("\t\t\t<Content>\r\n");
    for reference in &properties.content {
        insert.push_str(&format!(
            "\t\t\t\t<xr:Item xsi:type=\"xr:MDObjectRef\">{}</xr:Item>\r\n",
            escape_xml_element_text(reference)
        ));
    }
    insert.push_str("\t\t\t</Content>\r\n");
    insert.push_str(
        "\t\t\t<DefaultForm/>\r\n\
\t\t\t<AuxiliaryForm/>\r\n\
\t\t\t<ListPresentation/>\r\n\
\t\t\t<ExtendedListPresentation/>\r\n\
\t\t\t<Explanation/>\r\n",
    );
    insert_metadata_properties_xml(&mut xml, &insert);
    if let Some(index) = xml.find("\t</FilterCriterion>\r\n") {
        xml.insert_str(index, "\t\t<ChildObjects/>\r\n");
    }
    xml
}

fn insert_metadata_properties_xml(xml: &mut String, insert: &str) {
    let marker = "\t\t</Properties>\r\n";
    if let Some(index) = xml.find(marker) {
        xml.insert_str(index, insert);
    }
}

fn format_web_service_source_xml(
    header: &MetadataHeader,
    service: &WebServiceProperties,
    source_version: InfobaseConfigSourceVersion,
) -> String {
    let mut xml = format_full_metadata_source_xml("WebService", header, source_version);
    if source_version == InfobaseConfigSourceVersion::V2_21 {
        const STYLE_NAMESPACE_ATTRIBUTE: &str =
            " xmlns:style=\"http://v8.1c.ru/8.1/data/ui/style\"";
        const PALETTE_NAMESPACE_ATTRIBUTE: &str =
            " xmlns:pal=\"http://v8.1c.ru/8.1/data/ui/colors/palette\"";
        if let Some(style_index) = xml.find(STYLE_NAMESPACE_ATTRIBUTE) {
            xml.insert_str(style_index, PALETTE_NAMESPACE_ATTRIBUTE);
        }
    }
    let mut properties = String::new();
    push_web_service_text_property(&mut properties, "\t\t\t", "Namespace", &service.namespace);
    push_web_service_xdto_packages_xml(&mut properties, &service.xdto_packages);
    push_web_service_text_property(
        &mut properties,
        "\t\t\t",
        "DescriptorFileName",
        &service.descriptor_file_name,
    );
    properties.push_str(&format!(
        "\t\t\t<ReuseSessions>{}</ReuseSessions>\r\n\
\t\t\t<SessionMaxAge>{}</SessionMaxAge>\r\n",
        service.reuse_sessions, service.session_max_age
    ));
    insert_metadata_properties_xml(&mut xml, &properties);

    let child_objects = if service.operations.is_empty() {
        "\t\t<ChildObjects/>\r\n".to_string()
    } else {
        let mut child_objects = "\t\t<ChildObjects>\r\n".to_string();
        for operation in &service.operations {
            push_web_service_operation_xml(&mut child_objects, operation);
        }
        child_objects.push_str("\t\t</ChildObjects>\r\n");
        child_objects
    };
    if let Some(index) = xml.find("\t</WebService>\r\n") {
        xml.insert_str(index, &child_objects);
    }
    xml
}

fn push_web_service_xdto_packages_xml(xml: &mut String, packages: &[WebServiceXdtoPackage]) {
    if packages.is_empty() {
        xml.push_str("\t\t\t<XDTOPackages/>\r\n");
        return;
    }
    xml.push_str("\t\t\t<XDTOPackages>\r\n");
    for package in packages {
        let (value_type, value) = match package {
            WebServiceXdtoPackage::MetadataReference(reference) => {
                ("xr:MDObjectRef", reference.as_str())
            }
            WebServiceXdtoPackage::Namespace(namespace) => ("xs:string", namespace.as_str()),
        };
        xml.push_str(&format!(
            "\t\t\t\t<xr:Item>\r\n\
\t\t\t\t\t<xr:Presentation/>\r\n\
\t\t\t\t\t<xr:CheckState>0</xr:CheckState>\r\n\
\t\t\t\t\t<xr:Value xsi:type=\"{}\">{}</xr:Value>\r\n\
\t\t\t\t</xr:Item>\r\n",
            value_type,
            escape_xml_element_text(value)
        ));
    }
    xml.push_str("\t\t\t</XDTOPackages>\r\n");
}

fn push_web_service_operation_xml(xml: &mut String, operation: &WebServiceOperationProperties) {
    xml.push_str(&format!(
        "\t\t\t<Operation uuid=\"{}\">\r\n\
\t\t\t\t<Properties>\r\n",
        escape_xml_text(&operation.header.uuid)
    ));
    push_web_service_header_properties_xml(xml, "\t\t\t\t\t", &operation.header);
    push_web_service_xdto_type_xml(
        xml,
        "\t\t\t\t\t",
        "XDTOReturningValueType",
        &operation.returning_value_type,
        "d6p1",
    );
    xml.push_str(&format!(
        "\t\t\t\t\t<Nillable>{}</Nillable>\r\n\
\t\t\t\t\t<Transactioned>{}</Transactioned>\r\n",
        xml_bool(operation.nillable),
        xml_bool(operation.transactioned)
    ));
    push_web_service_text_property(
        xml,
        "\t\t\t\t\t",
        "ProcedureName",
        &operation.procedure_name,
    );
    xml.push_str(&format!(
        "\t\t\t\t\t<DataLockControlMode>{}</DataLockControlMode>\r\n\
\t\t\t\t</Properties>\r\n",
        operation.data_lock_control_mode
    ));
    if operation.parameters.is_empty() {
        xml.push_str("\t\t\t\t<ChildObjects/>\r\n");
    } else {
        xml.push_str("\t\t\t\t<ChildObjects>\r\n");
        for parameter in &operation.parameters {
            push_web_service_parameter_xml(xml, parameter);
        }
        xml.push_str("\t\t\t\t</ChildObjects>\r\n");
    }
    xml.push_str("\t\t\t</Operation>\r\n");
}

fn push_web_service_parameter_xml(xml: &mut String, parameter: &WebServiceParameterProperties) {
    xml.push_str(&format!(
        "\t\t\t\t\t<Parameter uuid=\"{}\">\r\n\
\t\t\t\t\t\t<Properties>\r\n",
        escape_xml_text(&parameter.header.uuid)
    ));
    push_web_service_header_properties_xml(xml, "\t\t\t\t\t\t\t", &parameter.header);
    push_web_service_xdto_type_xml(
        xml,
        "\t\t\t\t\t\t\t",
        "XDTOValueType",
        &parameter.value_type,
        "d8p1",
    );
    xml.push_str(&format!(
        "\t\t\t\t\t\t\t<Nillable>{}</Nillable>\r\n\
\t\t\t\t\t\t\t<TransferDirection>{}</TransferDirection>\r\n\
\t\t\t\t\t\t</Properties>\r\n\
\t\t\t\t\t</Parameter>\r\n",
        xml_bool(parameter.nillable),
        parameter.transfer_direction
    ));
}

fn push_web_service_header_properties_xml(xml: &mut String, indent: &str, header: &MetadataHeader) {
    xml.push_str(&format!(
        "{indent}<Name>{}</Name>\r\n",
        escape_xml_element_text(&header.name)
    ));
    push_header_synonym_xml(xml, indent, &header.synonyms);
    push_web_service_text_property(xml, indent, "Comment", &header.comment);
}

fn push_web_service_xdto_type_xml(
    xml: &mut String,
    indent: &str,
    tag: &str,
    value_type: &WebServiceXdtoType,
    custom_prefix: &str,
) {
    let (prefix, namespace_attribute) = match value_type.namespace.as_str() {
        XDTO_XML_SCHEMA_NAMESPACE => ("xs", None),
        XDTO_CORE_NAMESPACE => ("v8", None),
        namespace => (custom_prefix, Some(namespace)),
    };
    let namespace_attribute = namespace_attribute
        .map(|namespace| {
            format!(
                " xmlns:{}=\"{}\"",
                custom_prefix,
                escape_xml_text(namespace)
            )
        })
        .unwrap_or_default();
    xml.push_str(&format!(
        "{indent}<{tag}{namespace_attribute}>{prefix}:{}</{tag}>\r\n",
        escape_xml_element_text(&value_type.name)
    ));
}

fn push_web_service_text_property(xml: &mut String, indent: &str, tag: &str, value: &str) {
    if value.is_empty() {
        xml.push_str(&format!("{indent}<{tag}/>\r\n"));
    } else {
        xml.push_str(&format!(
            "{indent}<{tag}>{}</{tag}>\r\n",
            escape_xml_element_text(value)
        ));
    }
}

fn format_http_service_source_xml(
    header: &MetadataHeader,
    service: &HttpServiceProperties,
    source_version: InfobaseConfigSourceVersion,
) -> String {
    let mut xml = format_full_metadata_source_xml("HTTPService", header, source_version);
    let insert = format!(
        "\t\t\t<RootURL>{}</RootURL>\r\n\
\t\t\t<ReuseSessions>{}</ReuseSessions>\r\n\
\t\t\t<SessionMaxAge>{}</SessionMaxAge>\r\n",
        escape_xml_element_text(&service.root_url),
        escape_xml_text(service.reuse_sessions),
        service.session_max_age
    );
    let marker = "\t\t</Properties>\r\n";
    if let Some(index) = xml.find(marker) {
        xml.insert_str(index, &insert);
    }
    if !service.url_templates.is_empty() {
        let mut child_xml = "\t\t<ChildObjects>\r\n".to_string();
        for template in &service.url_templates {
            push_http_service_url_template_xml(&mut child_xml, template);
        }
        child_xml.push_str("\t\t</ChildObjects>\r\n");
        let owner_end = "\t</HTTPService>\r\n";
        if let Some(index) = xml.find(owner_end) {
            xml.insert_str(index, &child_xml);
        }
    }
    xml
}

fn push_http_service_url_template_xml(
    xml: &mut String,
    template: &HttpServiceUrlTemplateProperties,
) {
    xml.push_str(&format!(
        "\t\t\t<URLTemplate uuid=\"{}\">\r\n\
\t\t\t\t<Properties>\r\n\
\t\t\t\t\t<Name>{}</Name>\r\n",
        escape_xml_text(&template.header.uuid),
        escape_xml_element_text(&template.header.name)
    ));
    push_header_synonym_xml(xml, "\t\t\t\t\t", &template.header.synonyms);
    if template.header.comment.is_empty() {
        xml.push_str("\t\t\t\t\t<Comment/>\r\n");
    } else {
        xml.push_str(&format!(
            "\t\t\t\t\t<Comment>{}</Comment>\r\n",
            escape_xml_element_text(&template.header.comment)
        ));
    }
    xml.push_str(&format!(
        "\t\t\t\t\t<Template>{}</Template>\r\n\
\t\t\t\t</Properties>\r\n",
        escape_xml_element_text(&template.template)
    ));
    if !template.methods.is_empty() {
        xml.push_str("\t\t\t\t<ChildObjects>\r\n");
        for method in &template.methods {
            push_http_service_method_xml(xml, method);
        }
        xml.push_str("\t\t\t\t</ChildObjects>\r\n");
    }
    xml.push_str("\t\t\t</URLTemplate>\r\n");
}

fn push_http_service_method_xml(xml: &mut String, method: &HttpServiceMethodProperties) {
    xml.push_str(&format!(
        "\t\t\t\t\t<Method uuid=\"{}\">\r\n\
\t\t\t\t\t\t<Properties>\r\n\
\t\t\t\t\t\t\t<Name>{}</Name>\r\n",
        escape_xml_text(&method.header.uuid),
        escape_xml_element_text(&method.header.name)
    ));
    push_header_synonym_xml(xml, "\t\t\t\t\t\t\t", &method.header.synonyms);
    if method.header.comment.is_empty() {
        xml.push_str("\t\t\t\t\t\t\t<Comment/>\r\n");
    } else {
        xml.push_str(&format!(
            "\t\t\t\t\t\t\t<Comment>{}</Comment>\r\n",
            escape_xml_element_text(&method.header.comment)
        ));
    }
    xml.push_str(&format!(
        "\t\t\t\t\t\t\t<HTTPMethod>{}</HTTPMethod>\r\n\
\t\t\t\t\t\t\t<Handler>{}</Handler>\r\n\
\t\t\t\t\t\t</Properties>\r\n\
\t\t\t\t\t</Method>\r\n",
        escape_xml_element_text(&method.http_method),
        escape_xml_element_text(&method.handler)
    ));
}

